  IF (SELECT md5(content) FROM legal_articles WHERE "lawName" LIKE 'نظام التنفيذ%' AND "articleNumber"=1 LIMIT 1) <> '0c1443e1dcdf68c655856daa5d4188b5'
  OR (SELECT md5(content) FROM legal_articles WHERE "lawName"='نظام المعاملات المدنية' AND "articleNumber"=1 LIMIT 1) <> 'bb195018b612438b9d03d9c2b2ef80c4'
  THEN RAISE EXCEPTION 'guard md5 changed'; END IF; END $g$;
INSERT INTO unit_version (id,unit_id,body,valid_from,evidence_instrument,evidence_url,evidence_quote) VALUES
('boe26-953fd7aadc5794a1d74311fd','cmpz5u0qx00qjcwg26ewbykdq','( يجتمع  مجلس الإدارة  مرة كل ثلاثة أشهر، ويجوز عند الضرورة أن يجتمع أكثر من ذلك بدعوة من رئيسه، أو بناء على طلب أربعة من أعضائه أو من الأمين العام للدارة ).','1983-07-30'::timestamptz,'مرسوم ملكي رقم م/51 وتاريخ 20/10/1403هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0057fd8d-8ad4-48f9-b02f-a9a700f16a48/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/51) وتاريخ 20/ 10/ 1403هـ ، لتكون بالنص التالي:

( يجتمع  مجلس الإدارة  مرة كل ثلاثة أشهر، ويجوز عند الضرورة أن يجتمع أكثر من ذلك بدعوة من رئيسه، أو بناء على طلب أربعة من أعضائه أو من الأمين العام للدارة ).'),
('boe26-9f405f57662d0ef67a39f7af','cmpz5u0wo00qlcwg2rg0ernu5','(يعتبر الاجتماع قانونياً بحضور خمسة أعضاء على الأقل ، وتصدر القرارات بالأكثرية المطلقة ، وفي حالة التساوي يرجح جانب الرئيس).','1983-07-30'::timestamptz,'مرسوم ملكي رقم م/51 وتاريخ 20/10/1403هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0057fd8d-8ad4-48f9-b02f-a9a700f16a48/1','تم تعديل هذه المادة بموجب   المرسوم الملكي  رقم (م/51) وتاريخ 20/ 10/ 1403هـ ، لتكون بالنص التالي:

(يعتبر الاجتماع قانونياً بحضور خمسة أعضاء على الأقل ، وتصدر القرارات بالأكثرية المطلقة ، وفي حالة التساوي يرجح جانب الرئيس).'),
('boe26-2c5b013bbaa2853f247f1997','cmpzcv89q0amlvtrk1tflfj16','العمل حق للمواطن، لا يجوز لغيره ممارسته إلا بعد توافر الشروط المنصوص عليها في هذا النظام، والمواطنون متساوون في حق العمل دون أي تمييز على أساس الجنس أو الإعاقة أو السن أو أي شكل من أشكال التمييز الأخرى، سواءً أثناء أداء العمل أو عند التوظيف أو الإعلان عنه','2019-07-30'::timestamptz,'مرسوم ملكي رقم م/134 وتاريخ 27/11/1440هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','عُدلت هذه المادة بموجب المرسوم الملكي رقم (م / 134) وتاريخ 27 / 11 / 1440هـ، لتكون بالنص الآتي: "العمل حق للمواطن، لا يجوز لغيره ممارسته إلا بعد توافر الشروط المنصوص عليها في هذا النظام، والمواطنون متساوون في حق العمل دون أي تمييز على أساس الجنس أو الإعاقة أو السن أو أي شكل من أشكال التمييز الأخرى، سواءً أثناء أداء العمل أو عند التوظيف أو الإعلان عنه".'),
('boe26-eaeb16dbc2abe9d2359dc97b','cmpzcv89q0amnvtrk6ng1ueja','تسري أحكام هذا النظام على الآتي :

1 - كل عقد عمل يلتزم بمقتضاه أي شخص بالعمل لمصلحة صاحب عمل وتحت إدارته أو إشرافه؛ مقابل أجر.

2 - عمال الحكومة والهيئات والمؤسسات العامة، بمن فيهم الذين يشتغلون في المراعي أو الزراعة.

3 - عمال المؤسسات الخيرية.

4 - عقود التأهيل والتدريب مع غير العاملين لدى صاحب العمل في حدود الأحكام الخاصة المنصوص عليها في هذا النظام.

5 - العاملين بعض الوقت في حدود ما يتعلق بالسلامة والصحة المهنية وإصابات العمل وما يقرره الوزير','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"تسري أحكام هذا النظام على الآتي :

1 - كل عقد عمل يلتزم بمقتضاه أي شخص بالعمل لمصلحة صاحب عمل وتحت إدارته أو إشرافه؛ مقابل أجر.

2 - عمال الحكومة والهيئات والمؤسسات العامة، بمن فيهم الذين يشتغلون في المراعي أو الزراعة.

3 - عمال المؤسسات الخيرية.

4 - عقود التأهيل والتدريب مع غير العاملين لدى صاحب العمل في حدود الأحكام الخاصة المنصوص عليها في هذا النظام.

5 - العاملين بعض الوقت في حدود ما يتعلق ب'),
('boe26-a22944c140f259376eff54e2','cmpzcv89s0apbvtrk3oc3pkzr','تنظم ساعات العمل وفترات الراحة خلال اليوم، بحيث لا يعمل العامل أكثر من خمس ساعات متتالية دون فترة للراحة والصلاة والطعام لا تقل عن نصف ساعة في المرة الواحدة خلال مجموع ساعات العمل، وبحيث لا يبقى العامل في مكان العمل أكثر من اثنتي عشرة ساعة في اليوم الواحد','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"تنظم ساعات العمل وفترات الراحة خلال اليوم، بحيث لا يعمل العامل أكثر من خمس ساعات متتالية دون فترة للراحة والصلاة والطعام لا تقل عن نصف ساعة في المرة الواحدة خلال مجموع ساعات العمل، وبحيث لا يبقى العامل في مكان العمل أكثر من اثنتي عشرة ساعة في اليوم الواحد".'),
('boe26-3b60dfd76c6151bbea444ae1','cmpzcv89r0ao0vtrkqqat4vwl','لا يجوز وضع العامل تحت التجربة أكثر من مرة واحدة لدى صاحب عمل واحد.
واستثناء من ذلك يجوز باتفاق طرفي العقد - كتابة - إخضاع العامل لفترة تجربة أخرى بشرط أن تكون في مهنة أخرى أو عمل آخر، أو أن يكون قد مضى على انتهاء علاقة العامل بصاحب العمل مدة لا تقل عن ستة أشهر. وإذا أنهي العقد خلال فترة التجربة فإن أيًّا من الطرفين لا يستحق تعويضاً، كما لا يستحق العامل مكافأة نهاية الخدمة عن ذلك','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"لا يجوز وضع العامل تحت التجربة أكثر من مرة واحدة لدى صاحب عمل واحد.
واستثناء من ذلك يجوز باتفاق طرفي العقد - كتابة - إخضاع العامل لفترة تجربة أخرى بشرط أن تكون في مهنة أخرى أو عمل آخر، أو أن يكون قد مضى على انتهاء علاقة العامل بصاحب العمل مدة لا تقل عن ستة أشهر. وإذا أنهي العقد خلال فترة التجربة فإن أيًّا من الطرفين لا يستحق تعويضاً، كما لا يستحق العامل مكافأة نهاية الخدمة عن ذلك".'),
('boe26-66e4f9dcd62f665d905e6457','cmpzcv89r0ao1vtrkcfdvcmdl','1 - ينتهي عقد العمل المحدد المدة بانقضاء مدته، فإذا استمر طرفاه في تنفيذ عُدَّ العقدُ مجدداً لمدة غير محددة. مع مراعاة ما نصت عليه المادة (السابعة والثلاثون) من هذا النظام بالنسبة إلى غير السعوديين.

2 - إذا تضمن العقد المحدد المدة شرطاً يقضي بتجديده لمدة مماثلة أو لمدة محددة، فإنه يتجدد للمدة المتفق عليها. فإن تعدد التجديد ثلاث مرات متتالية، أو بلغت مدة العقد الأصلي مع مدة التجديد أربع سنوات أيهما أقل واستمر الطرفان في تنفيذه؛ تحوّل العقد إلى عقد غير محدد المدة','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"1 - ينتهي عقد العمل المحدد المدة بانقضاء مدته، فإذا استمر طرفاه في تنفيذ عُدَّ العقدُ مجدداً لمدة غير محددة. مع مراعاة ما نصت عليه المادة (السابعة والثلاثون) من هذا النظام بالنسبة إلى غير السعوديين.

2 - إذا تضمن العقد المحدد المدة شرطاً يقضي بتجديده لمدة مماثلة أو لمدة محددة، فإنه يتجدد للمدة المتفق عليها. فإن تعدد التجديد ثلاث مرات متتالية، أو بلغت مدة العقد الأصلي مع مدة التجديد أربع سنوات أيه'),
('boe26-b5745303369ba6be11526d64','cmpzcv89r0ao4vtrkrvs791oo','1 - لا يجوز لصاحب العمل أن ينقل العامل بغير موافقته – كتابةً – من مكان عمله الأصلي إلى مكان آخر يقتضي تغيير محل إقامته.

2 - لصاحب العمل - في حالات الضرورة التي قد تقتضيها ظروف عارضة ولمدة لا تتجاوز ثلاثين يوماً في السنة – تكليف العامل بعمل في مكان يختلف عن المكان المتفق عليه دون اشتراط موافقته، على أن يتحمل صاحب العمل تكاليف انتقال العامل وإقامته خلال تلك المدة','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"1 - لا يجوز لصاحب العمل أن ينقل العامل بغير موافقته – كتابةً – من مكان عمله الأصلي إلى مكان آخر يقتضي تغيير محل إقامته.

2 - لصاحب العمل - في حالات الضرورة التي قد تقتضيها ظروف عارضة ولمدة لا تتجاوز ثلاثين يوماً في السنة – تكليف العامل بعمل في مكان يختلف عن المكان المتفق عليه دون اشتراط موافقته، على أن يتحمل صاحب العمل تكاليف انتقال العامل وإقامته خلال تلك المدة".'),
('boe26-9c22b5943b83229466b90583','cmpzcv89r0aoavtrk0bhl4w2m','يلتزم صاحب العمل عند انتهاء عقد العمل بما يأتي :

1 - أن يعطي العامل – بناءً على طلبه – شهادة خدمة دون مقابل، يوضح فيها تاريخ التحاقه بالعمل، وتاريخ انتهاء علاقته به، ومهنته، ومقدار أجره الأخير. ولا يجوز لصاحب العمل تضمين الشهادة ما قد يسيء إلى سمعة العامل أو يقلل من فرص العمل أمامه.

2 - أن يعيد إلى العامل جميع ما أودعه لديه من شهادات أو وثائق','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"يلتزم صاحب العمل عند انتهاء عقد العمل بما يأتي :

1 - أن يعطي العامل – بناءً على طلبه – شهادة خدمة دون مقابل، يوضح فيها تاريخ التحاقه بالعمل، وتاريخ انتهاء علاقته به، ومهنته، ومقدار أجره الأخير. ولا يجوز لصاحب العمل تضمين الشهادة ما قد يسيء إلى سمعة العامل أو يقلل من فرص العمل أمامه.

2 - أن يعيد إلى العامل جميع ما أودعه لديه من شهادات أو وثائق".'),
('boe26-d5ae388b0f5dca5820313f92','cmpzcv89r0aojvtrk29f88ich','يجب على صاحب العمل أن يكتب الغرامات التي يوقعها على العامل في سجل خاص، مع بيان اسم العامل ومقدار أجره ومقدار الغرامة وسبب توقيعها وتاريخ ذلك. ولا يجوز التصرف في الغرامات إلا فيما يعود بالنفع على عمال المنشأة، على أن يكون التصرف بهذه الغرامات من قبل اللجنة العمالية في المنشأة، وفي حالة عدم وجود لجنة يكون التصرف في الغرامات بموافقة الوزارة','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"يجب على صاحب العمل أن يكتب الغرامات التي يوقعها على العامل في سجل خاص، مع بيان اسم العامل ومقدار أجره ومقدار الغرامة وسبب توقيعها وتاريخ ذلك. ولا يجوز التصرف في الغرامات إلا فيما يعود بالنفع على عمال المنشأة، على أن يكون التصرف بهذه الغرامات من قبل اللجنة العمالية في المنشأة، وفي حالة عدم وجود لجنة يكون التصرف في الغرامات بموافقة الوزارة".'),
('boe26-929c08a3c9e8b23617fcbbc3','cmpzcv89s0aomvtrkbb6sf2jp','إذا لم يراع الطرف الذي أنهى العقد غير المحدد المدة المهلة المحدد للإشعار وفقاً للمادة (الخامسة والسبعين) من هذا النظام، فإنه يلتزم بأن يدفع للطرف الآخر عن مهلة الإشعار مبلغاً مساوياً لأجر العامل عن المهلة نفسها، ما لم يتفق الطرفان على أكثر من ذلك','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"إذا لم يراع الطرف الذي أنهى العقد غير المحدد المدة المهلة المحدد للإشعار وفقاً للمادة (الخامسة والسبعين) من هذا النظام، فإنه يلتزم بأن يدفع للطرف الآخر عن مهلة الإشعار مبلغاً مساوياً لأجر العامل عن المهلة نفسها، ما لم يتفق الطرفان على أكثر من ذلك".'),
('boe26-06763bf30f315510f0bb957c','cmpzcv89s0aoqvtrkvtuetnbq','لا يجوز لصاحب العمل فسخ العقد دون مكافأة العامل، أو إشعاره، أو تعويضه؛ إلا في الحالات الآتية، وبشرط أن يتيح له الفرصة لكي يبدي أسباب معارضته للفسخ :

1 - إذا وقع من العامل اعتداء على صاحب العمل أو المدير المسؤول أو أحد رؤسائه أو مرؤوسيه أثناء العمل أو بسببه.

2 - إذا لم يؤدِّ العامل التزاماته الجوهرية المترتبة على عقد العمل أو لم يطع الأوامر المشروعة أو لم يراعِ عمداً التعليمات – التي أعلن عنها صاحب العمل في مكان ظاهر – الخاصة بسلامة العمل والعمال رغم إنذاره كتابة.

3 - إذا ثبت اتباع العامل سلوكاً سيئاً، أو ارتكابه عملاً مخلاً بالشرف أو الأمانة.

4 - إذا وقع من العامل - عمداً - أيُّ فعلٍ أو تقصيرٍ يقصد به إلحاق خسارة مادية بصاحب العمل، بشرط أن يبلغ صاحب العمل الجهات المختصة بالحادث خلال أربع وعشرين ساعة من وقت علمه بوقوعه.

5 - إذا ثبت أن العامل لجأ إلى التزوير ليحصل على العمل.

6 - إذا كان العامل مُعيَّناً تحت الاختبار.

7 - إذا تغيب العامل دون سبب مشروع أكثر من ثلاثين يوماً خلال السنة العقدية الواحدة أو أكثر من خمسة عشر يوماً متتالية، على أن يسبق الفصل إنذار كتابي من صاحب العمل للعامل بعد غيابه عشرين يوماً في الحالة الأولى وانقطاعه عشرة أيام في الحالة الثانية.

8 - إذا ثبت أن العامل استغل مركزه الوظيفي بطريقة غير مشروعة للحصول على نتائج ومكاسب شخصية.

9 - إذا ثبت أن العامل أفشى الأسرار الصناعية أو التجارية الخاصة بالعمل الذي يعمل فيه','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"لا يجوز لصاحب العمل فسخ العقد دون مكافأة العامل، أو إشعاره، أو تعويضه؛ إلا في الحالات الآتية، وبشرط أن يتيح له الفرصة لكي يبدي أسباب معارضته للفسخ :

1 - إذا وقع من العامل اعتداء على صاحب العمل أو المدير المسؤول أو أحد رؤسائه أو مرؤوسيه أثناء العمل أو بسببه.

2 - إذا لم يؤدِّ العامل التزاماته الجوهرية المترتبة على عقد العمل أو لم يطع الأوامر المشروعة أو لم يراعِ عمداً التعليمات – التي أعلن عنها صا'),
('boe26-f33c27fe28db10547a851486','cmpzcv89s0aotvtrk4bfqr1i6','1 - إذا كان العمل المنوط بالعامل يسمح له بمعرفة عملاء صاحب العمل، جاز لصاحب العمل – حمايةً لمصالحه المشروعة – أن يشترط على العامل ألا يقوم بعد انتهاء العقد بمنافسته، ويجب لصحة هذا الشرط أن يكون مُحرراً ومُحدداً، من حيث الزمان والمكان ونوع العمل، ويجب ألا تزيد مدته على سنتين من تاريخ انتهاء العلاقة بين الطرفين.

2 - إذا كان العمل المنوط بالعامل يسمح له بالاطلاع على أسرار عمله، جاز لصاحب العمل – حمايةً لمصالحه المشروعة – أن يشترط على العامل ألا يقوم بعد انتهاء العقد بإفشاء أسراره، ويجب لصحة هذا الشرط أن يكون محرراً ومحدداً، من حيث الزمان والمكان ونوع العمل.

3 - استثناء من أحكام هذا النظام، لصاحب العمل رفع دعوى خلال سنة من تاريخ اكتشاف مخالفة العامل لأيٍّ من التزاماته الواردة في هذه المادة','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"1 - إذا كان العمل المنوط بالعامل يسمح له بمعرفة عملاء صاحب العمل، جاز لصاحب العمل – حمايةً لمصالحه المشروعة – أن يشترط على العامل ألا يقوم بعد انتهاء العقد بمنافسته، ويجب لصحة هذا الشرط أن يكون مُحرراً ومُحدداً، من حيث الزمان والمكان ونوع العمل، ويجب ألا تزيد مدته على سنتين من تاريخ انتهاء العلاقة بين الطرفين.

2 - إذا كان العمل المنوط بالعامل يسمح له بالاطلاع على أسرار عمله، جاز لصاحب العمل – حما'),
('boe26-4dbb867ac14dee4125df2ba6','cmpzcv89s0ap0vtrkf1uyewpp','1 - يجب دفع أجر العامل وكل مبلغ مستحق له بالعملة الرسمية للبلاد طبقاً للأحكام الآتية :

أ - العمال باليومية : تصرف أجورهم مرة كل أسبوع على الأقل.

ب - العمال ذوو الأجور الشهرية : تصرف أجورهم مرة في الشهر.

ج - إذا كان العمل يؤدى بالقطعة، ويحتاج لمدة تزيد على أسبوعين، فيجب أن يحصل العامل على دفعة كل أسبوع تتناسب مع ما أتمه من العمل، ويصرف باقي الأجر كاملاً خلال الأسبوع التالي لتسليم العمل.

د - في غير ما ذكر، تؤدى إلى العمال أجورهم مرة كل أسبوع على الأقل.

2 - تلزم المنشآت بدفع الأجور في حسابات العمال عن طريق البنوك المعتمدة في المملكة، بشرط ألا يتجاوز موعد استحقاقها المواعيد المحددة أعلاه، ويجوز للوزير استثناء بعض المنشآت من ذلك','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"1 - يجب دفع أجر العامل وكل مبلغ مستحق له بالعملة الرسمية للبلاد طبقاً للأحكام الآتية :

أ - العمال باليومية : تصرف أجورهم مرة كل أسبوع على الأقل.

ب - العمال ذوو الأجور الشهرية : تصرف أجورهم مرة في الشهر.

ج - إذا كان العمل يؤدى بالقطعة، ويحتاج لمدة تزيد على أسبوعين، فيجب أن يحصل العامل على دفعة كل أسبوع تتناسب مع ما أتمه من العمل، ويصرف باقي الأجر كاملاً خلال الأسبوع التالي لتسليم العمل.

د - في '),
('boe26-a371c0ae6e1a0211e5f966a8','cmpzcv89s0appvtrkcgzx2hvd','1 - للعامل - إذا وافق صاحب العمل على انتسابه إلى مؤسسة تعليمية أو قَبِل استمراره فيها – الحق في إجازة بأجر كامل لتأدية الامتحان عن سنة غير معادة تحدد مدتها بعد أيام الامتحان الفعلية. أما إذا كان الامتحان عن سنة معادة فيكون للعامل الحق في إجازة دون أجر بعدد أيام الامتحان الفعلية. ويحرم العامل من أجر الإجازة إذا ثبت أنه لم يؤدِّ الامتحان، مع عدم الإخلال بحق صاحب العمل في مساءلته تأديبيًّا.

2 - إذا لم يحصل العامل على موافقة صاحب العمل على انتسابه إلى مؤسسة تعليمية، فله أن يحصل على إجازة لتأدية الامتحان بعدد أيام الامتحان الفعلية تحتسب من إجازته السنوية في حال توافرها، وعند تعذر ذلك فللعامل أن يحصل على إجازة دون أجر بعدد أيام الامتحان الفعلية.

3 - على العامل أن يتقدم بطلب الإجازة قبل موعدها بخمسة عشر يوماً على الأقل.

4 - لصاحب العمل أن يطلب من العامل تقديم الوثائق المؤيدة لطلب الإجازة، وكذلك ما يدل على أدائه الامتحان','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"1 - للعامل - إذا وافق صاحب العمل على انتسابه إلى مؤسسة تعليمية أو قَبِل استمراره فيها – الحق في إجازة بأجر كامل لتأدية الامتحان عن سنة غير معادة تحدد مدتها بعد أيام الامتحان الفعلية. أما إذا كان الامتحان عن سنة معادة فيكون للعامل الحق في إجازة دون أجر بعدد أيام الامتحان الفعلية. ويحرم العامل من أجر الإجازة إذا ثبت أنه لم يؤدِّ الامتحان، مع عدم الإخلال بحق صاحب العمل في مساءلته تأديبيًّا.

2 - إذا '),
('boe26-0de17112fc60bc1220a3f1b2','cmpzcv89s0aqbvtrkr1h6a1t2','للمصاب - في حالة عجزه المؤقت عن العمل الناتج من إصابة عمل - الحق في معونة مالية تعادل أجره كاملاً لمدة ستين يوماً ثم يستحق مقابلاً ماليًّا يعادل (75%) من أجره طوال المدة التي يستغرقها علاجه. فإذا بلغت مدة العلاج سنة أو تقرر طبيًّا عدم احتمال شفائه وحالته الصحية لا تمكنه من العمل، عُدت الإصابة عجزاً كليًّا، وينهي العقد ويعوض عن الإصابة. ولا يكون لصاحب العمل حق في استرداد ما دفعه إلى المصاب خلال تلك السنة','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"للمصاب - في حالة عجزه المؤقت عن العمل الناتج من إصابة عمل - الحق في معونة مالية تعادل أجره كاملاً لمدة ستين يوماً ثم يستحق مقابلاً ماليًّا يعادل (75%) من أجره طوال المدة التي يستغرقها علاجه. فإذا بلغت مدة العلاج سنة أو تقرر طبيًّا عدم احتمال شفائه وحالته الصحية لا تمكنه من العمل، عُدت الإصابة عجزاً كليًّا، وينهي العقد ويعوض عن الإصابة. ولا يكون لصاحب العمل حق في استرداد ما دفعه إلى المصاب خلال تلك'),
('boe26-8562394e65c2766dc3e77bbb','cmpzcv89t0aqtvtrkim954vnt','لا يجوز لصاحب العمل فصل العاملة أو إنذارها بالفصل أثناء حملها أو تمتعها بإجازة الوضع، ويشمل ذلك مدة مرضها الناشئ عن أي منهما، على أن يثبت المرض بشهادة طبية معتمدة، وأن لا تتجاوز مدة غيابها (مائة وثمانين) يوماً في السنة سواءً أكانت متصلة أم متفرقة','2019-07-30'::timestamptz,'مرسوم ملكي رقم م/134 وتاريخ 27/11/1440هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','عُدلت هذه المادة بموجب المرسوم الملكي رقم (م / 134) وتاريخ 27 / 11 / 1440هـ،  لتكون بالنص الآتي: "لا يجوز لصاحب العمل فصل العاملة أو إنذارها بالفصل أثناء حملها أو تمتعها بإجازة الوضع، ويشمل ذلك مدة مرضها الناشئ عن أي منهما، على أن يثبت المرض بشهادة طبية معتمدة، وأن لا تتجاوز مدة غيابها (مائة وثمانين) يوماً في السنة سواءً أكانت متصلة أم متفرقة".'),
('boe26-68375ef1160ead97edeebee4','cmpzcv89t0aqyvtrkqlm8ob4q','1 - للمرأة العاملة المسلمة التي يتوفى زوجها الحق في إجازة عدة بأجر كامل لمدة لا تقل عن أربعة أشهر وعشرة أيام من تاريخ الوفاة، ولها الحق في تمديد هذه الإجازة دون أجر إن كانت حاملاً - خلال هذه الفترة - حتى تضع حملها، ولا يجوز لها الاستفادة من باقي إجازة العدة الممنوحة لها – بموجب هذا النظام – بعد وضع حملها.

2 - للمرأة العاملة غير المسلمة التي يتوفى زوجها الحق في إجازة بأجر كامل لمدة خمسة عشر يوماً.

وفي جميع الأحوال لا يجوز للعاملة المتوفى عنها زوجها ممارسة أي عمل لدى الغير خلال هذه المدة.

ويحق لصاحب العمل أن يطلب الوثائق المؤيدة للحالات المشار إليها','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"1 - للمرأة العاملة المسلمة التي يتوفى زوجها الحق في إجازة عدة بأجر كامل لمدة لا تقل عن أربعة أشهر وعشرة أيام من تاريخ الوفاة، ولها الحق في تمديد هذه الإجازة دون أجر إن كانت حاملاً - خلال هذه الفترة - حتى تضع حملها، ولا يجوز لها الاستفادة من باقي إجازة العدة الممنوحة لها – بموجب هذا النظام – بعد وضع حملها.

2 - للمرأة العاملة غير المسلمة التي يتوفى زوجها الحق في إجازة بأجر كامل لمدة خمسة عشر يوماً'),
('boe26-12e492e92b12d4a56ca80c00','cmpzcv89t0arovtrki3o3z0m4','لا يجوز تشغيل أي شخص في المنجم أو المحجر لم يتم الثامنة عشرة من العمر','2020-08-26'::timestamptz,'مرسوم ملكي رقم م/5 وتاريخ 7/1/1442هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م / 5) وتاريخ 7 / 1 / 1442هـ، لتكون بالنص الآتي: "لا يجوز تشغيل أي شخص في المنجم أو المحجر لم يتم الثامنة عشرة من العمر".

 '),
('boe26-a989e0922bb025c07944debb','cmpzcv89t0arwvtrkhmxfm6ne','يتولى تفتيش العمل مفتشون من موظفي الوزارة، أو من غيرهم من السعوديين، يحددهم الوزير أو من يفوضه، وتكون لهم الصلاحيات والاختصاصات المنصوص عليها في هذا النظام','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"يتولى تفتيش العمل مفتشون من موظفي الوزارة، أو من غيرهم من السعوديين، يحددهم الوزير أو من يفوضه، وتكون لهم الصلاحيات والاختصاصات المنصوص عليها في هذا النظام".'),
('boe26-a2316ce59dcd3da2dad6c77f','cmpzcv89t0arzvtrkz43ptsnn','يلتزم مفتشو العمل - قبل مباشرتهم لمهماتهم - بتوقيع تعهد وفق النموذج الذي تعده الوزارة، يتضمن التزامهم بأداء عملهم بكل أمانة وإخلاص، وألا يفشوا سرَّ أيِّ اختراعٍ صناعيٍّ، أو غير ذلك من الأسرار التي يطلعون عليها بحكم عملهم. ويحمل مفتش العمل بطاقة من الوزارة تثبت صفته','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"يلتزم مفتشو العمل - قبل مباشرتهم لمهماتهم - بتوقيع تعهد وفق النموذج الذي تعده الوزارة، يتضمن التزامهم بأداء عملهم بكل أمانة وإخلاص، وألا يفشوا سرَّ أيِّ اختراعٍ صناعيٍّ، أو غير ذلك من الأسرار التي يطلعون عليها بحكم عملهم. ويحمل مفتش العمل بطاقة من الوزارة تثبت صفته".'),
('boe26-549f853a357c3c8f7272ad79','cmpzcv89t0as5vtrki2x156eq','إذا تحقق للمفتش أثناء التفتيش وجود مخالفة لأحكام هذا النظام أو اللائحة أو القرارات الصادرة تنفيذاً له، فعليه تحرير محضر ضبط بالمخالفة وفقاً للأحكام الواردة في اللائحة التنفيذية لضبط أعمال التفتيش وتنظيمها، ورفعه إلى الوزير؛ لإصدار قرار بذلك','2015-03-25'::timestamptz,'مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"إذا تحقق للمفتش أثناء التفتيش وجود مخالفة لأحكام هذا النظام أو اللائحة أو القرارات الصادرة تنفيذاً له، فعليه تحرير محضر ضبط بالمخالفة وفقاً للأحكام الواردة في اللائحة التنفيذية لضبط أعمال التفتيش وتنظيمها، ورفعه إلى الوزير؛ لإصدار قرار بذلك".'),
('boe26-9ca55adf25d6682744a83e92','cmpz6qln10buxcwg2v2dtvt6t','يسوى المعاش على أساس جزء من خمسة وثلاثين جزءًا من الراتب الأساسي الأخير على أن لا يتجاوز المعاش مقدار هذا الراتب','1976-07-06'::timestamptz,'مرسوم ملكي رقم م/56 وتاريخ 9/7/1396هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0838afd4-ca76-4b4a-b1d1-a9a700f22afd/1','عدلت هذه المادة  بموجب المرسوم الملكي  رقم (م/56) وتاريخ 9 / 7 / 1396 هـ ، ليصبح نصها كمايلى :

" يسوى المعاش على أساس جزء من خمسة وثلاثين جزءًا من الراتب الأساسي الأخير على أن لا يتجاوز المعاش مقدار هذا الراتب".'),
('boe26-0f11bd779c34be1d710c5409','cmpz6qn7v0bvhcwg2ekkyysgo','( يسوى معاش من يصاب من العسكريين بعجز كلي بسبب العمليات الحربية أو بسبب الأسر أو نتيجة إصابته خلال خدمة أُمر بها أثناء مواجهة التنظيمات المسلحة المعادية أو أثناء إطلاق النار خلال اقتحام أماكن المخربين أو مطاردة المهربين على أساس راتب أعلى درجة في سلم الرواتب للرتبة التي تعلو رتبته مباشرة، أما إذا كانت الإصابة قد أحدثت عجزًا جزئيًّا أوجب فصله من الخدمة العسكري فيمنح أربعة أخماس هذا الراتب ) .','1987-06-15'::timestamptz,'مرسوم ملكي رقم م/50 وتاريخ 19/10/1407هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0838afd4-ca76-4b4a-b1d1-a9a700f22afd/1','عدلت هذه المادة  بالمرسوم الملكي    رقم (م/50) وتاريخ 19 / 10 / 1407 هـ ، لتصبح بالنص التالى :

( يسوى معاش من يصاب من العسكريين بعجز كلي بسبب العمليات الحربية أو بسبب الأسر أو نتيجة إصابته خلال خدمة أُمر بها أثناء مواجهة التنظيمات المسلحة المعادية أو أثناء إطلاق النار خلال اقتحام أماكن المخربين أو مطاردة المهربين على أساس راتب أعلى درجة في سلم الرواتب للرتبة التي تعلو رتبته مباشرة، أما إذا كانت الإصابة قد أحدثت عجزًا جزئيًّا أوجب فصله من الخدمة العسكري فيمنح أربعة أخماس هذا الراتب ) .'),
('boe26-311b37c139d0bde39699ae9a','cmpz6qo0c0bvrcwg2b2cfs4fe','المستحقون عن صاحب المعاش هم: الزوج أو الزوجة، والأم والأب، والابن والبنت، وابن وبنت الابن الذي توفي في حياة صاحب المعاش، والأخ والأخت، والجد والجدة. وفيما عدا الزوجة والابن والبنت، فيشترط لاستحقاق الشخص أن يكون معتمداً في إعالته على صاحب المعاش عند وفاته. ويحدد مجلس إدارة المؤسسة العامة للتقاعد بقرار منه متى يعتبر الشخص معتمداً في إعالته على صاحب المعاش، وتاريخ بدء صرف الاستحقاق، وإجراءات إثبات ذلك','2021-06-03'::timestamptz,'مرسوم ملكي رقم م/93 وتاريخ 1442/10/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0838afd4-ca76-4b4a-b1d1-a9a700f22afd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/93) وتاريخ 1442/10/22هـ لتكون بالنص الآتي: " المستحقون عن صاحب المعاش هم: الزوج أو الزوجة، والأم والأب، والابن والبنت، وابن وبنت الابن الذي توفي في حياة صاحب المعاش، والأخ والأخت، والجد والجدة. وفيما عدا الزوجة والابن والبنت، فيشترط لاستحقاق الشخص أن يكون معتمداً في إعالته على صاحب المعاش عند وفاته. ويحدد مجلس إدارة المؤسسة العامة للتقاعد بقرار منه متى يعتبر الشخص معتمداً في إعالته على صاحب المعاش، وتاريخ بدء صرف الاستحقاق، وإجراءات إثبات ذلك".'),
('boe26-c87f9f3038bfa1935adc98cf','cmpz6qoyh0bw3cwg20iogdri8','إذا لم يعد العسكري متمتعاً بالجنسية العربية السعودية، يُمنح مكافأة تحسب وفق أحكام المادتين (9) و (10) من هذا النظام','2022-03-23'::timestamptz,'مرسوم ملكي رقم م/80 وتاريخ 1443/8/20هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0838afd4-ca76-4b4a-b1d1-a9a700f22afd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/80) وتاريخ 1443/8/20هـ، لتكون بالنص الآتي: " إذا لم يعد العسكري متمتعاً بالجنسية العربية السعودية، يُمنح مكافأة تحسب وفق أحكام المادتين (9) و (10) من هذا النظام".'),
('boe26-fdbf3c3c93f3fced1b508cd6','cmpzcv6870a4kvtrkid7nmfjt','يعاقب بالسجن مدة لا تزيد على ستة أشهر وبغرامة لا تتجاوز تسعين ألف ريال أو بإحدى هاتين العقوبتين، كل من زاول صناعة المعادن الثمينة ومشغولاتها أو الأحجار الكريمة دون ترخيص','2021-09-02'::timestamptz,'مرسوم ملكي رقم م/13 وتاريخ 1443/1/25هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0f54d227-1450-4231-93cd-a9a700f29821/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/13) وتاريخ 1443/1/25هـ، لتكون بالنص الآتي: " يعاقب بالسجن مدة لا تزيد على ستة أشهر وبغرامة لا تتجاوز تسعين ألف ريال أو بإحدى هاتين العقوبتين، كل من زاول صناعة المعادن الثمينة ومشغولاتها أو الأحجار الكريمة دون ترخيص".'),
('boe26-e285c14a7ae562582a3f2233','cmpz6qxzr0bz7cwg2d6shir9f','تكون قرارات المجلس نافذة بعد توقيعها من رئيس مجلس الخدمة العسكرية، وتستثنى منها القرارات التى تتطلب موضوعاتها استكمال إجراءات نظامية في شأنها، وتحيل الأمانة العامة لمجلس الخدمة العسكرية هذه القرارات إلى ديوان رئاسة مجلس الوزراء، لإكمال مايلزم في شأنها.','2011-03-08'::timestamptz,'مرسوم ملكي رقم م/21 وتاريخ 3/4/1432هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/11d3d5b0-dddf-443a-9851-a9a700f23208/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م / 21 ) وتاريخ 3 / 4 / 1432 هـ ، لتصبح بالنص التالى :

" تكون قرارات المجلس نافذة بعد توقيعها من رئيس مجلس الخدمة العسكرية، وتستثنى منها القرارات التى تتطلب موضوعاتها استكمال إجراءات نظامية في شأنها، وتحيل الأمانة العامة لمجلس الخدمة العسكرية هذه القرارات إلى ديوان رئاسة مجلس الوزراء، لإكمال مايلزم في شأنها."'),
('boe26-b706d659818a1919bead83e0','cmpz5uw0v011fcwg23hqhqxdo','(يجب أن يكون الإعلان منسجماً مع عادات وتقاليد البلاد، وأن تتلاءم مادته مع الذوق السليم، وأن تكون الصور والكتابات في إطار الآداب الإسلامية، مع التقيد بقواعد اللغة العربية الفصحى، وبما يصدر من الجهات ذات العلاقة فيما يخص الضوابط الشرعية للإعلانات) .','2001-01-22'::timestamptz,'قرار مجلس الوزراء رقم 242 وتاريخ 27/10/1421هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/16c49913-599f-406b-b016-a9a700f172c9/1','عدلت هذه المادة بموجب قرار مجلس الوزراء رقم (242) وتاريخ 27/ 10/ 1421هـ ،لتصبح بالنص الآتى:

(يجب أن يكون الإعلان منسجماً مع عادات وتقاليد البلاد، وأن تتلاءم مادته مع الذوق السليم، وأن تكون الصور والكتابات في إطار الآداب الإسلامية، مع التقيد بقواعد اللغة العربية الفصحى، وبما يصدر من الجهات ذات العلاقة فيما يخص الضوابط الشرعية للإعلانات) .'),
('boe26-4d0dcdfd40af158c4ad56993','cmpzcv9t60b3mvtrkbmjwfqub','ينشأ بموجب التنظيم مجلس يسمى مجلس شؤون الأسرة يرتبط تنظيمياً بمجلس الشؤون الاقتصادية والتنمية، وبرئاسة معالي وزير الموارد البشرية والتنمية الاجتماعية، ويتمتع بالشخصية الاعتبارية وبالاستقلال المالي والإداري، ويكون مقره في مدينة الرياض، وله إنشاء فروع أو مكاتب داخل المملكة بحسب الحاجة','2022-03-15'::timestamptz,'قرار مجلس الوزراء رقم 443 وتاريخ 1443/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/1c026125-b0b2-4ea7-b374-a9a700f2c0ee/1','- عدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (443) وتاريخ 1443/8/12هـ، لتكون بالنص الآتي: " ينشأ بموجب التنظيم مجلس يسمى مجلس شؤون الأسرة يرتبط تنظيمياً بمجلس الشؤون الاقتصادية والتنمية، وبرئاسة معالي وزير الموارد البشرية والتنمية الاجتماعية، ويتمتع بالشخصية الاعتبارية وبالاستقلال المالي والإداري، ويكون مقره في مدينة الرياض، وله إنشاء فروع أو مكاتب داخل المملكة بحسب الحاجة".'),
('boe26-8dd10ce00b5bceb4ffd58d8c','cmpzcv9t60b3qvtrkifnvxi6n','يشكل المجلس ما يلزم من لجان فنية دائمة أو مؤقتة على أن يكون من بينها (لجنة الطفولة ولجنة كبار السن ولجنة المرأة) ويحدد المجلس أعضاء كل لجنة ومهماتها وآلية عملها وحوكمتها','2022-03-15'::timestamptz,'قرار مجلس الوزراء رقم 443 وتاريخ 1443/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/1c026125-b0b2-4ea7-b374-a9a700f2c0ee/1','- عدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (443) وتاريخ 1443/8/12هـ، لتكون بالنص الآتي: "يشكل المجلس ما يلزم من لجان فنية دائمة أو مؤقتة على أن يكون من بينها (لجنة الطفولة ولجنة كبار السن ولجنة المرأة) ويحدد المجلس أعضاء كل لجنة ومهماتها وآلية عملها وحوكمتها".'),
('boe26-cd8781e8121978725b04c3b7','cmpzcv9t60b3rvtrk57771oul','يكون للمجلس أمانة عامة ترتبط بالرئيس، يرأسها أمين عام، يختاره الرئيس','2022-03-15'::timestamptz,'قرار مجلس الوزراء رقم 443 وتاريخ 1443/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/1c026125-b0b2-4ea7-b374-a9a700f2c0ee/1','- عدلت هذه المادة بموجب قرار مجلس الوزراء رقم (443) وتاريخ 1443/8/12هـ، لتكون بالنص الآتي: "يكون للمجلس أمانة عامة ترتبط بالرئيس، يرأسها أمين عام، يختاره الرئيس".'),
('boe26-3aec25624b2806827518ddcf','cmpz9encb0cfnybvvqfwup3hk','أ - يكون تشكيل مجلس الخدمة المدنية من:

-  رئيس مجلس الوزراء         رئيساً

-   نائب رئيس مجلس الوزراء         نائباً للرئيس

-  رئيس الديوان العام للخدمة المدنية    عضواً

- أربعة من الوزراء أعضاء يعينون بأمر ملكي لمدة ثلاث سنوات.

- ثلاثة أعضاء من ذوي الاختصاص يعينون بأمر ملكي     لمدة ثلاث سنوات.

ب - تعقد جلسات المجلس الخدمة المدنية برئاسة رئيسه ، أو نائبه ، أو من يفوضه من بين أعضائه.','1982-09-04'::timestamptz,'مرسوم ملكي رقم م/53 وتاريخ 16/11/1402هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/1fe7fe77-d349-4fae-a561-a9a700f23a89/1','عدلت هذه المادة  بالمرسوم الملكي رقم (م / 53) وتاريخ 16 /11 /1402هـ ، لتصبح كالتالى :

أ - يكون تشكيل مجلس الخدمة المدنية من:

-  رئيس مجلس الوزراء         رئيساً

-   نائب رئيس مجلس الوزراء         نائباً للرئيس

-  رئيس الديوان العام للخدمة المدنية    عضواً

- أربعة من الوزراء أعضاء يعينون بأمر ملكي لمدة ثلاث سنوات.

- ثلاثة أعضاء من ذوي الاختصاص يعينون بأمر ملكي     لمدة ثلاث سنوات.

ب - تعقد جلسات المجلس الخدمة المدنية برئاسة رئيسه ، أو نائبه ، أو من يفوضه من بين أعضائه.'),
('boe26-100ca1a1a41b47da7b77ebe0','cmpz6h3dy08hzcwg21vue35d1','1- تودع جميع إيرادات الهيئة في حساب جاري وزارة المالية في البنك المركزي السعودي.

2- تفتح الهيئة حساباً لها في البنك المركزي السعودي، وتصرف منه وفق ميزانيتها المعتمدة، ولها فتح حسابات أخرى في البنوك المرخص لها بالعمل في المملكة','2022-12-27'::timestamptz,'قرار مجلس الوزراء رقم 376 وتاريخ 1444/6/3هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/216a2b6e-911e-4223-a11b-adab00c670a1/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (376) وتاريخ 1444/6/3هـ، لتكون بالنص الآتي:

" 1- تودع جميع إيرادات الهيئة في حساب جاري وزارة المالية في البنك المركزي السعودي.

2- تفتح الهيئة حساباً لها في البنك المركزي السعودي، وتصرف منه وفق ميزانيتها المعتمدة، ولها فتح حسابات أخرى في البنوك المرخص لها بالعمل في المملكة ".'),
('boe26-ea36da8422c2050f46c87775','cmpzcvci60bxuvtrktid7c47o','المؤسسة العامة للخطوط الجوية العربية السعودية مؤسسة عامة مستقلة تتمتع بالشخصية الاعتبارية وترتبط تنظيميًا برئيس مجلس الوزراء، ويكون مقرها في محافظة جدة، ويجوز لمجلس الوزراء أن يقرر نقل مقرها إلى مكان آخر داخل المملكة','2012-01-09'::timestamptz,'قرار مجلس الوزراء رقم 28 وتاريخ 15/2/1433هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/21bbfc47-571d-4916-82b6-a9a700f2e06c/1','تم تعديل هذه المادة بموجب قرار مجلس الوزراء رقم (28) وتاريخ 15 / 2 / 1433هـ ، لتصبح بالنص التالى :

"المؤسسة العامة للخطوط الجوية العربية السعودية مؤسسة عامة مستقلة تتمتع بالشخصية الاعتبارية وترتبط تنظيميًا برئيس مجلس الوزراء، ويكون مقرها في محافظة جدة، ويجوز لمجلس الوزراء أن يقرر نقل مقرها إلى مكان آخر داخل المملكة".'),
('boe26-6873d7e23ab2a2a8abe16dd0','cmpzcvci60bxxvtrkwf71rnst','يتولى إدارة المؤسسة مجلس يرأسه سمو   وزير الدفاع والطيران     أو من ينيبه، وتسعة أعضاء يصدر بتسميتهم قرار من   مجلس الوزراء    ، بناء على ترشيح   وزير الدفاع والطيران  ، ممن تتوفر فيهم المؤهلات المناسبة، ويكون من بينهم:
1 -   مساعد وزير الدفاع والطيران لشؤون الطيران المدني  ،   ومدير عام المؤسسة ،   ورئيس الطيران المدني .
2 - ممثلون عن الجهات الحكومية ذات العلاقة.
3 - من يرشحهم   وزير الدفاع والطيران     من غير هؤلاء.
ويحدد قرار  مجلس الوزراء    فترة عضوية من يختارهم، ومقدار المكافأة التي تمنح مقابل عضوية المجلس .','1980-01-23'::timestamptz,'مرسوم ملكي رقم م/2 وتاريخ 5/3/1400هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/21bbfc47-571d-4916-82b6-a9a700f2e06c/1','عدلت هذه المادة  بموجب المرسوم الملكي رقم (م/2) وتاريخ 5 / 3 / 1400 هـ ، لتصبح بالنص التالى :

يتولى إدارة المؤسسة مجلس يرأسه سمو   وزير الدفاع والطيران     أو من ينيبه، وتسعة أعضاء يصدر بتسميتهم قرار من   مجلس الوزراء    ، بناء على ترشيح   وزير الدفاع والطيران  ، ممن تتوفر فيهم المؤهلات المناسبة، ويكون من بينهم:
1 -   مساعد وزير الدفاع والطيران لشؤون الطيران المدني  ،   ومدير عام المؤسسة ،   ورئيس الطيران المدني .
2 - ممثلون عن الجهات الحكومية ذات العلاقة.
3 - من يرشحهم   وزير الدفاع والطيران  '),
('boe26-a9e5ba0c1a8e66aca90ea441','cmpzcvci60bxzvtrkplxgeh7r','ينعقد مجلس إدارة المؤسسة في مقر المؤسسة أو في مدينة يحددها بدعوة من رئيسه، ويجب ألا تقل الجلسات التي يعقدها المجلس عن عشر جلسات في السنة.
ولا يكون انعقاد المجلس صحيحا إلا إذا حضره ستة أعضاء على الأقل بما فيهم الرئيس .','1980-01-23'::timestamptz,'مرسوم ملكي رقم م/2 وتاريخ 5/3/1400هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/21bbfc47-571d-4916-82b6-a9a700f2e06c/1','عدلت هذه المادة  بموجب المرسوم الملكي رقم (م/2) وتاريخ 5 / 3 / 1400 هـ ، ليصبح نصها كالتالى :

"ينعقد مجلس إدارة المؤسسة في مقر المؤسسة أو في مدينة يحددها بدعوة من رئيسه، ويجب ألا تقل الجلسات التي يعقدها المجلس عن عشر جلسات في السنة.
ولا يكون انعقاد المجلس صحيحا إلا إذا حضره ستة أعضاء على الأقل بما فيهم الرئيس ."'),
('boe26-d130802f36b42d3feb26e7d0','cmpzcvci60by5vtrkmjlgc471','تعفى المؤسسة من أداء جميع الرسوم والطوابع وضرائب الدخل عن النشاط الاقتصادي الذي تمارسه في حدود الأغراض المنصوص عليها في المادة (الثانية) من هذا النظام، ويشمل هذا الإعفاء رسوم وقود الطائرات دون أنواع الوقود الأخرى الذي تستهلكه المؤسسة.','2005-08-16'::timestamptz,'مرسوم ملكي رقم م/42 وتاريخ 11/7/1426هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/21bbfc47-571d-4916-82b6-a9a700f2e06c/1','عدلت هذه المادة  بموجب المرسوم الملكي رقم (م/42) وتاريخ 11 / 7 / 1426 هـ،  لتصبح بالنص التالى :

"تعفى المؤسسة من أداء جميع الرسوم والطوابع وضرائب الدخل عن النشاط الاقتصادي الذي تمارسه في حدود الأغراض المنصوص عليها في المادة (الثانية) من هذا النظام، ويشمل هذا الإعفاء رسوم وقود الطائرات دون أنواع الوقود الأخرى الذي تستهلكه المؤسسة."'),
('boe26-29d909db3065de0946301d9f','cmpzcuyse082avtrkbm6cgx2l','1- على الجهات ذات العلاقة وضع برامج صحية وتربوية وتعليمية ونفسية واجتماعية، لإعادة تأهيل الطفل الذي تعرض لإحدى حالات الإيذاء أو الإهمال.

2- تتولى وزارة الموارد البشرية والتنمية الاجتماعية - عند الحاجة - التنسيق مع  وزارة الصحة، لإخضاع مرتكب الإيذاء أو الإهمال لعلاج نفسي أو برامج تأهيلية بما يلائم حالته','2022-03-09'::timestamptz,'مرسوم ملكي رقم م/72 وتاريخ 1443/8/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/2d3cb83a-0379-4cde-8e0b-a9a700f272bd/1','- عدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/72) وتاريخ 1443/8/6هـ، لتكون بالنص الآتي:

"1- على الجهات ذات العلاقة وضع برامج صحية وتربوية وتعليمية ونفسية واجتماعية، لإعادة تأهيل الطفل الذي تعرض لإحدى حالات الإيذاء أو الإهمال.

2- تتولى وزارة الموارد البشرية والتنمية الاجتماعية - عند الحاجة - التنسيق مع  وزارة الصحة، لإخضاع مرتكب الإيذاء أو الإهمال لعلاج نفسي أو برامج تأهيلية بما يلائم حالته".'),
('boe26-103736b6007d8ed83b5ba9f6','cmpz9egl90cd9ybvvh2qx1zmq','يكون شغل وظائف المرتبتين (الرابعة عشرة) و(الخامسة عشرة) بقرار من مجلس الوزراء، ويكون شغل وظائف المرتبة (الثالثة عشرة) فما دون بقرار من الوزير المختص وفقاً للشروط والضوابط والإجراءات المحددة لهذه الوظائف، واستثناءً من ذلك؛ يجوز نقل من يشغل المرتبة (الرابعة عشرة) أو المرتبة (الخامسة عشرة) داخل الجهة بقرار من الوزير المختص، بعد أخذ موافقة رئيس مجلس الوزراء','2017-02-21'::timestamptz,'مرسوم ملكي رقم م/57 وتاريخ 24/5/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/32f651e6-2976-439c-b418-a9a700f23fb2/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/ 57) بتاريخ 24/ 5/ 1438هـ، لتكون بالنص الآتي:

"يكون شغل وظائف المرتبتين (الرابعة عشرة) و(الخامسة عشرة) بقرار من مجلس الوزراء، ويكون شغل وظائف المرتبة (الثالثة عشرة) فما دون بقرار من الوزير المختص وفقاً للشروط والضوابط والإجراءات المحددة لهذه الوظائف، واستثناءً من ذلك؛ يجوز نقل من يشغل المرتبة (الرابعة عشرة) أو المرتبة (الخامسة عشرة) داخل الجهة بقرار من الوزير المختص، بعد أخذ موافقة رئيس مجلس الوزراء".'),
('boe26-4a5b78f9bbbc9c00a83a2135','cmpz9egqs0cdbybvvkzwo534z','تعلن وزارة الخدمة المدنية عن الوظائف التي في المرتبة (العاشرة) فما دون وما يعادلها في سلالم رواتب الخدمة المدنية، ويخضع جميع المتقدمين لشغل هذه الوظائف لتقويم تحدد وزارة الخدمة المدنية مقاييسه وإجراءاته في ضوء متطلبات الوظائف، ويجوز بعد اتفاق وزير الخدمة المدنية والوزير المختص؛ أن تعلن الجهة الإدارية عن الوظائف التي يتفق في شأنها وفق المقاييس والإجراءات التي تحددها وزارة الخدمة المدنية','2017-02-21'::timestamptz,'مرسوم ملكي رقم م/57 وتاريخ 24/5/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/32f651e6-2976-439c-b418-a9a700f23fb2/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/ 57) بتاريخ 24/ 5/ 1438هـ، لتكون بالنص الآتي:

"تعلن وزارة الخدمة المدنية عن الوظائف التي في المرتبة (العاشرة) فما دون وما يعادلها في سلالم رواتب الخدمة المدنية، ويخضع جميع المتقدمين لشغل هذه الوظائف لتقويم تحدد وزارة الخدمة المدنية مقاييسه وإجراءاته في ضوء متطلبات الوظائف، ويجوز بعد اتفاق وزير الخدمة المدنية والوزير المختص؛ أن تعلن الجهة الإدارية عن الوظائف التي يتفق في شأنها وفق المقاييس والإجراءات التي تحددها وزارة الخدمة المدنية".  '),
('boe26-304cbdb61c7ce77d1fc09813','cmpz9ehte0cdpybvv9ludn9f3','لا يجوز للموظف الجمع بين وظيفته وممارسة مهنة أخرى، على أنه يجوز وفق لائحة يصدرها مجلس الوزراء السماح بالاشتغال بالمهن الحرة لمن تقضي المصلحة العامة السماح لهم بذلك؛ للحاجة إلى مهنهم','2017-02-21'::timestamptz,'مرسوم ملكي رقم م/57 وتاريخ 24/5/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/32f651e6-2976-439c-b418-a9a700f23fb2/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/ 57) بتاريخ 24/ 5/ 1438هـ، لتكون بالنص الآتي:

"لا يجوز للموظف الجمع بين وظيفته وممارسة مهنة أخرى، على أنه يجوز وفق لائحة يصدرها مجلس الوزراء السماح بالاشتغال بالمهن الحرة لمن تقضي المصلحة العامة السماح لهم بذلك؛ للحاجة إلى مهنهم".'),
('boe26-a3c285ec98da036bf55b1999','cmpz9eil10cdzybvv7nbg1qr5','أ - يمنح الموظف المعين راتب أول درجة في مرتبة الوظيفة التي عين عليها، فإذا كان راتبه عند التعيين يساوي راتب هذه الدرجة أو يزيد عليه؛ يمنح راتب أول درجة تتجاوز راتبه عند التعيين.

ويجوز التعيين في غير الدرجة الأولى بالنسبة لمن يتوفر لديه مؤهلات معينة يحددها مجلس الوزراء.

ب - يمنح الموظف المرقى راتب أول درجة في مرتبة الوظيفة التي يرقى إليها، فإن كان راتبه عند الترقية يساوي راتب هذه الدرجة أو يزيد عليه؛ فيمنح راتب أول درجة تتجاوز راتبه، على ألا تقل الزيادة التي يحصل عليها المرقى في راتبه عن مقدار العلاوة المحددة للمرتبة التي كان مثبتاً عليها قبل الترقية على المرتبة الأعلى.

ج - إذا أعيد الموظف الذي ترك الخدمة إلى وظيفة في المرتبة نفسها التي كان يشغلها عند انتهاء خدمته؛ فيوضع في الدرجة نفسها التي كان عليها، أما إذا أعيد إلى وظيفة ذات مرتبة أعلى أو أدنى فيمنح راتب أول درجة يتجاوز راتبها راتب الدرجة التي كان يشغلها في السلم المطبق عليه، فإن كان راتبه يزيد على راتب آخر درجة في مرتبة الوظيفة؛ فيمنح هذه الدرجة','2017-02-21'::timestamptz,'مرسوم ملكي رقم م/57 وتاريخ 24/5/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/32f651e6-2976-439c-b418-a9a700f23fb2/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/57) بتاريخ 24/  5/ 1438هـ، لتكون بالنص الآتي:

"أ - يمنح الموظف المعين راتب أول درجة في مرتبة الوظيفة التي عين عليها، فإذا كان راتبه عند التعيين يساوي راتب هذه الدرجة أو يزيد عليه؛ يمنح راتب أول درجة تتجاوز راتبه عند التعيين.

ويجوز التعيين في غير الدرجة الأولى بالنسبة لمن يتوفر لديه مؤهلات معينة يحددها مجلس الوزراء.

ب - يمنح الموظف المرقى راتب أول درجة في مرتبة الوظيفة التي يرقى إليها، فإن كان راتبه عند الترقية يساوي راتب هذه الدرجة أو يزيد عليه؛'),
('boe26-5253d8221fb9fc5611c10d1b','cmpzcvd6a0c4hvtrk21l17lu3','( المادة السابعة بعد المائة: المركز الوطني لسلامة النقل (المركز) واختصاصه)

يتولى المركز التحقيق في الحوادث والوقائع التي تقع للطائرات المدنية في إقليم المملكة وللطائرات السعودية وللطائرات التي يشغلها أشخاص يحملون الجنسية السعودية فوق أعالي البحار أو فوق الأراضي غير المملوكة لإحدى الدول وفقاً للشروط والضوابط التي تحددها لائحة التحقيق. وللمركز في سبيل ذلك القيام بما يأتي:

أ- وضع لائحة التحقيق واعتمادها من مجلس إدارة المركز.

ب- تشكيل لجان التحقيق وتحديد صلاحياتها وتحديد القواعد الواجب مراعاتها، لإجراء التحقيق في هذه الحوادث والوقائع.

ج- إعداد تقرير عن الحالات والظروف المتعلق بكل حادث طيران يتم التحقيق فيه، وبيان أسبابه ونتائجه، وأي إجراءات أو قواعد يوصي بها لمنع تكرار مثل هذا الحادث مستقبلاً.

د- إصدار التعليمات والقواعد الواجب مراعاتها، لضمان تأمين سلامة الطيران وتلافي وقوع حوادث الطيران مستقبلاً.

هـ- نشر نتائج التحقيق في حوداث الطيران بعد اعتمادها من مجلس إدارة المركز.

يجوز للمركز في المملكة -بناءً على طلب السلطات المختصة في إحدى الدول الأجنبية التي يقع في إقليمها حادث طيران لطائرة مدنية سعودية، أو لطائرة يشغلها شخص يحمل الجنسية السعودية- أن يقوم بإجراء التحقيق الفني في الحادث، أو أن يشترك فيه.

يجوز للمركز إجراء التحقيق في حوادث الطيران التي تقع لأي طائرة مدنية في إقليم دولة أخرى بناء على طلب السلطات المختصة في هذه الدولة، وذلك بشرط أن تتحمل تلك الدولة جميع التكاليف والنفقات اللازمة والمترتبة على إجراء هذا التحقيق','2023-09-05'::timestamptz,'قرار مجلس الوزراء رقم 158 وتاريخ 1445/2/20هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/33ef05e2-f53e-4340-b5cb-a9a700f2ead1/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (158) وتاريخ 1445/2/20هـ، لتكون على النحو الآتي:

"( المادة السابعة بعد المائة: المركز الوطني لسلامة النقل (المركز) واختصاصه)

يتولى المركز التحقيق في الحوادث والوقائع التي تقع للطائرات المدنية في إقليم المملكة وللطائرات السعودية وللطائرات التي يشغلها أشخاص يحملون الجنسية السعودية فوق أعالي البحار أو فوق الأراضي غير المملوكة لإحدى الدول وفقاً للشروط والضوابط التي تحددها لائحة التحقيق. وللمركز في سبيل ذلك القيام بما يأتي:

أ- وضع لائحة التحقيق و'),
('boe26-4404a78c5780e13d07081555','cmpzcut6d06i0vtrkmtc03ant','المؤسسة العامة لتحلية المياه المالحة ، مؤسسة عامة مستقلة تتمتع بالشخصية الاعتبارية ، ولها جميع الحقوق اللازمة لممارسة نشاطها ، وتتبع إداريا وزير المياه والكهرباء ، ومقرها الرئيس في مدينة الرياض ، ولها أن تنشئ فروعا أو مكاتب في المناطق أو المدن التي يقررها مجلس الإدارة .','2005-04-06'::timestamptz,'مرسوم ملكي رقم م/10 وتاريخ 27/2/1426هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/37f95015-f360-45be-8f91-a9a700f244c1/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/10) وتاريخ 27 / 2 / 1426 هـ ، لتصبح بالنص الآتى :

"المادة الأولى :

المؤسسة العامة لتحلية المياه المالحة ، مؤسسة عامة مستقلة تتمتع بالشخصية الاعتبارية ، ولها جميع الحقوق اللازمة لممارسة نشاطها ، وتتبع إداريا وزير المياه والكهرباء ، ومقرها الرئيس في مدينة الرياض ، ولها أن تنشئ فروعا أو مكاتب في المناطق أو المدن التي يقررها مجلس الإدارة ."'),
('boe26-f29429fe77a695f2e58a51e3','cmpzcut6d06i3vtrk9dd0hrsg','يكون للمؤسسة مجلس إدارة يشكل على النحو الآتي:

ـ وزير المياه والكهرباء رئيساً

- محافظ المؤسسة نائباً للرئيس

ـ وكيل وزارة المياه والكهرباء عضواً

ـ وكيل وزارة الشؤون البلدية والقروية عضواً

ـ وكيل وزارة المالية عضواً

ـ وكيل وزارة البترول والثروة المعدنية عضواً

ـ وكيل وزارة الاقتصاد والتخطيط عضواً

ـ عضوان من القطاع الأهلي من ذوي الكفاية والأهلية يعنيان بقرار مدة عضويتهما ثلاث سنوات قابلة للتجديد مرة واحدة','2005-04-06'::timestamptz,'مرسوم ملكي رقم م/10 وتاريخ 27/2/1426هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/37f95015-f360-45be-8f91-a9a700f244c1/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/10) وتاريخ 27 / 2 / 1426 هـ ، لتصبح بالنص الآتى :

يكون للمؤسسة مجلس إدارة يشكل على النحو الآتي:

ـ وزير المياه والكهرباء رئيساً

- محافظ المؤسسة نائباً للرئيس

ـ وكيل وزارة المياه والكهرباء عضواً

ـ وكيل وزارة الشؤون البلدية والقروية عضواً

ـ وكيل وزارة المالية عضواً

ـ وكيل وزارة البترول والثروة المعدنية عضواً

ـ وكيل وزارة الاقتصاد والتخطيط عضواً

ـ عضوان من القطاع الأهلي من ذوي الكفاية والأهلية يعنيان بقرار مدة عضويتهما ثلاث سنوات قابلة للتجديد مرة'),
('boe26-d06e2cbd567f483bee75e0df','cmpz64hh4047rcwg2v50hp81x','تُشترط موافقة البنك المركزي السعودي على ترشيح أعضاء مجالس إدارات شركات التأمين وشركات إعادة التأمين وشركات مزاولي الخدمات المساندة للتأمين، وأعضاء لجان المراجعة واللجان المنبثقة عن هذه المجالس، ومديري تلك الشركات، والوظائف العليا التي يحددها البنك المركزي السعودي. ويضع البنك المركزي السعودي الضوابط الخاصة بتعيينهم.','2021-08-31'::timestamptz,'مرسوم ملكي رقم م/12 وتاريخ 1443/1/23هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/3e3c6fc3-9a45-4a0e-b28e-a9a700f1ad14/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/12) وتاريخ 1443/1/23هـ، لتكون بالنص الآتي:

" تُشترط موافقة البنك المركزي السعودي على ترشيح أعضاء مجالس إدارات شركات التأمين وشركات إعادة التأمين وشركات مزاولي الخدمات المساندة للتأمين، وأعضاء لجان المراجعة واللجان المنبثقة عن هذه المجالس، ومديري تلك الشركات، والوظائف العليا التي يحددها البنك المركزي السعودي. ويضع البنك المركزي السعودي الضوابط الخاصة بتعيينهم."'),
('boe26-75c56adaf5da20973a3a66f5','cmpz64jwx048jcwg2hrvgnswh','1 - تشكل لجنة ابتدائية (أو أكثر) بقرار من مجلس الوزراء من عدد لا يقل عن ثلاثة أعضاء متفرغين – إن أمكن – من ذوي الاختصاص، يكون أحدهم على الأقل مستشارًا نظاميًا، وتكون مدة العضوية ثلاث سنوات قابلة للتجديد، وتتولى الفصل فيما يأتي:

أ – جميع المنازعات الناشئة عن عقود التأمين، بما فيها التي تقع بين شركات التأمين وعملائها والمستفيدين من التغطيات التأمينية، أو بين هذه الشركات وغيرها في حالة حلولها محل المؤمن له.

ب - المنازعات التي تقع بين شركات التأمين وشركات إعادة التأمين أو فيما بين كل منها، أو المنازعات التي تقع بين تلك الشركات ومزاولي المهن الحرة المتعلقة بنشاط التأمين.

ج - مخالفة التعليمات الرقابية والإشرافية لشركات التأمين وإعادة التأمين أو أي من هذين النشاطين.

د - مخالفات مزاولي المهن الحرة المشار إليها في المادة (الثامنة عشرة) من هذا النظام.

هـ - المخالفات الناشئة عن تطبيق هذا النظام، وإيقاع الغرامات المنصوص عليها في المادة (الحادية والعشرين) من هذا النظام.

2 - إذا كانت المخالفة تنطوي على جريمة، فعلى اللجنة إحالتها إلى جهة التحقيق المختصة للتحقيق مع المخالف تمهيدًا لإقامة الدعوى أمام المحكمة الجزائية المختصة، للنظر في توقيع العقوبات الواردة في هذا النظام أو أي نظام آخر بحسب الأحوال. على أنه إذا رأت جهة التحقيق المختصة أنه لا وجه لإقامة الدعوى في الشق الجنائي، فعليها إعادة الأوراق إلى اللجنة للنظر في المخالفة واتخاذ ما يلزم حيالها وفقًا لما ورد في هذا النظام','2013-04-08'::timestamptz,'مرسوم ملكي رقم م/30 وتاريخ 27/5/1434هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/3e3c6fc3-9a45-4a0e-b28e-a9a700f1ad14/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/30 ) وتاريخ 27 / 5 / 1434 هـ، لتكون بالنص الآتى :

"1 - تشكل لجنة ابتدائية (أو أكثر) بقرار من مجلس الوزراء من عدد لا يقل عن ثلاثة أعضاء متفرغين – إن أمكن – من ذوي الاختصاص، يكون أحدهم على الأقل مستشارًا نظاميًا، وتكون مدة العضوية ثلاث سنوات قابلة للتجديد، وتتولى الفصل فيما يأتي:

أ – جميع المنازعات الناشئة عن عقود التأمين، بما فيها التي تقع بين شركات التأمين وعملائها والمستفيدين من التغطيات التأمينية، أو بين هذه الشركات وغيرها في حالة حلولها محل ا'),
('boe26-af8f461dcc14413641c8cd84','cmpz64jwx048jcwg2hrvgnswh','تشكل بقرار من مجلس الوزراء لجنة ابتدائية (أو أكثر) من أعضاء من ذوي الاختصاص لا يقل عددهم عن ثلاثة، ويكونون متفرغين إن أمكن، ويكون أحدهم - على الأقل - مستشاراً نظاميًّا، وتكون مدة العضوية ثلاث سنوات قابلة للتجديد؛ تتولى ما يأتي:

الفصل في جميع المنازعات الناشئة عن عقود التأمين، بما فيهم التي تقع بين شركات التأمين وعملائها والمستفيدين من التغطيات التأمينية، أو بين هذه الشركات والغير في حالة حلولها محل المؤَّمن له، والمنازعات الناشئة بين مزاولي الخدمات المساندة للتأمين وعملائهم.

الفصل في جميع المنازعات التي تقع بين شركات التأمين وشركات إعادة التأمين ومزاولي الخدمات المساندة للتأمين.

النظر في تظلم ذوي الشأن من العقوبات والإجراءات الصادرة من البنك المركزي السعودي بحقهم وفق المادة (التاسعة عشرة) من هذا النظام، على أن يقدم التظلم إلى اللجنة خلال (ثلاثين) يوماً من تاريخ إبلاغ المركزي السعودي لهم بالإجراء. ويحق للجنة إصدار قرار بالتعويض أو إعادة الحال إلى ما كانت عليه أو إصدار أي قرار آخر تراه مناسباً ويضمن حق المتضرر.

النظر في قرارات إلغاء التراخيص التي تصدر من البنك المركزي السعودي.','2021-08-31'::timestamptz,'مرسوم ملكي رقم م/12 وتاريخ 1443/1/23هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/3e3c6fc3-9a45-4a0e-b28e-a9a700f1ad14/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/12) وتاريخ 1443/1/23هـ، لتكون بالنص الآتي:

" تشكل بقرار من مجلس الوزراء لجنة ابتدائية (أو أكثر) من أعضاء من ذوي الاختصاص لا يقل عددهم عن ثلاثة، ويكونون متفرغين إن أمكن، ويكون أحدهم - على الأقل - مستشاراً نظاميًّا، وتكون مدة العضوية ثلاث سنوات قابلة للتجديد؛ تتولى ما يأتي:

الفصل في جميع المنازعات الناشئة عن عقود التأمين، بما فيهم التي تقع بين شركات التأمين وعملائها والمستفيدين من التغطيات التأمينية، أو بين هذه الشركات والغير في حالة حلولها محل'),
('boe26-9f949fdc2b683e22dfd42186','cmpz6ggv2089rcwg2spywcgmz','تتمتع الهيئة بالشخصية الاعتبارية وبالاستقلال المالي والإداري، ويكون مقرها الرئيس في مدينة الرياض، ولها أن تنشى فروعاً أو مكاتب تابعة لها داخل المملكة بحسب الحاجة','2025-10-14'::timestamptz,'قرار مجلس الوزراء رقم 283 وتاريخ 1447/4/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/3fd2d5d4-e39f-4543-a69f-ad0100b32c4d/1','- عُدلت هذه المادة وذلك  بموجب قرار مجلس الوزراء رقم (283) وتاريخ 1447/4/22هـ، لتصبح بالنص الآتي:

"تتمتع الهيئة بالشخصية الاعتبارية وبالاستقلال المالي والإداري، ويكون مقرها الرئيس في مدينة الرياض، ولها أن تنشى فروعاً أو مكاتب تابعة لها داخل المملكة بحسب الحاجة".'),
('boe26-975d742d70aee7d7eb38d39c','cmpzcvb5l0bjhvtrk3fkyerej','1 - تستوفى مبالغ الأجور والإيجارات المقررة بموجب هذا النظام، وتودع في حساب الهيئة في مؤسسة النقد العربي السعودي وفقاً للأنظمة المعمول بها في المملكة.
2 - في حالة تأخير سداد الأجور عن موعد الاستحقاق، رغم تكرار المطالبة بالسداد، وعدم وجود ضمان يستوفى منه مبلغ الأجر، يعد المتأخر عن السداد مماطلاً، وتستوفى منه غرامة تأخير لا تتجاوز (30%) ثلاثين في المائة من المبلغ المستحق، وتودع الغرامة في الخزينة العامة للدولة.
3 - على الهيئة تضمين العقد الذي تبرمه مع المستأجر نصاً يقضي بإلزامه بتقديم ضمان بنكي عند توقيع العقد بما يعادل ما نسبته (30%) ثلاثون في المائة من قيمته، كضمان لاستيفاء الإيجار المستحق عليه، ويكون هذا الضمان ساري المفعول وغير قابل للإلغاء إلا بعد انتهاء مدة العقد وبموافقة الهيئة، ويستوفى منه أيُّ مبلغ يُستحق على المستأجر فور استحقاقه وفق أحكام العقد، مع مطالبته بتغطية ما نقص من مبلغ الضمان فوراً','2017-07-11'::timestamptz,'مرسوم ملكي رقم م/105 وتاريخ 17/10/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/456ab486-9c16-4c7b-993c-a9a700f2cc4a/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/ 105) بتاريخ 17/ 10/ 1438هـ، لتكون بالنص الآتي:

"1 - تستوفى مبالغ الأجور والإيجارات المقررة بموجب هذا النظام، وتودع في حساب الهيئة في مؤسسة النقد العربي السعودي وفقاً للأنظمة المعمول بها في المملكة.
2 - في حالة تأخير سداد الأجور عن موعد الاستحقاق، رغم تكرار المطالبة بالسداد، وعدم وجود ضمان يستوفى منه مبلغ الأجر، يعد المتأخر عن السداد مماطلاً، وتستوفى منه غرامة تأخير لا تتجاوز (30%) ثلاثين في المائة من المبلغ المستحق، وتودع الغرامة في الخزينة العام'),
('boe26-3e8edcb4c676fbe3e6636cda','cmpzcvb5l0bjsvtrkqgks84p0','يقوم مجلس الإدارة باتخاذ الآتي:

1   -	مراجعة الأجور والإيجارات وفئاتها الواردة في هذا النظام، وتعديلها واعتمادها، متى اقتضت الحاجة ذلك، وعليه عند قيامه بذلك مراعاة الآتي:

أ‌ - أن تكون فئات الأجور والإيجارات ضمن المعايير المعمول بها وضمن الأسعار المنافسة دولياً وإقليمياً.

ب‌ - أن تكون الأجور والإيجارات محفزة لشركات الطيران الدولية والخاصة للتشغيل في مطارات المملكة واستخدام مرافقها والاستفادة من خدماتها.

ج - الأخذ في الاعتبار الأهمية الاستراتيجية لبعض المطارات من حيث ازدحامها أو تدني نسبة الحركة فيها، والتفريق – كلما كان ذلك مناسباً – بين أوقات الذروة خلال الموسم والأوقات الأخرى.

2 - استحداث فئات للخدمات التي تقدمها الهيئة، وتحديد مبالغ أجورها، وتعديلها، متى اقتضت الحاجة لذلك.

3 - 	اعتماد أجور خدمات المطارات والملاحة الجوية في حال تقديم القطاع الخاص لها','2015-04-28'::timestamptz,'مرسوم ملكي رقم م/53 وتاريخ 9/7/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/456ab486-9c16-4c7b-993c-a9a700f2cc4a/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م / 53) وتاريخ 9 / 7 / 1436هـ،  لتصبح بالنص الآتي:

"يقوم مجلس الإدارة باتخاذ الآتي:

1   -	مراجعة الأجور والإيجارات وفئاتها الواردة في هذا النظام، وتعديلها واعتمادها، متى اقتضت الحاجة ذلك، وعليه عند قيامه بذلك مراعاة الآتي:

أ‌ - أن تكون فئات الأجور والإيجارات ضمن المعايير المعمول بها وضمن الأسعار المنافسة دولياً وإقليمياً.

ب‌ - أن تكون الأجور والإيجارات محفزة لشركات الطيران الدولية والخاصة للتشغيل في مطارات المملكة واستخدام مرافقها والاستفادة من خ'),
('boe26-0ecee60b4df420720f91bad2','cmpz65k2004kjcwg2fopadkq8','مع مراعاة ما تقتضي به الأنظمة الأخرى، يعاقب بالحبس مدة لا تزيد على ثلاث سنوات وبغرامة لا تزيد على خمسين ألف ريال أو بإحدى هاتين العقوبتين كل من أقدم بسوء نية على ارتكاب أحد الأفعال الآتية:

أ - إذا سحب شيكا لا يكون له مقابل وفاء قائم وقابل للسحب أو يكون له مقابل وفاء أقل من قيمة الشيك.

ب - إذا استرد بعد إعطاء الشيك مقابل الوفاء أو بعضه بحيث أصبح الباقي لا يفي بقيمة الشيك. 

ج - إذا أمر المسحوب عليه بعدم دفع قيمة الشيك .

د - إذا تعمد تحرير الشيك أو التوقيع عليه بصورة تمنع صرفه.

هـ - إذا ظهر أو سلم شيكا وهو يعلم أنه ليس له مقابل يفي بقيمته أو أنه غير قابل للصرف.

و- إذا تلقى المستفيد أو الحامل شيكا لا يوجد له مقابل وفاء كاف لدفع قيمته.

فإذا عاد الجاني إلى ارتكاب أي من هذه الجرائم خلال ثلاث سنوات من تاريخ الحكم عليه في أي منها تكون العقوبة الحبس مدة لا تزيد على خمس سنوات والغرامة التي لا تزيد على مائة ألف ريال أو إحدى هاتين العقوبتين.','1989-04-18'::timestamptz,'مرسوم ملكي رقم م/45 وتاريخ 12/9/1409هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4763eb94-047b-46f1-9697-a9a700f1b7ed/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/45) وتاريخ 12 / 9 / 1409 هـ ، لتكون كما يلى :

مع مراعاة ما تقتضي به الأنظمة الأخرى، يعاقب بالحبس مدة لا تزيد على ثلاث سنوات وبغرامة لا تزيد على خمسين ألف ريال أو بإحدى هاتين العقوبتين كل من أقدم بسوء نية على ارتكاب أحد الأفعال الآتية:

أ - إذا سحب شيكا لا يكون له مقابل وفاء قائم وقابل للسحب أو يكون له مقابل وفاء أقل من قيمة الشيك.

ب - إذا استرد بعد إعطاء الشيك مقابل الوفاء أو بعضه بحيث أصبح الباقي لا يفي بقيمة الشيك. 

ج - إذا أمر المسحوب عليه بعدم د'),
('boe26-ef53b1412d3e414cc9a75365','cmpz65k7y04klcwg20qvmao6h','مع مراعاة ما تقضي به الأنظمة الأخرى، يعاقب بغرامة لا تزيد على مائة ألف ريال كل مسحوب عليه رفض بسوء نية وفاء شيك مسحوب سحبا صحيحا وله مقابل وفاء ولم تقدم بشأنه أية معارضة مع عدم الإخلال بالتعويض المستحق للساحب عما أصابه من ضرر بسبب عدم الوفاء.
ويعاقب بهذه العقوبة كل مسحوب عليه صرح عن علم بوجود مقابل وفاء هو أقل مما لديه فعلا.','1989-04-18'::timestamptz,'مرسوم ملكي رقم م/45 وتاريخ 12/9/1409هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4763eb94-047b-46f1-9697-a9a700f1b7ed/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/45) وتاريخ 12 / 9 / 1409 هـ ، لتكون كما يلى :

مع مراعاة ما تقضي به الأنظمة الأخرى، يعاقب بغرامة لا تزيد على مائة ألف ريال كل مسحوب عليه رفض بسوء نية وفاء شيك مسحوب سحبا صحيحا وله مقابل وفاء ولم تقدم بشأنه أية معارضة مع عدم الإخلال بالتعويض المستحق للساحب عما أصابه من ضرر بسبب عدم الوفاء.
ويعاقب بهذه العقوبة كل مسحوب عليه صرح عن علم بوجود مقابل وفاء هو أقل مما لديه فعلا.'),
('boe26-66c318614d99728d6a120f4f','cmpzcv47909hqvtrkuv3hlxxt','يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية','2021-07-13'::timestamptz,'قرار مجلس الوزراء رقم 722 وتاريخ 1442/12/3هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/49ab78f2-a4ad-42f8-97ce-a9a700f28035/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (722) وتاريخ 1442/12/3هـ، لتصبح بالنص الآتي: "يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية".'),
('boe26-30924a895fec67d43a460027','cmpzcv47a09i9vtrk6iwr8tfn','يُمنح الترخيص للمختبرات بشرط التزام الترخيص بتوفير الكوادر اللازمة من المتخصصين المؤهلين علمياً، والمعدات والأجهزة اللازمة للعمل بالمختبر بما يتفق مع حجم العمل وطبيعته، وفقاً لما تحدده الجهة المختصة والمركز','2021-11-11'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص لآتي: 

" يُمنح الترخيص للمختبرات بشرط التزام الترخيص بتوفير الكوادر اللازمة من المتخصصين المؤهلين علمياً، والمعدات والأجهزة اللازمة للعمل بالمختبر بما يتفق مع حجم العمل وطبيعته، وفقاً لما تحدده الجهة المختصة والمركز".'),
('boe26-45ec8a54bc5f9e8f8fc6cf13','cmpzcv47a09iavtrky7ff6fen','تحدد اللائحة التنفيذية فئات المختبرات والشروط اللازم توافرها لكل فئة، بناءً على توصية من المركز','2021-11-11'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص الآتي:

" تحدد اللائحة التنفيذية فئات المختبرات والشروط اللازم توافرها لكل فئة، بناءً على توصية من المركز".'),
('boe26-8eec732c245d87108092a4fd','cmpzcv47a09icvtrkkt0cowb5','يُعطى المرخص له مهلة لا تزيد على سنة ونصف تبدأ من تاريخ حصوله على الترخيص لإكمال الحصول على الاعتماد من المركز. وفي حال انقضاء المهلة دون الحصول على الاعتماد يعد الترخيص ملغياً','2021-11-11'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص الآتي:

" يُعطى المرخص له مهلة لا تزيد على سنة ونصف تبدأ من تاريخ حصوله على الترخيص لإكمال الحصول على الاعتماد من المركز. وفي حال انقضاء المهلة دون الحصول على الاعتماد يعد الترخيص ملغياً".'),
('boe26-dcac1abd8ff5dc641302e168','cmpzcv47a09idvtrkuqbounl4','أ- تصدر الجهة المختصة الترخيص للمختبر الخاص بعد تسديد رسم الترخيص، ومقداره خمسة آلاف (5000) ريال للمختبر الرئيس، وألفان وخمسمائة (2500) ريال لكل فرع.

ب- مدة صلاحية الترخيص خمس سنوات تبدأ من تاريخ المهلة الواردة في المادة (السادسة) من هذا النظام، ويُجدد بطلب من صاحب الشأن يقدمه إلى الجهة المختصة قبل ثلاثة أشهر على الأقل من تاريخ انتهاء مدته. ويكون التجديد من تاريخ انتهاء الترخيص','2021-11-11'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص الآتي:

" أ- تصدر الجهة المختصة الترخيص للمختبر الخاص بعد تسديد رسم الترخيص، ومقداره خمسة آلاف (5000) ريال للمختبر الرئيس، وألفان وخمسمائة (2500) ريال لكل فرع.

ب- مدة صلاحية الترخيص خمس سنوات تبدأ من تاريخ المهلة الواردة في المادة (السادسة) من هذا النظام، ويُجدد بطلب من صاحب الشأن يقدمه إلى الجهة المختصة قبل ثلاثة أشهر على الأقل من تاريخ انتهاء مدته. ويكون التجديد من تاريخ انتهاء الترخيص".'),
('boe26-8d7da5c68cee56ec604e892a','cmpzcv47a09ievtrk8luchk4j','تصدر الجهة المختصة قراراً بالسلع المزمع فحصها بواسطة المختبر الخاص قبل (ستين) يوماً من إسناد المهمة إلى المختبر الخاص، وبعد الإعلان عنها في الجريدة الرسمية، وتبلّغ هيئة الزكاة والضريبة والجمارك بذلك','2021-11-11'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص الآتي:

" تصدر الجهة المختصة قراراً بالسلع المزمع فحصها بواسطة المختبر الخاص قبل (ستين) يوماً من إسناد المهمة إلى المختبر الخاص، وبعد الإعلان عنها في الجريدة الرسمية، وتبلّغ هيئة الزكاة والضريبة والجمارك بذلك".'),
('boe26-5ab5e2ad6e292891836eb9a4','cmpzcv47a09imvtrkd3tdfv5u','يصدر وزير التجارة - بالاتفاق مع كل من وزارات: ( الداخلية، والصحة، والبيئة والمياه والزراعة، والصناعة والثروة المعدنية، والشؤون البلدية والقروية والإسكان)، والهيئة العامة للغذاء والدواء - اللائحة التنفيذية لهذا النظام','2021-11-11'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص الآتي:

"يصدر وزير التجارة - بالاتفاق مع كل من وزارات: ( الداخلية، والصحة، والبيئة والمياه والزراعة، والصناعة والثروة المعدنية، والشؤون البلدية والقروية والإسكان)، والهيئة العامة للغذاء والدواء - اللائحة التنفيذية لهذا النظام".'),
('boe26-2a30025ac75853d671d5ef02','cmpz9er1l0cgzybvvjjzcnxje','تبدأ السنة المالية للمؤسسة من أول شهر يناير وتنتهي بنهاية شهر ديسمبر من كل عام ميلادي','2019-04-02'::timestamptz,'قرار مجلس الوزراء رقم 429 وتاريخ 26/7/1440هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/5160cfca-da74-4008-97e2-a9a700f23b92/1','•المادة الثانية عشرة

-عُدلت هذه المادة بموجب قرار مجلس الوزراء رقم (429) وتاريخ 26 /7 / 1440هـ، لتكون بالنص الآتي: "تبدأ السنة المالية للمؤسسة من أول شهر يناير وتنتهي بنهاية شهر ديسمبر من كل عام ميلادي".

 '),
('boe26-f3264c4db8cfd3b47cd2cd6e','cmpzcvbts0bojvtrktcoy9nt7','تنشأ بمقتضى هذا التنظيم جمعية تسمى الجمعية السعودية للمراجعين الداخليين، وهي جمعية مهنية ذات شخصية اعتبارية وذمة مالية مستقلة، تعمل تحت إشراف الجهة التي يصدر بتحديدها أمر من رئيس مجلس الوزراء بناءً على اقتراح مجلس الشؤون الاقتصادية والتنمية، مقرها الرئيس مدينة الرياض. ولها –بقرار من مجلس الإدارة- إنشاء فروع أو مكاتب ف مدن أخرى داخل المملكة','2020-09-08'::timestamptz,'قرار مجلس الوزراء رقم 57 وتاريخ 20/1/1442هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/5203b65e-bf51-4e81-8701-a9a700f2d4b7/1','- عُدلت هذه المادة بموجب قرار مجلس الوزراء رقم (57) وتاريخ 20 / 1 / 1442هـ، لتكون بالنص الآتي:

" تنشأ بمقتضى هذا التنظيم جمعية تسمى الجمعية السعودية للمراجعين الداخليين، وهي جمعية مهنية ذات شخصية اعتبارية وذمة مالية مستقلة، تعمل تحت إشراف الجهة التي يصدر بتحديدها أمر من رئيس مجلس الوزراء بناءً على اقتراح مجلس الشؤون الاقتصادية والتنمية، مقرها الرئيس مدينة الرياض. ولها –بقرار من مجلس الإدارة- إنشاء فروع أو مكاتب ف مدن أخرى داخل المملكة".'),
('boe26-f726af8cf6e441f01a06dcad','cmpzcut6e06isvtrkvmi3ks5j','كل من يخالف أحكام هذا النظام ولوائحه التنفيذية يعاقب بغرامة لا تتجاوز مائة ألف ريـال، ويجوز تضمين قرار العقوبة النص على نشر منطوقه على نفقة المخالف في صحيفة محلية تصدر في مكان إقامته، فإن لم يكن في مكان إقامته صحيفة ففي أقرب منطقة له، أو نشره في أي وسيلة أخرى مناسبة، وذلك بحسب نوع المخالفة المرتكبة وجسامتها وآثارها، على أن يكون نشر القرار بعد تحصنه بمضي المدة المحددة نظاما أو تأييده من المحكمة المختصة','2017-01-17'::timestamptz,'مرسوم ملكي رقم م/37 وتاريخ 19/4/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/588efd09-dc0d-4491-82e4-a9a700f245f6/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/37) بتاريخ 19/ 4/ 1438هـ، لتصبح بالنص الآتي:

"كل من يخالف أحكام هذا النظام ولوائحه التنفيذية يعاقب بغرامة لا تتجاوز مائة ألف ريـال، ويجوز تضمين قرار العقوبة النص على نشر منطوقه على نفقة المخالف في صحيفة محلية تصدر في مكان إقامته، فإن لم يكن في مكان إقامته صحيفة ففي أقرب منطقة له، أو نشره في أي وسيلة أخرى مناسبة، وذلك بحسب نوع المخالفة المرتكبة وجسامتها وآثارها، على أن يكون نشر القرار بعد تحصنه بمضي المدة المحددة نظاما أو تأييده من المحكمة المختصة"'),
('boe26-62cf4c4de0e6f29dbbe3fbbc','cmpzcv7lk0ajwvtrkvasra2qf','أولاً: أن يكون التقديم على طلب دعم الصندوق قبل نهاية 31 ديسمبر 2022م.

ثانياً: أن يكون مبلغ دعم الصندوق هو (30%) من راتب المستفيد، ويضاف عليه نسب الدعم التفضيلي (10%) بحسب الشروط والأحكام الصادرة من مجلس إدارة الصندوق، على ألا يتجاوز مبلغ الدعم (3000) ريال.

ثالثاً: أن يكون دعم الصندوق لنشاط الإيواء السياحي في مدينتي (مكة المكرمة، والمدينة المنورة).

رابعاً: أن يستمر المستفيد -خلال السنة الإضافية- في المرفق السياحي الذي تم طلب الدعم عليه.

خامساً: ألا يكون المرفق السياحي من ضمن قائمة المنشآت المستبعدة من دعم الصندوق.','2022-11-15'::timestamptz,'قرار مجلس الوزراء رقم 297 وتاريخ 1444/4/21هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/5a16cf9b-e1b8-426f-82ab-a9a700f2a640/1','- عُدلت مدة تحمل الصندوق لمن دعمهم الصندوق مسبقاً في مدينتي ( مكة المكرمة، و المدينة المنورة ) لتكون ثلاث سنوات بدلاً من سنتين، وذلك بموجب قرار مجلس الوزراء رقم (297) وتاريخ 1444/4/21هـ، وتكون وفقاً للآتي:

أولاً: أن يكون التقديم على طلب دعم الصندوق قبل نهاية 31 ديسمبر 2022م.

ثانياً: أن يكون مبلغ دعم الصندوق هو (30%) من راتب المستفيد، ويضاف عليه نسب الدعم التفضيلي (10%) بحسب الشروط والأحكام الصادرة من مجلس إدارة الصندوق، على ألا يتجاوز مبلغ الدعم (3000) ريال.

ثالثاً: أن يكون دعم الصندوق لنشاط '),
('boe26-0e9a3ce9cefcea540d39cb5e','cmpz61pa903b7cwg233xu7b8g','يدرس المركز الطلب، بعد استكمال المتطلبات المشار إليها في المادة (الرابعة) من النظام؛ للنظر في الموافقة - ما لم تقتضِ المصلحة خلاف ذلك - على منح المتقدم الإقامة المميزة، وتصدر بقرار من رئيس المركز، وذلك وفقاً للأحكام الواردة في النظام واللائحة','2023-12-24'::timestamptz,'مرسوم ملكي رقم م/84 وتاريخ 1445/6/11هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/5e9762df-2b15-4e66-8cdc-aa5200f62042/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/84) وتاريخ 1445/6/11هـ، لتصبح بالنص الآتي:

"يدرس المركز الطلب، بعد استكمال المتطلبات المشار إليها في المادة (الرابعة) من النظام؛ للنظر في الموافقة - ما لم تقتضِ المصلحة خلاف ذلك - على منح المتقدم الإقامة المميزة، وتصدر بقرار من رئيس المركز، وذلك وفقاً للأحكام الواردة في النظام واللائحة".'),
('boe26-47873d30f749dec72db5be97','cmpz6gduo088ncwg2o2h6frn5','1- يقدم طلب الترخيص إلى الهيئة وفقاً للإجراءات التي يحددها المجلس.

2- تصدر الهيئة قرارها بالموافقة على منح الترخيص، أو بالرفض مسبباً لطلب الترخيص، خلال مدة تحددها اللائحة. ولطالب الترخيص التظلم من قرار الرفض أمام المحكمة الإدارية.

3- تحدد اللائحة إجراءات دراسة طلب الترخيص والبت فيه، ومدته وشروط تجديده.

4- يحدد المجلس المقابل المالي للترخيص','2025-02-09'::timestamptz,'مرسوم ملكي رقم م/169 وتاريخ 1446/8/10هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/6435e205-a7ae-4a8c-9580-ad0000b6bef2/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/169) وتاريخ 1446/8/10هـ، لتصبح بالنص الآتي:

"1- يقدم طلب الترخيص إلى الهيئة وفقاً للإجراءات التي يحددها المجلس.

2- تصدر الهيئة قرارها بالموافقة على منح الترخيص، أو بالرفض مسبباً لطلب الترخيص، خلال مدة تحددها اللائحة. ولطالب الترخيص التظلم من قرار الرفض أمام المحكمة الإدارية.

3- تحدد اللائحة إجراءات دراسة طلب الترخيص والبت فيه، ومدته وشروط تجديده.

4- يحدد المجلس المقابل المالي للترخيص".'),
('boe26-ab8277e40824805b4b43abd9','cmpz6ge03088pcwg236bq94if','دون إخلال بالعقوبات المنصوص عليها في المادة (العاشرة) من النظام، للهيئة إصدار قرار بإلغاء الترخيص. ويجوز لمن صدر قرار إلغاء ترخيصه التظلم منه أمام المحكمة الإدارية. ولا يترتب على إلغاء الترخيص إلغاء عضويته بالهيئة','2025-02-09'::timestamptz,'مرسوم ملكي رقم م/169 وتاريخ 1446/8/10هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/6435e205-a7ae-4a8c-9580-ad0000b6bef2/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/169) وتاريخ 1446/8/10هـ، لتصبح بالنص الآتي: "دون إخلال بالعقوبات المنصوص عليها في المادة (العاشرة) من النظام، للهيئة إصدار قرار بإلغاء الترخيص. ويجوز لمن صدر قرار إلغاء ترخيصه التظلم منه أمام المحكمة الإدارية. ولا يترتب على إلغاء الترخيص إلغاء عضويته بالهيئة".'),
('boe26-b20df1bef4fc72ab90a56378','cmpz6gg9h089jcwg21ekfjkns','دون إخلال باختصاصات الجهات المعنية، يتولى موظفون من الهيئة -يصدر بتسميتهم قرار من المجلس- ضبط ما يُرتكب من الجرائم المنصوص عليها في المادة (العاشرة) من النظام، وما يُرتكب من مخالفات لأحكام النظام ولائحته والقرارات الصادرة تنفيذاً لهما','2025-02-09'::timestamptz,'مرسوم ملكي رقم م/169 وتاريخ 1446/8/10هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/6435e205-a7ae-4a8c-9580-ad0000b6bef2/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/169) وتاريخ 1446/8/10هـ، لتصبح بالنص الآتي: "دون إخلال باختصاصات الجهات المعنية، يتولى موظفون من الهيئة -يصدر بتسميتهم قرار من المجلس- ضبط ما يُرتكب من الجرائم المنصوص عليها في المادة (العاشرة) من النظام، وما يُرتكب من مخالفات لأحكام النظام ولائحته والقرارات الصادرة تنفيذاً لهما".'),
('boe26-fb1ab9e95d452f464512a8cd','cmpzcv47a09jdvtrkun9utom0','على كل مؤسسة صحية خاصة تحديد أسعار الخدمات التي تقدمها، ومن ثم تعتمدها الوزارة بعد مراجعتها والتأكد من مناسبتها وفقاً للمعايير التي تضعها، ولا يجوز تعديل هذه الأسعار إلا بعد موافقة الوزارة، وتلتزم المؤسسة بما يأتي:

1 ـ  أسعار الخدمات الصحية المعتمدة.

2 - وضع الأسعار في مكان بارز وبخط واضح.

3 - تقديم تقرير تقريبي للمراجع عن تكلفة العلاج قبل بدئه والخدمات التي ستقدم له.

4 - تقديم بيان تفصيلي نهائي للمراجع عن نوع العلاج والخدمات التي قدمت له وتكلفة كل منها','2014-09-26'::timestamptz,'مرسوم ملكي رقم م/78 وتاريخ 2/12/1435هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/64e307c5-ac8c-49d8-9174-a9a700f285a0/1','تم تعديل المادة (السابعة) بموجب المرسوم الملكي رقم ( م/78 ) وتاريخ 2 / 12 / 1435 هـ، لتصبح بالنص الآتي:

"على كل مؤسسة صحية خاصة تحديد أسعار الخدمات التي تقدمها، ومن ثم تعتمدها الوزارة بعد مراجعتها والتأكد من مناسبتها وفقاً للمعايير التي تضعها، ولا يجوز تعديل هذه الأسعار إلا بعد موافقة الوزارة، وتلتزم المؤسسة بما يأتي:

1 ـ  أسعار الخدمات الصحية المعتمدة.

2 - وضع الأسعار في مكان بارز وبخط واضح.

3 - تقديم تقرير تقريبي للمراجع عن تكلفة العلاج قبل بدئه والخدمات التي ستقدم له.

4 - تقديم بيان تفصي'),
('boe26-740609f8e1136ddf62702fa0','cmpzcvduf0c7mvtrklyjh7tbx','مع عدم الإخلال بأي عقوبة أشد ينص عليها نظام آخر، يعاقب كل من يرتكب أياً من الأعمال المنصوص عليها في المادة (الثالثة والعشرين) من هذا النظام بغرامة لا تزيد على (خمسة ملايين ريال) أو بالسجن مدة لا تزيد على (خمس سنوات) أو بهما معاً، ويجوز الحكم بمصادرة الأجهزة والمنظومات والبرامج المستخدمة في ارتكاب المخالفة.

وللمحكمة المختصة أن تضمن حكمها النص على نشر ملخصه على نفقة المحكوم عليه في صحيفة محلية تصدر في مكان إقامته، أو في أقرب منطقة له إن لم يكن في مكان إقامته صحيفة محلية، أو بالطريقة التي تراها المحكمة مناسبة، وذلك بحسب نوع الجريمة المرتكبة، وجسامتها، وتأثيرها، على أن يكون النشر بعد اكتساب الحكم الصفة النهائية','2015-05-19'::timestamptz,'مرسوم ملكي رقم م/57 وتاريخ 1/8/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/6f509360-2c39-4358-ae2a-a9a700f2ed16/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/57) بتاريخ 1 / 8 / 1436هـ، لتصبح بالنص الآتي:

" مع عدم الإخلال بأي عقوبة أشد ينص عليها نظام آخر، يعاقب كل من يرتكب أياً من الأعمال المنصوص عليها في المادة (الثالثة والعشرين) من هذا النظام بغرامة لا تزيد على (خمسة ملايين ريال) أو بالسجن مدة لا تزيد على (خمس سنوات) أو بهما معاً، ويجوز الحكم بمصادرة الأجهزة والمنظومات والبرامج المستخدمة في ارتكاب المخالفة.

وللمحكمة المختصة أن تضمن حكمها النص على نشر ملخصه على نفقة المحكوم عليه في صحيفة محلية تصدر في'),
('boe26-0801738a0a25de2ab622d090','cmpz6mupm0ak7cwg2jll9vhw3','يعاقب بالسجن مدة لا تزيد على سنتين وبغرامة لا تتجاوز مائة ألف ريال، أو بإحدى هاتين العقوبتين؛ كل من تعمد إتلاف أي من تمديدات أو منشآت المرافق العامة، أو تعمد قطعها أو تعطيلها، سواء كان الفاعل أصلياً أو شريكاً، ويجوز تضمين قرار أو حكم العقوبة النص على نشر منطوقه على نفقة المخالف في صحيفة محلية تصدر في مكان إقامته، فإن لم يكن في مكان إقامته صحيفة ففي أقرب منطقة له، أو نشره في أي وسيلة أخرى مناسبة، وذلك بحسب نوع المخالفة المرتكبة وجسامتها وآثارها، على أن يكون النشر بعد تحصن القرار بمضي المدة المحددة نظاماً أو تأييده من المحكمة المختصة، أو باكتساب الحكم الصفة النهائية','2017-01-17'::timestamptz,'مرسوم ملكي رقم م/38 وتاريخ 19/4/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/70405759-cf34-4260-a81e-a9a700f21241/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/38) بتاريخ 19/ 4/ 1438هـ، لتصبح بالنص الآتي:

"يعاقب بالسجن مدة لا تزيد على سنتين وبغرامة لا تتجاوز مائة ألف ريال، أو بإحدى هاتين العقوبتين؛ كل من تعمد إتلاف أي من تمديدات أو منشآت المرافق العامة، أو تعمد قطعها أو تعطيلها، سواء كان الفاعل أصلياً أو شريكاً، ويجوز تضمين قرار أو حكم العقوبة النص على نشر منطوقه على نفقة المخالف في صحيفة محلية تصدر في مكان إقامته، فإن لم يكن في مكان إقامته صحيفة ففي أقرب منطقة له، أو نشره في أي وسيلة أخرى مناسبة، وذلك ب'),
('boe26-28e3a575be1c61c93b9999f4','cmpz5wh0201k7cwg20qsmi4qx','يحكم على من تثبت إدانته في جريمة الرشوة بمصادرة المال أو الميزة أو الفائدة محل الجريمة متى كان ذلك ممكناً، أو مصادرة قيمته بحسب الأحوال، ومصادرة أي عائدات ترتبت من ذلك المال أو الميزة أو الفائدة','2021-12-02'::timestamptz,'مرسوم ملكي رقم م/38 وتاريخ 1443/4/27هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/75e963c8-9ff3-4d10-88a4-a9a700f17f21/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/38) وتاريخ 1443/4/27هـ. لتكون بالنص الآتي: "يحكم على من تثبت إدانته في جريمة الرشوة بمصادرة المال أو الميزة أو الفائدة محل الجريمة متى كان ذلك ممكناً، أو مصادرة قيمته بحسب الأحوال، ومصادرة أي عائدات ترتبت من ذلك المال أو الميزة أو الفائدة".'),
('boe26-c5ece67f1ea8822b22d2eadb','cmpzcv7li0ahkvtrkptwt1grl','يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية','2021-03-23'::timestamptz,'قرار مجلس الوزراء رقم 445 وتاريخ 1442/8/10هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/796a6587-8da2-4583-8603-ac4500d5b8bc/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (445) وتاريخ 1442/8/10هـ، لتصبح بالنص الآتي: "يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية".'),
('boe26-9ca7efb37a56a38161b650fe','cmpz5y1ty023tcwg22fsjonr5','عند تعديل القيود أو تسجيل الحالات والواقعات المدنية، تُسجّل الخصائص الحيوية لمن بلغ سن (السادسة) من السعوديين. وتحدد اللائحة التنفيذية الضوابط اللازمة لما ورد في هذه المادة','2024-04-01'::timestamptz,'مرسوم ملكي رقم م/198 وتاريخ 1445/9/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/198) وتاريخ 1445/9/22هـ، لتكون بالنص الآتي: 

"عند تعديل القيود أو تسجيل الحالات والواقعات المدنية، تُسجّل الخصائص الحيوية لمن بلغ سن (السادسة) من السعوديين. وتحدد اللائحة التنفيذية الضوابط اللازمة لما ورد في هذه المادة".'),
('boe26-984a9299c425047e0e601fae','cmpz5y2ao023zcwg2t5bdocz1','إذا رفض كاتب السجل المنوط به القيد – قيد أية واقعة مدنية - وجب عليه خلال سبعة أيام رفع الأمر إلى الإدارة التي يتبعها بمذكرة مسببة. وعلى مدير الإدارة أن يبدي رأيه بقرار مكتوب يعلم فيه كلا من كاتب السجل وصاحب الشأن خلال ثلاثين يوما من تاريخ رفع الأمر إليه، وفي حالة رفض القيد أو مضي المدة المذكورة يكون لصاحب الشأن الحق في التظلم إلى   اللجنة  الفرعية.','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 /1422 هـ ،لتكون بالنص التالى:

إذا رفض كاتب السجل المنوط به القيد – قيد أية واقعة مدنية - وجب عليه خلال سبعة أيام رفع الأمر إلى الإدارة التي يتبعها بمذكرة مسببة. وعلى مدير الإدارة أن يبدي رأيه بقرار مكتوب يعلم فيه كلا من كاتب السجل وصاحب الشأن خلال ثلاثين يوما من تاريخ رفع الأمر إليه، وفي حالة رفض القيد أو مضي المدة المذكورة يكون لصاحب الشأن الحق في التظلم إلى   اللجنة  الفرعية.'),
('boe26-7f02e20d9c023e39408bd033','cmpz5y2g80241cwg2zs9igcof','عند التبليغ عن واقعة مدنية بعد فوات المدة المحددة وقبل نهاية السنة الأولى لحدوثها، فعلى كاتب السجل أن يتثبت من صحة وقوعها في التاريخ المبلغ عنه، وله في هذا السبيل طلب الإثباتات وإجراء التحقيق اللازم، وعليه بعد ثبوت   الواقعة     تقييدها في السجل الخاص بها. أما في الواقعات التي يبلغ عنها بعد انتهاء سنة من تاريخ حدوثها، فلا يجوز قيدها إلا بقرار من   اللجنة     المحلية.','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422 هـ ،لتكون بالنص التالى:

عند التبليغ عن واقعة مدنية بعد فوات المدة المحددة وقبل نهاية السنة الأولى لحدوثها، فعلى كاتب السجل أن يتثبت من صحة وقوعها في التاريخ المبلغ عنه، وله في هذا السبيل طلب الإثباتات وإجراء التحقيق اللازم، وعليه بعد ثبوت   الواقعة     تقييدها في السجل الخاص بها. أما في الواقعات التي يبلغ عنها بعد انتهاء سنة من تاريخ حدوثها، فلا يجوز قيدها إلا بقرار من   اللجنة     المحلية.'),
('boe26-7eb587eb45a83b2cebdf1aaa','cmpz5y2rd0245cwg2fs5tla84','لا يجوز لكاتب السجل المنوط به القيد أن يسجل أية واقعة يكون هو فيها مبلغا أو طالب قيد أو شاهد، أو تكون متعلقة به أو بزوجه أو أحد أصوله أو فروعه أو أقاربه إلى الدرجة الرابعة، إلا بعد أن يرفع الأمر إلى مدير الإدارة التابع له الذي يقوم بدراسة الأوراق والتأكد من سلامتها ثم يأمر بإجراء القيد اللازم.','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 /1422 هـ ،لتكون بالنص التالى:

لا يجوز لكاتب السجل المنوط به القيد أن يسجل أية واقعة يكون هو فيها مبلغا أو طالب قيد أو شاهد، أو تكون متعلقة به أو بزوجه أو أحد أصوله أو فروعه أو أقاربه إلى الدرجة الرابعة، إلا بعد أن يرفع الأمر إلى مدير الإدارة التابع له الذي يقوم بدراسة الأوراق والتأكد من سلامتها ثم يأمر بإجراء القيد اللازم.'),
('boe26-b49f23a942a0cb1b8b4ebc1c','cmpz5y382024bcwg2wbnfgrfm','يهيأ في كل إدارة من إدارات الأحوال المدنية، في كل مكتب من مكاتبها - خزائن خاصة - تحفظ فيها سجلات وأوراق الواقعات، أما معاملات الأحوال المدنية المبنية على هذه الواقعات والمتعلقة بالإضافة إلى السجل المدني أو التعديل فيه أو الحذف منه، فتحفظ في ملف أساس صاحب الشأن بعد إكمال اللازم، ليمكن الرجوع إليها. وتحدد اللائحة التنفيذية طرق وأساليب الحفظ في خزائن المحفوظات وكيفية عمل فهارس واضحة للمحفوظات، بحيث يمكن الرجوع إليها بيسر عند الحاجة','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 /1422 هـ ،لتكون بالنص التالى:

يهيأ في كل إدارة من إدارات الأحوال المدنية، في كل مكتب من مكاتبها - خزائن خاصة - تحفظ فيها سجلات وأوراق الواقعات، أما معاملات الأحوال المدنية المبنية على هذه الواقعات والمتعلقة بالإضافة إلى السجل المدني أو التعديل فيه أو الحذف منه، فتحفظ في ملف أساس صاحب الشأن بعد إكمال اللازم، ليمكن الرجوع إليها. وتحدد اللائحة التنفيذية طرق وأساليب الحفظ في خزائن المحفوظات وكيفية عمل فهارس واضحة للمحفوظات، بحيث يمكن الرج'),
('boe26-9ab381009c540fa49e800504','cmpz5y3dm024dcwg20dhu824z','تفحص السجلات عند إيداعها للحفظ في خزائن المحفوظات من قبل   اللجنة     المحلية وعليها أن توقع في نهاية القيود من كل سجل بما يفيد فحصها، وأن تحرر محضرا بنتيجة الفحص تبين فيه حالة هذه السجلات، وما قد يكون فيها من مخالفات تسجيلية، ورفع هذا المحضر إلى   الهيئة  خلال خمسة عشرة يوما من تاريخ إجراء الفحص.','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422هـ ،لتكون بالنص التالى:

تفحص السجلات عند إيداعها للحفظ في خزائن المحفوظات من قبل   اللجنة     المحلية وعليها أن توقع في نهاية القيود من كل سجل بما يفيد فحصها، وأن تحرر محضرا بنتيجة الفحص تبين فيه حالة هذه السجلات، وما قد يكون فيها من مخالفات تسجيلية، ورفع هذا المحضر إلى   الهيئة  خلال خمسة عشرة يوما من تاريخ إجراء الفحص.'),
('boe26-f946b0ee6e15591b4d58fde8','cmpz5y4rq024tcwg2019o9ntt','يكون التبليغ عن المواليد لدى مكتب من مكاتب الأحوال المدنية على النموذج المعد لذلك خلال خمسة عشر يوما من تاريخ الولادة. وتكون هذه المهلة ثلاثين يوما إذا حدثت الولادة في مكان يبعد عن أقرب إدارة أو مكتب للأحوال المدنية أكثر من خمسين كيلا.','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422 هـ ،لتكون بالنص التالى:

يكون التبليغ عن المواليد لدى مكتب من مكاتب الأحوال المدنية على النموذج المعد لذلك خلال خمسة عشر يوما من تاريخ الولادة. وتكون هذه المهلة ثلاثين يوما إذا حدثت الولادة في مكان يبعد عن أقرب إدارة أو مكتب للأحوال المدنية أكثر من خمسين كيلا.'),
('boe26-673afaf14a412ba9f7be53df','cmpz5y5e00251cwg2wjh0jege','إذا توفي مولود قبل قيده في السجل، وجب تسجيل ولادته ثم تسجيل وفاته. أما إذا ولد ميتا بعد الشهر السادس من الحمل فيقيد في سجل الوفيات بأنه ولد ميتا.','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 /1422 هـ ،لتكون بالنص التالى:

إذا توفي مولود قبل قيده في السجل، وجب تسجيل ولادته ثم تسجيل وفاته. أما إذا ولد ميتا بعد الشهر السادس من الحمل فيقيد في سجل الوفيات بأنه ولد ميتا.'),
('boe26-9641812f82d62f1b6db99662','cmpz5y5pa0255cwg2wne5pluk','يجب على المؤسسة أو الشخص الذي عهد إليه برعاية الطفل اللقيط تبليغ   مكتب الأحوال المدنية     المختص بذلك خلال خمسة عشر يوما من تاريخ تسلمه اللقيط. وعلى كاتب السجل قيده في السجل كالمتبع، وتسلم شهادة ميلاد الطفل إلى المؤسسة أو الشخص الذي تكفل بتربيته ورعايته دون أن يذكر فيه أنه لقيط. وفي حالة معرفة أحد الوالدين أو كليهما يتم تصحيح قيد الطفل بقرار من   اللجنة     الفرعية.','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 /1422 هـ ،لتكون بالنص التالى:

يجب على المؤسسة أو الشخص الذي عهد إليه برعاية الطفل اللقيط تبليغ   مكتب الأحوال المدنية     المختص بذلك خلال خمسة عشر يوما من تاريخ تسلمه اللقيط. وعلى كاتب السجل قيده في السجل كالمتبع، وتسلم شهادة ميلاد الطفل إلى المؤسسة أو الشخص الذي تكفل بتربيته ورعايته دون أن يذكر فيه أنه لقيط. وفي حالة معرفة أحد الوالدين أو كليهما يتم تصحيح قيد الطفل بقرار من   اللجنة     الفرعية.'),
('boe26-693a953f8b6dfea2ebd556ea','cmpz5y9vm026ncwg2s6u40wcm','يجب على من أكمل سن الخامسة عشرة من المواطنين السعوديين أن يحصل على بطاقة شخصية هوية وطنية خاصة به، ويكون ذلك اختياريًا لمن هم بين سن العاشرة والخامسة عشرة بعد موافقة ولي أمره، وتستخرج البطاقة من واقع قيود السجل المدني المركزي.','2013-04-02'::timestamptz,'مرسوم ملكي رقم م/28 وتاريخ 21/5/1434هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/28) وتاريخ 21 / 5 /1434 هـ ،لتكون بالنص الآتى:

يجب على من أكمل سن الخامسة عشرة من المواطنين السعوديين أن يحصل على بطاقة شخصية هوية وطنية خاصة به، ويكون ذلك اختياريًا لمن هم بين سن العاشرة والخامسة عشرة بعد موافقة ولي أمره، وتستخرج البطاقة من واقع قيود السجل المدني المركزي.'),
('boe26-65bf4c6a4e0dc0bf64d93257','cmpz5y9vm026ncwg2s6u40wcm','يجب أن يحصل من أكمل سن (الخامسة عشرة) من السعوديين على بطاقة شخصية خاصة به، ويقوم وليه أو وصيه أو وكيل أي منهما بالإجراءات المطلوبة لذلك، ويكون ذلك اختيارياً لمن هم بين سن (السادسة) و(الخامسة عشرة)، وتستخرج البطاقة من واقع قيود السجل المدني المركزي.

وتحدد اللائحة التنفيذية الضوابط اللازمة لما ورد في هذه المادة','2024-04-01'::timestamptz,'مرسوم ملكي رقم م/198 وتاريخ 1445/9/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/198) وتاريخ 1445/9/22هـ ، لتكون بالنص الآتي: 

" يجب أن يحصل من أكمل سن (الخامسة عشرة) من السعوديين على بطاقة شخصية خاصة به، ويقوم وليه أو وصيه أو وكيل أي منهما بالإجراءات المطلوبة لذلك، ويكون ذلك اختيارياً لمن هم بين سن (السادسة) و(الخامسة عشرة)، وتستخرج البطاقة من واقع قيود السجل المدني المركزي.

وتحدد اللائحة التنفيذية الضوابط اللازمة لما ورد في هذه المادة".'),
('boe26-64058e0eeae77f51a65de33f','cmpz5yayk0271cwg2734acf8h','1 -  يعطى دفتر العائلة لمدة غير محددة، وإذا توفي صاحبه يسحب ويصرف بدلا منه دفتر عائلة آخر باسم المتوفى لكل من يرغب من ورثته المضافين فيه، على أن يؤثر مكان الصورة بما يفيد أنه متوفى.
2 – تحدد اللائحة التنفيذية مدة صلاحية البطاقة الشخصية من تاريخ صدورها، أو استبدالها، أو تجديدها. ويجب تجديدها خلال مائة وثمانين يوما سابقة لانقضاء مدة صلاحيتها.','2005-04-13'::timestamptz,'مرسوم ملكي رقم م/11 وتاريخ 4/3/1426هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة أكثر من مرة ، كان آخرها بموجب المرسوم الملكي رقم (م/11) وتاريخ 4 / 3 / 1426 هـ ، لتكون بالنص الآتى:

"1 -  يعطى دفتر العائلة لمدة غير محددة، وإذا توفي صاحبه يسحب ويصرف بدلا منه دفتر عائلة آخر باسم المتوفى لكل من يرغب من ورثته المضافين فيه، على أن يؤثر مكان الصورة بما يفيد أنه متوفى.
2 – تحدد اللائحة التنفيذية مدة صلاحية البطاقة الشخصية من تاريخ صدورها، أو استبدالها، أو تجديدها. ويجب تجديدها خلال مائة وثمانين يوما سابقة لانقضاء مدة صلاحيتها."'),
('boe26-52e5c23810c2d5e846372db6','cmpz5yc75027hcwg2v73ye7zc','أ - تشكل بقرار من   وزير الداخلية وبقدر الحاجة لجان محلية في كل إدارة أو مكتب للأحوال المدنية، وتتكون كل لجنة من:

1 - مندوب من   إدارة الأحوال المدنية     يعينه   وزير الداخلية    أو من ينيبه.
2 - مندوب من وزارة العدل يعينه وزير العدل أو من ينيبه.
3 - مندوب من وزارة الصحة يعينه وزير الصحة أو من ينيبه.

ب - تشكل بقرار من   وزير الداخلية  وبقدر الحاجة لجان فرعية في المناطق، وتتكون كل لجنة من:

1 - مستشار يعينه وزير الداخلية.
2  -  مندوب يعينه وزير العدل.
3 - مندوب يعينه وزير الصحة.','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422هـ ، لتكون بالنص الآتى:

" أ - تشكل بقرار من   وزير الداخلية وبقدر الحاجة لجان محلية في كل إدارة أو مكتب للأحوال المدنية، وتتكون كل لجنة من:

1 - مندوب من   إدارة الأحوال المدنية     يعينه   وزير الداخلية    أو من ينيبه.
2 - مندوب من وزارة العدل يعينه وزير العدل أو من ينيبه.
3 - مندوب من وزارة الصحة يعينه وزير الصحة أو من ينيبه.

ب - تشكل بقرار من   وزير الداخلية  وبقدر الحاجة لجان فرعية في المناطق، وتتكون كل لجنة من:

1 - مستشار'),
('boe26-39776b3fe51d18209d5b0fb6','cmpz5yccq027jcwg2f3dmype7','تقوم اللجان المحلية بتطبيق الاختصاص المحدد لها في المادتين (20 ،26) من هذا النظام، وتختص اللجان الفرعية بالفصل في الموضوعات التالية:

أ - طلبات تصحيح أو تعديل قيود الأحوال المدنية، وتظلمات رفض القيد. على أنه فيما يتعلق بتعديل تاريخ الميلاد فيستمر العمل بالقرارات والتعليمات المطبقة حاليا حتى يتم وضع القواعد الخاصة بذلك بقرار من   مجلس الوزراء.
ب - التحقيق مع مخالفي أحكام هذا النظام ولوائحه وتوقيع العقوبات والجزاءات المقررة عليهم.
جـ - الموضوعات الأخرى التي تحال إليها من   إدارة الأحوال المدنية .','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422 هـ ، لتكون بالنص التالى:

تقوم اللجان المحلية بتطبيق الاختصاص المحدد لها في المادتين (20 ،26) من هذا النظام، وتختص اللجان الفرعية بالفصل في الموضوعات التالية:

أ - طلبات تصحيح أو تعديل قيود الأحوال المدنية، وتظلمات رفض القيد. على أنه فيما يتعلق بتعديل تاريخ الميلاد فيستمر العمل بالقرارات والتعليمات المطبقة حاليا حتى يتم وضع القواعد الخاصة بذلك بقرار من   مجلس الوزراء.
ب - التحقيق مع مخالفي أحكام هذا النظام ولوائحه وتوقيع العقوبا'),
('boe26-1581f58675039175a368e61e','cmpz5ycnv027ncwg2k9jljyv3','استثناء مما نصت عليه المادة (84) يجوز للمحكوم عليهم التظلم من قرارات اللجان الفرعية الصادرة ضدهم بالغرامة أو السجن أو بهما معا، أمام ديوان المظالم خلال ستين يوما من تاريخ إبلاغهم بالقرار.','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بالمرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422 هـ ، لتكون بالنص الآتى:

استثناء مما نصت عليه المادة (84) يجوز للمحكوم عليهم التظلم من قرارات اللجان الفرعية الصادرة ضدهم بالغرامة أو السجن أو بهما معا، أمام ديوان المظالم خلال ستين يوما من تاريخ إبلاغهم بالقرار.'),
('boe26-ebb797c8cc85cc1534969fc4','cmpz5ycz0027rcwg2cs2e8c2j','تختص   هيئة الأحوال المدنية المركزية    بالنظر والفصل في الموضوعات التالية:

أ - الفصل في الطعون الموجهة ضد قرارات اللجان الفرعية والمحلية.
ب - التصديق على محاضر فحص السجلات.
جـ - إبداء الرأي في كل ما يحيله إليها   وزير الداخلية    من مسائل تتعلق بالأحوال المدنية.','2001-08-20'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1/6/1422هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عدلت هذه المادة بالمرسوم الملكي رقم (م/25) وتاريخ 1 / 6 / 1422 هـ ، لتكون بالنص الآتى:

تختص   هيئة الأحوال المدنية المركزية    بالنظر والفصل في الموضوعات التالية:

أ - الفصل في الطعون الموجهة ضد قرارات اللجان الفرعية والمحلية.
ب - التصديق على محاضر فحص السجلات.
جـ - إبداء الرأي في كل ما يحيله إليها   وزير الداخلية    من مسائل تتعلق بالأحوال المدنية.'),
('boe26-7fcf8fb9283cf1615a8fe6d6','cmpz5ydl9027zcwg2pweupm89','يعد رب الأسرة في مجال تطبيق هذا النظام هو الأب أو الأم بالنسبة إلى  الأولاد القصّر','2019-07-30'::timestamptz,'مرسوم ملكي رقم م/134 وتاريخ 27/11/1440هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/7e2b99b1-0e84-4dd1-90c7-a9a700f18cdf/1','عُدلت هذه المادة بموجب المرسوم الملكي رقم (م / 134) وتاريخ 27 / 11 /1440هـ، لتكون بالنص الآتي: "يعد رب الأسرة في مجال تطبيق هذا النظام هو الأب أو الأم بالنسبة إلى  الأولاد القصّر".'),
('boe26-b273452f1e67c78ef60eab4a','cmpz6lfl90a2hcwg20yckrpen','يصدر وزير الحج بالاتفاق مع وزير الداخلية ووزير الخارجية - وبالتنسيق مع الهيئة العامة للسياحة والآثار - التعديلات اللازمة على اللائحة التنفيذية لهذا التنظيم بما فيها القواعد المنظمة لتنقل المعتمرين داخل المملكة, وذلك خلال مدة لا تتجاوز ستة أشهر','2014-09-15'::timestamptz,'قرار مجلس الوزراء رقم 439 وتاريخ 20/11/1435هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/812ac6e0-430d-4c9d-b6cb-a9a700f2080c/1','تم بموجب قرار مجلس الوزراء رقم (439) وتاريخ 20 / 11 /1435هـ 	تعديل المادة (الثالثة عشرة)  لتكون بالنص الآتي:

"يصدر وزير الحج بالاتفاق مع وزير الداخلية ووزير الخارجية - وبالتنسيق مع الهيئة العامة للسياحة والآثار - التعديلات اللازمة على اللائحة التنفيذية لهذا التنظيم بما فيها القواعد المنظمة لتنقل المعتمرين داخل المملكة, وذلك خلال مدة لا تتجاوز ستة أشهر".'),
('boe26-eba85d60de7e78ad52c13747','cmpzcuy3y07wdvtrk7v4tq7c7','يكون للهيئة رئيس يعين بأمر ملكي بمرتبة وزير، ونائب ومساعد يعينان بأمر ملكي بالمرتبة الممتازة','2023-03-28'::timestamptz,'قرار مجلس الوزراء رقم 620 وتاريخ 1444/9/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/836460dd-2750-40a8-b8b1-a9a700f26ede/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (620) وتاريخ 1444/9/6هـ، لتكون بالنص الآتي:

" يكون للهيئة رئيس يعين بأمر ملكي بمرتبة وزير، ونائب ومساعد يعينان بأمر ملكي بالمرتبة الممتازة".'),
('boe26-e77a52a8ec434893d65d0e34','cmpzcuysb07wkvtrki1nco20d','يتولى نائب رئيس الهيئة ومساعد الرئيس معاونة الرئيس في حضوره، وفقاً لما يحدده الرئيس من صلاحيات لهما، ويتولى نائب الرئيس عمل الرئيس عند غيابه','2023-03-28'::timestamptz,'قرار مجلس الوزراء رقم 620 وتاريخ 1444/9/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/836460dd-2750-40a8-b8b1-a9a700f26ede/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (620) وتاريخ 1444/9/6هـ، لتكون بالنص الآتي:

" يتولى نائب رئيس الهيئة ومساعد الرئيس معاونة الرئيس في حضوره، وفقاً لما يحدده الرئيس من صلاحيات لهما، ويتولى نائب الرئيس عمل الرئيس عند غيابه".'),
('boe26-52efba84510670fab506db53','cmpzcv8z00awsvtrk4rrz2pdf','1- مع مراعاة الأحكام الواردة في نظام الإجراءات الجزائية، تتابع الوزارة قضايا الإيذاء التي تحيلها إلى جهة الضبط وفقاً لما ورد في المادة (الحادية عشرة) من النظام، وعلى جهة الضبط إحاطة الوزارة بما انتهت إليه من إجراءت حيال كل قضية على حدة. وفي حال كان من تعرض للإيذاء من الأشخاص ذوق الإعاقة، فتستمر في متابعة القضية إلى حين الفصل فيها قضاءً.

2- تتولى الوزارة -عند الحاجة- متابعة حالات الإيذاء بعد الفصل فيها قضاءً لمدة لا تقل عن (6) أشهر','2022-03-09'::timestamptz,'مرسوم ملكي رقم م/72 وتاريخ 1443/8/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/83f450eb-7985-461f-b053-a9a700f2ba08/1','- صدر تعديل على هذه المادة وذلك بموجب المرسوم الملكي رقم (م/72) وتاريخ 1443/8/6هـ، لتكون بالنص الآتي:

"1- مع مراعاة الأحكام الواردة في نظام الإجراءات الجزائية، تتابع الوزارة قضايا الإيذاء التي تحيلها إلى جهة الضبط وفقاً لما ورد في المادة (الحادية عشرة) من النظام، وعلى جهة الضبط إحاطة الوزارة بما انتهت إليه من إجراءت حيال كل قضية على حدة. وفي حال كان من تعرض للإيذاء من الأشخاص ذوق الإعاقة، فتستمر في متابعة القضية إلى حين الفصل فيها قضاءً.

2- تتولى الوزارة -عند الحاجة- متابعة حالات الإيذاء بعد ا'),
('boe26-73d3de50633e41e23833295d','cmpz5x82z01tfcwg2nh2a4fky','أ- يجب أن تحمل كل دراجة آلية لوحة واحدة، واضحة، ومقروءة، تثبت على مؤخرتها، ولا يجوز السير دونها.

ب- يجب أن تحمل كل مقطورة أو نصف مقطورة رقم لوحة المركبة القاطرة إذا كان حجمها يحجب رؤية تلك اللوحة، وأن تحمل كل مقطورة أو نصف مقطورة لوحة خاصة بها بحسب ما تحدده اللائحة.

ج- دون إخلال بالأحكام ذات الصلة بالمقطورة ونصف المقطورة الواردة في النظام، تحدد اللائحة الأحكام التي تخضع لها المقطورة ونصف المقطورة من بين أحكام النظام ذات الصلة بالمركبة، وذلك بما يتفق مع طبيعة المقطورة ونصف المقطورة','2024-04-07'::timestamptz,'مرسوم ملكي رقم م/207 وتاريخ 1445/9/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/85364e57-c01e-41ba-8def-a9a700f183e9/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/207) وتاريخ 1445/9/28هـ ، لتكون بالنص الآتي:

"أ- يجب أن تحمل كل دراجة آلية لوحة واحدة، واضحة، ومقروءة، تثبت على مؤخرتها، ولا يجوز السير دونها.

ب- يجب أن تحمل كل مقطورة أو نصف مقطورة رقم لوحة المركبة القاطرة إذا كان حجمها يحجب رؤية تلك اللوحة، وأن تحمل كل مقطورة أو نصف مقطورة لوحة خاصة بها بحسب ما تحدده اللائحة.

ج- دون إخلال بالأحكام ذات الصلة بالمقطورة ونصف المقطورة الواردة في النظام، تحدد اللائحة الأحكام التي تخضع لها المقطورة ونصف المقطورة'),
('boe26-3b202eb133974662d48f6e0b','cmpz805dr0cbp7b6w8t5wsxaz','مع مراعاة أحكام الحالات المختلفة المنصوص عليها في هذا النظام، يسوى المعاش عن مدة الخدمة بواقع جزء من أربعين جزءًا من المرتب الشهري الأخير وذلك عن كل سنة من سنوات الخدمة المحسوبة في التقاعد، على ألا تتجاوز أربعين سنة .','1976-10-14'::timestamptz,'مرسوم ملكي رقم م/75 وتاريخ 21/10/1396هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/859d4e56-627b-4766-a7aa-a9a700f23975/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/75) وتاريخ 21 /10 /1396 هـ ، لتكون كما يلى :

مع مراعاة أحكام الحالات المختلفة المنصوص عليها في هذا النظام، يسوى المعاش عن مدة الخدمة بواقع جزء من أربعين جزءًا من المرتب الشهري الأخير وذلك عن كل سنة من سنوات الخدمة المحسوبة في التقاعد، على ألا تتجاوز أربعين سنة .'),
('boe26-fbec9df37f59ab11f6d0b34e','cmpz806p20cc57b6wknehqxv3','المستحقون عن صاحب المعاش هم: الزوج أو الزوجة، والأم والأب، والابن والبنت، وابن وبنت الابن الذي توفي في حياة صاحب المعاش، والأخ والأخت، والجد والجدة. وفيما عدا الزوجة والابن والبنت، فيشترط لاستحقاق الشخص أن يكون معتمداً في إعالته على صاحب المعاش عند وفاته. ويحدد مجلس إدارة المؤسسة العامة للتقاعد بقرار منه متى يعتبر الشخص معتمداً في إعالته على صاحب المعاش، وتاريخ بدء صرف الاستحقاق، وإجراءات إثبات ذلك','2021-06-03'::timestamptz,'مرسوم ملكي رقم م/93 وتاريخ 1442/10/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/859d4e56-627b-4766-a7aa-a9a700f23975/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/93) وتاريخ 1442/10/22هـ ، لتكون بالنص الآتي: "المستحقون عن صاحب المعاش هم: الزوج أو الزوجة، والأم والأب، والابن والبنت، وابن وبنت الابن الذي توفي في حياة صاحب المعاش، والأخ والأخت، والجد والجدة. وفيما عدا الزوجة والابن والبنت، فيشترط لاستحقاق الشخص أن يكون معتمداً في إعالته على صاحب المعاش عند وفاته. ويحدد مجلس إدارة المؤسسة العامة للتقاعد بقرار منه متى يعتبر الشخص معتمداً في إعالته على صاحب المعاش، وتاريخ بدء صرف الاستحقاق، وإجراءات إثبات ذلك"'),
('boe26-055e7d1e7072cf0d7100c41b','cmpz808lg0ccv7b6wkxdup063','إذا لم يعد الموظف متمتعاً بالجنسية العربية السعودية، يُمنح مكافأة تحسب وفق أحكام المادة (الثالثة والعشرين) من هذا النظام','2022-03-23'::timestamptz,'مرسوم ملكي رقم م/80 وتاريخ 1443/8/20هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/859d4e56-627b-4766-a7aa-a9a700f23975/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/80) وتاريخ 1443/8/20هـ، لتكون بالنص الآتي: "إذا لم يعد الموظف متمتعاً بالجنسية العربية السعودية، يُمنح مكافأة تحسب وفق أحكام المادة (الثالثة والعشرين) من هذا النظام".'),
('boe26-19ec982a8b5d174b37c0e758','cmpz6fuy0081pcwg2m1hnhqbb','تتولى المحكمة المختصة الفصل في جميع المخالفات والمنازعات ودعاوى المطالبة بالتعويض الناشئة من تطبيق أحكام هذا النظام','2018-09-19'::timestamptz,'مرسوم ملكي رقم م/10 وتاريخ 1440/1/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/85eb2897-bec6-4c0c-b1d7-ac7c008ec09c/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/10) وتاريخ 1440/1/9هـ، لتصبح بالنص الآتي:

" المادة (الثالثة عشرة): تتولى المحكمة المختصة الفصل في جميع المخالفات والمنازعات ودعاوى المطالبة بالتعويض الناشئة من تطبيق أحكام هذا النظام".'),
('boe26-85971e25961633737ec13f5f','cmpz6fwfy0829cwg29ocd9bbg','1- للنيابة العامة أن تطلب منع سفر من يثبت التحقيق ارتكابه مخالفة لأحكام النظام إلى أن يصدر الحكم النهائي في القضية.

2- لوزارة الداخلية، إذا صدر حكم نهائي بإدانة غير السعودي بارتكابه أياً من المخالفات المنصوص عليها في المادة (الثانية) من النظام، إبعاده من المملكة ومنعه من دخولها، وذلك وفقاً لضوابط تضعها وزارة الداخلية والوزارة ووزارة الاستثمار','2021-08-05'::timestamptz,'مرسوم ملكي رقم م/109 وتاريخ 1442/12/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/85eb2897-bec6-4c0c-b1d7-ac7c008ec09c/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/109) وتاريخ 1442/12/26هـ، لتكون بالنص الآتي:

" 1- للنيابة العامة أن تطلب منع سفر من يثبت التحقيق ارتكابه مخالفة لأحكام النظام إلى أن يصدر الحكم النهائي في القضية.

2- لوزارة الداخلية، إذا صدر حكم نهائي بإدانة غير السعودي بارتكابه أياً من المخالفات المنصوص عليها في المادة (الثانية) من النظام، إبعاده من المملكة ومنعه من دخولها، وذلك وفقاً لضوابط تضعها وزارة الداخلية والوزارة ووزارة الاستثمار".'),
('boe26-7375fd977fc609dffdadd0be','cmpz6fwqr082dcwg2rauql2x0','تضمَّن المحكمة المختصة حكمها - الصادر بعقوبة السجن في إحدى المخالفات المنصوص عليها في المواد السابقة - النص على نشر ملخصه على نفقة المخالف، وللمحكمة المختصة النشر فيما عدا عقوبة السجن، وتحدد المحكمة طريقة النشر إما في إحدى الصحف المحلية أو في أي وسيلة أخرى مناسبة، وذلك بحسب نوع المخالفة المرتكبة وجسامتها وتأثيرها، على أن يكون النش بعد اكتساب الحكم الصفة النهائية','2018-07-11'::timestamptz,'مرسوم ملكي رقم م/108 وتاريخ 1439/10/27هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/85eb2897-bec6-4c0c-b1d7-ac7c008ec09c/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/108) وتاريخ 1439/10/27هـ، لتكون بالنص الآتي: 

"تضمَّن المحكمة المختصة حكمها - الصادر بعقوبة السجن في إحدى المخالفات المنصوص عليها في المواد السابقة - النص على نشر ملخصه على نفقة المخالف، وللمحكمة المختصة النشر فيما عدا عقوبة السجن، وتحدد المحكمة طريقة النشر إما في إحدى الصحف المحلية أو في أي وسيلة أخرى مناسبة، وذلك بحسب نوع المخالفة المرتكبة وجسامتها وتأثيرها، على أن يكون النش بعد اكتساب الحكم الصفة النهائية".'),
('boe26-6ec18d2212cec24cbeccd828','cmpz6fx1k082hcwg2lc40bdht','يجوز للوزير - في حالة الضرورة أو الاستعجال - إصدار أمر بالحجز التحفظي على منتجٍ وسحبه من الأسواق عند الاشتباه في غشه على أن يعرض أمر الحجز خلال مدة لا تزيد على (اثنتين وسبعين) ساعة على المحكمة المختصة على النحو المبين في اللائحة، لتأكيد الحجز أو إلغائه','2018-09-19'::timestamptz,'مرسوم ملكي رقم م/10 وتاريخ 1440/1/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/85eb2897-bec6-4c0c-b1d7-ac7c008ec09c/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/10) وتاريخ 1440/1/9هـ، لتصبح بالنص الآتي:

"المادة (السابعة والعشرون): يجوز للوزير - في حالة الضرورة أو الاستعجال - إصدار أمر بالحجز التحفظي على منتجٍ وسحبه من الأسواق عند الاشتباه في غشه على أن يعرض أمر الحجز خلال مدة لا تزيد على (اثنتين وسبعين) ساعة على المحكمة المختصة على النحو المبين في اللائحة، لتأكيد الحجز أو إلغائه".'),
('boe26-c24b822afacbc3cb52f1b4c3','cmpz5ur8r00zpcwg28hi7tdxh','يكون للمكتبة   مجلس أمناء    يتكون من :
- رئيس للمجلس وخمسة أعضاء ممن لهم اهتمام بشئون المكتبات، يتم اختيارهم بأمر ملكي وتكون مدة عضويتهم ثلاث سنوات قابلة للتجديد مرتين.
- أمين للمكتبة عضواً','1996-08-08'::timestamptz,'مرسوم ملكي رقم م/2 وتاريخ 24/3/1417هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/891a3908-3c1b-4b06-85ac-a9a700f17132/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/2) وتاريخ 24/ 3/ 1417هـ ، لتصبح بالنص الآتي :

" يكون للمكتبة   مجلس أمناء    يتكون من :
- رئيس للمجلس وخمسة أعضاء ممن لهم اهتمام بشئون المكتبات، يتم اختيارهم بأمر ملكي وتكون مدة عضويتهم ثلاث سنوات قابلة للتجديد مرتين.
- أمين للمكتبة عضواً  ".'),
('boe26-2e878f5282bede3f3c263a6e','cmpz6r6ej0c25cwg2jeogd9ol','تصرف شهريا علاوة تدريس تعادل (25% من أول مربوط الرتبة للضباط القائمين فعلا بالتدريس في الكليات والمعاهد والمدارس والمراكز التعليمية العسكرية، وكذلك مدرسي الطيران الجوي المتفرغين للتدريس، كما يصرف ذلك للضباط الذين تتطلب طبيعة عملهم القيام بالتدريس لمواجهة حالات تدريب مؤقتة حسبما يقرره الوزير.','1977-09-03'::timestamptz,'مرسوم ملكي رقم م/56 وتاريخ 1397/9/20هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/56) وتاريخ 1397/9/20هـ، ليصبح نصها كالآتي: 

تصرف شهريا علاوة تدريس تعادل (25% من أول مربوط الرتبة للضباط القائمين فعلا بالتدريس في الكليات والمعاهد والمدارس والمراكز التعليمية العسكرية، وكذلك مدرسي الطيران الجوي المتفرغين للتدريس، كما يصرف ذلك للضباط الذين تتطلب طبيعة عملهم القيام بالتدريس لمواجهة حالات تدريب مؤقتة حسبما يقرره الوزير.

 '),
('boe26-5b6ceb11eaa52d7e59614d2a','cmpz6r7o90c2jcwg2tr7xbh2v','إذا أمضى الضابط من رتبة رائد فما دون أرب سنوات في رتبته بالإضافة إلى المدة المقررة في المادة (18) من هذه النظام ولم تتوافر شروط الترقية المنصوص عليها في المادة (21) – تنهى خدماته ويعامل بموجب النظام','2002-12-01'::timestamptz,'مرسوم ملكي رقم م/37 وتاريخ 1423/9/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','-  عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/37) وتاريخ 1423/9/26هـ، ليكون نصها كالآتي: "إذا أمضى الضابط من رتبة رائد فما دون أرب سنوات في رتبته بالإضافة إلى المدة المقررة في المادة (18) من هذه النظام ولم تتوافر شروط الترقية المنصوص عليها في المادة (21) – تنهى خدماته ويعامل بموجب النظام".'),
('boe26-49c560dd26186c72e8fe8fb2','cmpz6r8az0c2rcwg2wbjdo8u9','إذا أمضى اللواء ثلاث سنوات في الخدمة ولم يصدر امر بتمديد خدمته فيحال للتقاعد ويجوز مد خدمته ستين قابلة للتجديد عدة مرات وذلك بقرار من القائد الأعلى للقوات المسلحة بناء على اقتراح رئيس مجلس الوزراء وبعد توصية الوزير مالم يبلغ سن التقاعد في رتبته قبل ذلك.','1983-09-07'::timestamptz,'مرسوم ملكي رقم م/58 وتاريخ 1403/11/30هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/58) وتاريخ 1403/11/30هـ، ليصبح نصها كما يلي: إذا أمضى اللواء ثلاث سنوات في الخدمة ولم يصدر امر بتمديد خدمته فيحال للتقاعد ويجوز مد خدمته ستين قابلة للتجديد عدة مرات وذلك بقرار من القائد الأعلى للقوات المسلحة بناء على اقتراح رئيس مجلس الوزراء وبعد توصية الوزير مالم يبلغ سن التقاعد في رتبته قبل ذلك.'),
('boe26-1445fa34116d02145abe0e52','cmpz6r8gn0c2tcwg2tjosmt81','تكون الترقية إلى رتبة فريق بالاختيار المطلق بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على اقتراح رئيس مجلس الوزراء وتوصية الوزير وذلك من بين الضباط الحاصلين على رتبة لواء الذين أمضوا أربع سنوات على الأقل في هذه الرتبة وتكون مدة شغل الضابط لرتبة فريق أربع سنوات، قابلة للتجديد لمدة لا تزيد على أربع سنوات أخرى وذلك أمر من القائد الأعلى لكافة القوات العسكرية بناءً على اقتراح رئيس مجلس الوزراء وتوصية الوزير','2008-08-27'::timestamptz,'مرسوم ملكي رقم م/54 وتاريخ 1429/8/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','-  عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/54) وتاريخ 1429/8/26هـ، لتصبح بالنص الآتي: "تكون الترقية إلى رتبة فريق بالاختيار المطلق بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على اقتراح رئيس مجلس الوزراء وتوصية الوزير وذلك من بين الضباط الحاصلين على رتبة لواء الذين أمضوا أربع سنوات على الأقل في هذه الرتبة وتكون مدة شغل الضابط لرتبة فريق أربع سنوات، قابلة للتجديد لمدة لا تزيد على أربع سنوات أخرى وذلك أمر من القائد الأعلى لكافة القوات العسكرية بناءً على اقتراح رئيس مجلس الوزراء وت'),
('boe26-bc9728b214159dd59d4a1fcd','cmpz6r9w20c3bcwg2b54t1kp7','( أ – يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي بأمر من القائد الأعلى للقوات المسلحة بناء على توصية وزير الدفاع والطيران والمفتش العام).

ب – يتم اختيار رؤساء هيئات القوات المسلحة بقرار من الوزير بناء على توصية من رئيس هيئة الأركان العامة)','1986-07-16'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي:

( أ – يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي بأمر من القائد الأعلى للقوات المسلحة بناء على توصية وزير الدفاع والطيران والمفتش العام).

ب – يتم اختيار رؤساء هيئات القوات المسلحة بقرار من الوزير بناء على توصية من رئيس هيئة الأركان العامة)

 '),
('boe26-5eda2266f0ecb32409060476','cmpz6r9w20c3bcwg2b54t1kp7','يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي وقائد قوة الصواريخ الاستراتيجية بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على توصية وزير الدفاع','2017-04-25'::timestamptz,'مرسوم ملكي رقم م/81 وتاريخ 1438/7/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/81) وتاريخ 1438/7/28هـ، لتصبح على النحو الآتي: "يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي وقائد قوة الصواريخ الاستراتيجية بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على توصية وزير الدفاع".'),
('boe26-c2c1acbfb5a9d9746edc5ea7','cmpz6ra1q0c3dcwg24ceu2jm7','(يتم بتوصية من لجنة الضباط العليا نقل واثبات الضباط في قيادة القوات البرية الذين يشغلون مناصب قيادية من مستوى كتيبة وما يعاد لها فأعلى ومساعديهم وأركان الألوية وما يعاد لهم فأعلى والملحقين العسكريين ومساعديهم وضباط الاتصال ومساعديهم وكذلك ما يقابلهم في قيادات القوات الجوية والبحرية والدفاع الجوي).','1986-07-16'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة، وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي: (يتم بتوصية من لجنة الضباط العليا نقل واثبات الضباط في قيادة القوات البرية الذين يشغلون مناصب قيادية من مستوى كتيبة وما يعاد لها فأعلى ومساعديهم وأركان الألوية وما يعاد لهم فأعلى والملحقين العسكريين ومساعديهم وضباط الاتصال ومساعديهم وكذلك ما يقابلهم في قيادات القوات الجوية والبحرية والدفاع الجوي).'),
('boe26-59b2321e0e28a79c9f1912f4','cmpz6ra1q0c3dcwg24ceu2jm7','يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي وقائد قوة الصواريخ الاستراتيجية بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على توصية وزير الدفاع','2017-04-25'::timestamptz,'مرسوم ملكي رقم م/81 وتاريخ 1438/7/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/81) وتاريخ 1438/7/28هـ، لتصبح على النحو الآتي: "يتم اختيار نائب رئيس هيئة الأركان العامة وقائد القوات البرية وقائد القوات الجوية وقائد القوات البحرية وقائد قوات الدفاع الجوي وقائد قوة الصواريخ الاستراتيجية بأمر من القائد الأعلى لكافة القوات العسكرية بناءً على توصية وزير الدفاع".'),
('boe26-5b3af24a06d654daae9f8807','cmpz6rais0c3jcwg2l1a3tqx5','يجري نقل واثبات الضباط داخل كل قوة بالقوات المسلحة على الوجه الآتي: 

من رتبة مقدم فما فوق بتوصية من لجنة الضباط العليا.

من رتبة رائد فما دون بقرار من قائد القوة.','1989-01-17'::timestamptz,'مرسوم ملكي رقم م/40 وتاريخ 1409/6/10هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','-    عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/40) وتاريخ 1409/6/10هـ، لتكون كما يلي: " يجري نقل واثبات الضباط داخل كل قوة بالقوات المسلحة على الوجه الآتي: 

من رتبة مقدم فما فوق بتوصية من لجنة الضباط العليا.

من رتبة رائد فما دون بقرار من قائد القوة.'),
('boe26-6e057222e4e26129f3354b2b','cmpz7zrxq0c6n7b6wefiwv269','يستحق الضابط الذي يصاب بجرح أو مرض – يمنعه من أداء عمله بصفة مؤقتة، ويكون ذلك أثناء عمله وبسببه – إجازة مرضية بدلاً من الإجازة المنصوص عليها في المادة (95) مدتها سنة ونصف السنة براتب كامل، فإن لم يعد إلى عمله بعد انتهاء هذه المدة يعرض أمره على اللجنة الطبية لتقرر إما التوصية بإحالته إلى التقاعد أو تمديد إجازته مع تحديد المدة الإضافية، ويصرف له في هذه الحالة نصف الراتب','2002-12-01'::timestamptz,'مرسوم ملكي رقم م/37 وتاريخ 1423/9/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/37) وتاريخ 1423/9/26هـ، ليكون نصها كالآتي: "يستحق الضابط الذي يصاب بجرح أو مرض – يمنعه من أداء عمله بصفة مؤقتة، ويكون ذلك أثناء عمله وبسببه – إجازة مرضية بدلاً من الإجازة المنصوص عليها في المادة (95) مدتها سنة ونصف السنة براتب كامل، فإن لم يعد إلى عمله بعد انتهاء هذه المدة يعرض أمره على اللجنة الطبية لتقرر إما التوصية بإحالته إلى التقاعد أو تمديد إجازته مع تحديد المدة الإضافية، ويصرف له في هذه الحالة نصف الراتب".'),
('boe26-5d3e92402c241796b36c2ffa','cmpz6re5s0c4tcwg202r5d3zf','يحرم الضابط الطيار، والضابط مشغل أنظمة التسليح على الطائرات المقاتلة، من علاوة الطيران، متى ثبت تقصيره في أداء واجباته المتعلقة بأعمال الطيران، أو ثبت ضعف مستوى طيرانه، أو لم يُتم الحد الأدنى لعدد ساعات الطيران المقررة لكل رتبة. وتحدد لجنة الضباط العليا مدى هذه الواجبات وكيفية أدائها بناء على اقتراح قائد القوات الجوية. ويكون الحرمان – كلياً أو جزئياً – بنسبة تقصير الضابط في أداء واجباته المتعلقة بأعمال الطيران','2003-06-11'::timestamptz,'مرسوم ملكي رقم م/19 وتاريخ 1424/4/11هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','-  عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/19) وتاريخ 1424/4/11هـ، لتصبح بالنص التالي: "يحرم الضابط الطيار، والضابط مشغل أنظمة التسليح على الطائرات المقاتلة، من علاوة الطيران، متى ثبت تقصيره في أداء واجباته المتعلقة بأعمال الطيران، أو ثبت ضعف مستوى طيرانه، أو لم يُتم الحد الأدنى لعدد ساعات الطيران المقررة لكل رتبة. وتحدد لجنة الضباط العليا مدى هذه الواجبات وكيفية أدائها بناء على اقتراح قائد القوات الجوية. ويكون الحرمان – كلياً أو جزئياً – بنسبة تقصير الضابط في أداء واجباته المتعلقة بأ'),
('boe26-949dc95960a82c5a5399bb21','cmpz7zqmb0c657b6wqnnv7i9n','الإجازات هي: اعتيادية، عرضية، ميدانية، استثنائية، مرضية، مرافقة دراسية','2020-11-12'::timestamptz,'مرسوم ملكي رقم م/28 وتاريخ 1442/3/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/28) وتاريخ 1442/3/26هـ، لتكون بالنص الآتي: "الإجازات هي: اعتيادية، عرضية، ميدانية، استثنائية، مرضية، مرافقة دراسية".'),
('boe26-546ef071078c9343c5e89ddd','cmpz7zrsg0c6l7b6w1xsbhbg2','يستحق الضابط إجازة مرضية، في مدة ثلاث سنوات، مدتها اثنا عشر شهراً بالراتب الفعلي، وستة أشهر بنصف الراتب الفعلي','2005-08-13'::timestamptz,'مرسوم ملكي رقم م/34 وتاريخ 1426/7/8هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/34) وتاريخ 1426/7/8هـ، لتصبح بالنص الآتي: "يستحق الضابط إجازة مرضية، في مدة ثلاث سنوات، مدتها اثنا عشر شهراً بالراتب الفعلي، وستة أشهر بنصف الراتب الفعلي".'),
('boe26-09534ee7e32a10e2ebfa0de3','cmpz7zvg10c7x7b6wpvzi0aws','إذا قدم الضابط طلباً للإحالة إلى التقاعد أو الاستقالة فللمراجع المختصة حق رفضه أو قبوله، ويخطر الضابط بالقبول أو الرفض في مدة أقصاها ثلاثة أشهر، أما إذا كان الضابط رهن التحقيق أو المحاكمة فيجب إرجاء البتّ في الطلب إلى أن ينتهي التحقيق بالحفظ أو المحاكمة، وفي الحالة الأخيرة يُنتظر أن يصدّق على الحكم ثم يُنظر في طلبه على ضوء النتيجة','2020-11-12'::timestamptz,'مرسوم ملكي رقم م/28 وتاريخ 1442/3/26هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/28) وتاريخ 1442/3/26هـ، لتكون بالنص الآتي: "إذا قدم الضابط طلباً للإحالة إلى التقاعد أو الاستقالة فللمراجع المختصة حق رفضه أو قبوله، ويخطر الضابط بالقبول أو الرفض في مدة أقصاها ثلاثة أشهر، أما إذا كان الضابط رهن التحقيق أو المحاكمة فيجب إرجاء البتّ في الطلب إلى أن ينتهي التحقيق بالحفظ أو المحاكمة، وفي الحالة الأخيرة يُنتظر أن يصدّق على الحكم ثم يُنظر في طلبه على ضوء النتيجة".'),
('boe26-283d599a8b020bc2ea43f9c8','cmpz7zwm30c8d7b6wsjmpm25u','(عند غياب رئيس اللجنة العليا يحل محله من يكلف بالقيام بعمله وإذا غاب أحد قادة القوات فيحل محله نائبه)','1986-07-16'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي 

(عند غياب رئيس اللجنة العليا يحل محله من يكلف بالقيام بعمله وإذا غاب أحد قادة القوات فيحل محله نائبه)'),
('boe26-fa774572b2f21992e24ec5de','cmpz7zyd40c917b6wzdhwt513','(تشكل لجان ضباط فرعية في فروع القوات المسلحة –القوات البرية- القوات الجوية- القوات البحرية- قوات الدفاع الجوي- وتتكون كل منها من خمسة ضباط على مستوى جيد من الثقافة والتخطيط وحسن الادراك ويرأسها أقدم ضابط منهم على أن يكون أحدهم مدير إدارة شئون ضباط ذلك الفرع عضوا وسكرتيرا لها ولا يجوز أن يشترك في هذه اللجان أي من أعضاء لجنة الضباط العليا).','1986-07-16'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي: (تشكل لجان ضباط فرعية في فروع القوات المسلحة –القوات البرية- القوات الجوية- القوات البحرية- قوات الدفاع الجوي- وتتكون كل منها من خمسة ضباط على مستوى جيد من الثقافة والتخطيط وحسن الادراك ويرأسها أقدم ضابط منهم على أن يكون أحدهم مدير إدارة شئون ضباط ذلك الفرع عضوا وسكرتيرا لها ولا يجوز أن يشترك في هذه اللجان أي من أعضاء لجنة الضباط العليا).'),
('boe26-9a901a3c5f19c2fe5288faff','cmpz7zyd40c917b6wzdhwt513','تشكل لجان ضباط فرعية في فروع القوات المسلحة – القوات البرية – القوات الجوية – القوات البحرية – قوات الدفاع الجوي – قوة الصواريخ الاستراتيجية – وتتكون كل منها من خمسة ضباط على مستوى جيد من الثقافة والتخطيط وحسن الإدراك ويرأسها أقدم ضابط منهم على أن يكون مدير إدارة شؤون ضباط ذلك الفرع عضواً وسكرتيراً لها ولا يجوز أن يشترك في هذه اللجان أي من أعضاء لجنة الضباط العليا','2017-04-25'::timestamptz,'مرسوم ملكي رقم م/81 وتاريخ 1438/7/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/81) وتاريخ 1438/7/28هـ، لتكون على النحو الآتي: "تشكل لجان ضباط فرعية في فروع القوات المسلحة – القوات البرية – القوات الجوية – القوات البحرية – قوات الدفاع الجوي – قوة الصواريخ الاستراتيجية – وتتكون كل منها من خمسة ضباط على مستوى جيد من الثقافة والتخطيط وحسن الإدراك ويرأسها أقدم ضابط منهم على أن يكون مدير إدارة شؤون ضباط ذلك الفرع عضواً وسكرتيراً لها ولا يجوز أن يشترك في هذه اللجان أي من أعضاء لجنة الضباط العليا".'),
('boe26-9436bdd768c7a90d1eb47ec8','cmpz7zyid0c937b6w5avd017w','(يرشح كل قائد من قادة القوات البرية والجوية والبحرية والدفاع الجوي رئيس وأعضاء لجنة الضباط الفرعية في قواته وذلك وفقاً للمادة (139) من النظام).','1986-07-16'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي: (يرشح كل قائد من قادة القوات البرية والجوية والبحرية والدفاع الجوي رئيس وأعضاء لجنة الضباط الفرعية في قواته وذلك وفقاً للمادة (139) من النظام).'),
('boe26-288ed1fe0cbefe2c5c6e9ede','cmpz7zyid0c937b6w5avd017w','يرشح كل قائد من قادة القوات البرية والجوية والبحرية والدفاع الجوي وقوة الصواريخ الاستراتيجية رئيس وأعضاء لجنة الضباط الفرعية في قواته وذلك وفقاً للمادة (139) من النظام','2017-04-25'::timestamptz,'مرسوم ملكي رقم م/81 وتاريخ 1438/7/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/81) وتاريخ 1438/7/28هـ، لتكون بالنص الآتي: "يرشح كل قائد من قادة القوات البرية والجوية والبحرية والدفاع الجوي وقوة الصواريخ الاستراتيجية رئيس وأعضاء لجنة الضباط الفرعية في قواته وذلك وفقاً للمادة (139) من النظام".'),
('boe26-fe4072fb23e9d4bf1fca1a63','cmpz7zz8o0c9d7b6wgrcjgmx2','(ترفع توصيات كل لجنة من لجان الضباط الفرعية بعد أن يتم إقرارها من قائد القوات المختص).','1986-07-16'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي: (ترفع توصيات كل لجنة من لجان الضباط الفرعية بعد أن يتم إقرارها من قائد القوات المختص).'),
('boe26-f508cf0e9d47090a1512be2f','cmpz8009g0c9r7b6woras15fr','(تنظم أعمال لجان الضباط الفرعية في القوات المسلحة بقرار يصدر من قائد القوات المختص بناء على توصية مدير إدارة شؤون الضباط في قواته بعد التنسيق مع مدير إدارة شؤون ضباط القوات المسلحة ينظم سير أعمال لجنة الضباط الفرعية في قواته واجتماعاتها والبت في القضايا المنوطة بها وفقا لأحكام هذا النظام).','1986-07-16'::timestamptz,'مرسوم ملكي رقم م/25 وتاريخ 1406/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/25) وتاريخ 1406/11/9هـ، لتكون بالنص الآتي: (تنظم أعمال لجان الضباط الفرعية في القوات المسلحة بقرار يصدر من قائد القوات المختص بناء على توصية مدير إدارة شؤون الضباط في قواته بعد التنسيق مع مدير إدارة شؤون ضباط القوات المسلحة ينظم سير أعمال لجنة الضباط الفرعية في قواته واجتماعاتها والبت في القضايا المنوطة بها وفقا لأحكام هذا النظام).'),
('boe26-c9f2fb928a5979f419b65d7d','cmpz800ep0c9t7b6weh1h2s0g','يُعطى الضابط الذي تلحقه خسارة مادية بسبب عمله، أو قيامه بتأديته، أو قيامه بمهمة رسمية، تعويضاً للخسارة الفعلية، على أن يقدم خلال ثلاثة أشهر من تاريخ وقوع الخسارة طلب التعويض والوثائق المثبتة للخسارة إلى الوزير عن طريق المرجع، وإلا سقط الحق بالمطالبة به، ما لم يكن ثمة عذر شرعي – يقدره الوزير المختص – حال دون تقديم طلب التعويض خلال تلك المدة','2018-07-11'::timestamptz,'مرسوم ملكي رقم م/107 وتاريخ 1439/10/27هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8a12c94e-5a31-45cf-9c57-ac4400be8677/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/107) وتاريخ 1439/10/27هـ، لتكون بالنص الآتي: "يُعطى الضابط الذي تلحقه خسارة مادية بسبب عمله، أو قيامه بتأديته، أو قيامه بمهمة رسمية، تعويضاً للخسارة الفعلية، على أن يقدم خلال ثلاثة أشهر من تاريخ وقوع الخسارة طلب التعويض والوثائق المثبتة للخسارة إلى الوزير عن طريق المرجع، وإلا سقط الحق بالمطالبة به، ما لم يكن ثمة عذر شرعي – يقدره الوزير المختص – حال دون تقديم طلب التعويض خلال تلك المدة".'),
('boe26-6f4bff628cdcfee90032aa38','cmpz6liwt0a3ncwg2zd3x99wb','يكون للمجمع أمين عام يعين ويعفى بقرار من المجلس بناء على اقتراح من رئيسه، ويحدد القرار أجره ومزاياه المالية الأخرى، ويتولى إدارة المجمع في حدود ما يقضي به هذا التنظيم، وما يُقرره المجلس، ويمثله أمام القضاء والهيئات والمؤسسات الأُخرى. وتحدد صلاحياته ومسؤولياته بناءً على لائحة يصدرها المجلس','2022-02-15'::timestamptz,'قرار مجلس الوزراء رقم 391 وتاريخ 1443/7/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8f0b8e8e-a856-4567-9396-a9a700f20b4d/1','-عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (391) وتاريخ 1443/7/14هـ، لتكون بالنص الآتي: "يكون للمجمع أمين عام يعين ويعفى بقرار من المجلس بناء على اقتراح من رئيسه، ويحدد القرار أجره ومزاياه المالية الأخرى، ويتولى إدارة المجمع في حدود ما يقضي به هذا التنظيم، وما يُقرره المجلس، ويمثله أمام القضاء والهيئات والمؤسسات الأُخرى. وتحدد صلاحياته ومسؤولياته بناءً على لائحة يصدرها المجلس".'),
('boe26-bd48b58c6599c0bf51e9310c','cmpwi2xtg00hjnxfftdpf43p6','يخضع رجال الضبط الجنائي - فيما يتعلق بوظائفهم في الضبط الجنائي المقررة في هذا النظام - لإشراف النيابة العامة. وللنيابة العامة أن تطلب من الجهة المختصة النظر في أمر كل من تقع منه مخالفة لواجباته أو تقصير في عمله، ولها أن تطلب رفع الدعوى التأديبية عليه، وتشعر النيابة العامة بما تم في شأن ذلك الطلب، وذلك دون إخلال بالحق في رفع الدعوى الجزائية','2021-11-04'::timestamptz,'مرسوم ملكي رقم م/28 وتاريخ 1443/3/29هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/8f1b7079-a5f0-425d-b5e0-a9a700f26b2d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/28) وتاريخ 1443/3/29هـ، لتكون بالنص الآتي: " يخضع رجال الضبط الجنائي - فيما يتعلق بوظائفهم في الضبط الجنائي المقررة في هذا النظام - لإشراف النيابة العامة. وللنيابة العامة أن تطلب من الجهة المختصة النظر في أمر كل من تقع منه مخالفة لواجباته أو تقصير في عمله، ولها أن تطلب رفع الدعوى التأديبية عليه، وتشعر النيابة العامة بما تم في شأن ذلك الطلب، وذلك دون إخلال بالحق في رفع الدعوى الجزائية".'),
('boe26-357a20d67c0e25a5f06bab51','cmpz6lmpk0a4xcwg235y1kgfc','يتولى موظفون من الوزارة أو غيرهم -يصدر بتسميتهم قرار من الوزير- الرقابة على شركات ضيافة الحجاج وشركات تقديم الخدمة والتفتيش عليها وضبط ما يقع منها من مخالفات؛ لتطبيق أحكام النظام والقرارات الصادرة تنفيذًا له.','2025-11-03'::timestamptz,'مرسوم ملكي رقم م/89 وتاريخ 1447/5/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/962235c2-9fa8-4c1a-b835-aa6400dd851e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/89) وتاريخ 1447/5/12هـ، لتكون بالنص الآتي:

" يتولى موظفون من الوزارة أو غيرهم -يصدر بتسميتهم قرار من الوزير- الرقابة على شركات ضيافة الحجاج وشركات تقديم الخدمة والتفتيش عليها وضبط ما يقع منها من مخالفات؛ لتطبيق أحكام النظام والقرارات الصادرة تنفيذًا له.'),
('boe26-93414eb670e3f7453f218239','cmpz64x2p04cxcwg2nr3drpg8','يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية','2022-04-19'::timestamptz,'قرار مجلس الوزراء رقم 539 وتاريخ 1443/9/18هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/98642c12-dd48-4148-841d-a9a700f1b3ea/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (539) وتاريخ 1443/9/18هـ. لتكون بالنص الآتي: "يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية".'),
('boe26-1b528c1be07db20e09789baf','cmpzcvdug0c9ivtrknfzrw9ri','تهدف الهيئة إلى تنظيم نشاط النقل العام والإشراف عليه وعلى سلامة تشغيل مرافقه وتجهيزاته وحسن إدارتها، وتوفيره بالمستوى الجيد والكلفة الملائمة، وتنظيم الاستثمار فيه بما يتفق مع أهداف التنمية الاقتصادية والاجتماعية في المملكة، وتراعى في كل ذلك الجوانب الفنية والبيئية والتكامل مع أنظمة النقل الجوي. وللهيئة في سبيل تحقيق أهدافها ممارسة المهمات والاختصاصات الآتية:

1 - إعداد الخطط السنوية والخمسية لنشاطاتها في إطار الأهداف والسياسات العامة لها بالتنسيق مع الجهات ذات العلاقة.

2 - الإشراف على تنفيذ خطط النقل العام على مستوى المملكة، والتأكد من توافر التمويل لأنشطته من مصادره المختلفة.

3 - اقتراح السياسات العامة والتشريعات الخاصة بالنقل العام، والإشراف على تنفيذها بعد اعتمادها.

4 - ضمان عدالة المنافسة بين مقدمي خدمات النقل العام.

5 - إجراء البحوث والدراسات اللازمة لتقويم نشاط النقل العام، والعمل على تطويره باستمرار.

6 - تحديد شبكة خطوط النقل العام ومساراتها.

7 - وضع أسس تنظيم الأنشطة الخاصة بمرافق النقل العام وإداراتها.

8 - وضع المواصفات والشروط الفنية ومعايير السلامة اللازمة لوسائل ووسائط النقل العام، بالمشاركة والتنسيق مع الجهات ذات العلاقة.

9 - إصدار التراخيص والتصاريح لجميع وسائل النقل العام، وإلغاؤها في حال مخالفة أحكام الأنظمة ذات الصلة.

10 - تحديد مواقع مرافق النقل العام – بالتنسيق مع الجهات ذات العلاقة – والإشراف على خدماتها، بما في ذلك محطات الوصول والانطلاق لوسائط النقل العام وأهمية قربها من المطارات.

11 - اقتراح آلية لتنظيم أجور النقل العام وأسس تسعيرها، ومتابعة الالتزام بها بعد اعتماد الأجور من الجهات المختصة.

12 - مراقبة وسائل النقل العام ومرافقه في المملكة، وإعادة هيكلتها بما يتناسب مع الحاجة إليها.

13 - توظيف التقنية في تنفيذ ومراقبة أعمال الهيئة ومهماتها.

14 - إعادة الدراسات اللازمة لمخططات النقل العام وتصميم منظوماته.

15 - مراقبة الالتزام بتنفيذ العقود المبرمة بين الهيئة والأطراف الأخرى.

16 - العمل على حماية مصالح المستخدمين المتعلقة بخدمات النقل العام، ومراقبة أداء المرخصين والمصرح لهم بتقديم تلك الخدمات، واتخاذ الإجراءات التي تكفل تقيدهم بشروط التراخيص والتصاريح الممنوحة لهم.

17 - التأكد من سلامة وسائط النقل العام بالتعاون والتنسيق مع الجهات ذات العلاقة.

18 - توفير الظروف الملائمة لجذب الاستثمارات في مجال النقل العام.

19 - العمل على وضع المواصفات اللازمة للحد من التلوث البيئي المرتبط بأنشطة النقل العام، بالتعاون مع الجهات المختصة.

20 - التنسيق مع الهيئة العامة للطيران المدني والجهات المعنية الأخرى لضمان تنفيذ الاستراتيجية الوطنية للنقل.

21 - تمثيل المملكة في المنظمات الدولية والإقليمية ذات العلاقة بالنقل العام.

22 - متابعة تنفيذ اتفاقيات النقل المبرمة بين المملكة والدول الأخرى.

23 - التحقيق فنياً في حوادث النقل العام التي تنتج منها خسائر في الأرواح أو الممتلكات أو تعطيل لأنشطة النقل العام، بالمشاركة مع الجهات المختصة.

24 - القيام بأي مهمة أخرى تكلف بها في مجال اختصاصها','2016-03-21'::timestamptz,'قرار مجلس الوزراء رقم 248 وتاريخ 12/6/1437هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/9a1c4977-c539-4e01-8c88-a9a700f2efa9/1','تم تعديل هذه المادة بموجب قرار مجلس الوزراء رقم (248) وتاريخ 12/ 6/ 1437هـ ، لتكون بالنص الآتي:

" تهدف الهيئة إلى تنظيم نشاط النقل العام والإشراف عليه وعلى سلامة تشغيل مرافقه وتجهيزاته وحسن إدارتها، وتوفيره بالمستوى الجيد والكلفة الملائمة، وتنظيم الاستثمار فيه بما يتفق مع أهداف التنمية الاقتصادية والاجتماعية في المملكة، وتراعى في كل ذلك الجوانب الفنية والبيئية والتكامل مع أنظمة النقل الجوي. وللهيئة في سبيل تحقيق أهدافها ممارسة المهمات والاختصاصات الآتية:

1 - إعداد الخطط السنوية والخمسية لنشاطا'),
('boe26-8927652b3839ce761cf99d89','cmpz61v1p03d3cwg2ujupskrj','يصرف للفرد أثناء مدة توقيفه أو سجنه لغرض التحقيق أو المحاكمة نصف صافي راتبه، فان لم تثبت ادانته او عوقب بغير الطرد، يعاد اليه ما استقطع من راتبه','2001-12-07'::timestamptz,'مرسوم ملكي رقم م/44 وتاريخ 1422/9/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/9b461caf-dc11-46bd-a8fd-ac74009a8724/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/44) وتاريخ 1422/9/22هـ، لتصبح بالنص الآتي: "يصرف للفرد أثناء مدة توقيفه أو سجنه لغرض التحقيق أو المحاكمة نصف صافي راتبه، فان لم تثبت ادانته او عوقب بغير الطرد، يعاد اليه ما استقطع من راتبه".'),
('boe26-21f59019193cef64858795be','cmpz61vq303dbcwg2frymz1hn','يستحق الافراد علاوات فنية بموجب جدول العلاوات الفنية المرفق بهذا النظام، ويجوز الجمع بين علاوتين فنيتين فقط إذا قام بعملهما معا وتحدد اللائحة التنفيذية شروط منح هذه العلاوات وتصنيفها وفق التخصصات','1977-09-03'::timestamptz,'مرسوم ملكي رقم م/56 وتاريخ 1397/9/20هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/9b461caf-dc11-46bd-a8fd-ac74009a8724/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/56) وتاريخ 1397/9/20هـ، لتصبح بالنص الآتي: "يستحق الافراد علاوات فنية بموجب جدول العلاوات الفنية المرفق بهذا النظام، ويجوز الجمع بين علاوتين فنيتين فقط إذا قام بعملهما معا وتحدد اللائحة التنفيذية شروط منح هذه العلاوات وتصنيفها وفق التخصصات".'),
('boe26-deaaeca1de60cb956cd9c659','cmpz61z1i03dzcwg2t74l9bre','يصرف للفرد بدل ترحيل وفقاً للأحكام التي تحددها اللائحة التنفيذية، وذلك عند تعيينه لأول مرة في الخدمة، أو نقله من بلد إلى آخر داخل المملكة، أو نقله من داخل المملكة إلى خارجها أو العكس، أو نقله من جهة إلى أخرى خارج المملكة، أو عند ابتعاثه أو إلحاقه لمدة تزيد على ستة أشهر، أو عند انتدابه لمدة أو مدد متواصلة تزيد على ثلاثة أشهر','2007-04-24'::timestamptz,'مرسوم ملكي رقم م/34 وتاريخ 1428/4/7هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/9b461caf-dc11-46bd-a8fd-ac74009a8724/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/ 34) وتاريخ 1428/4/7هـ، لتكون بالنص الآتي: "يصرف للفرد بدل ترحيل وفقاً للأحكام التي تحددها اللائحة التنفيذية، وذلك عند تعيينه لأول مرة في الخدمة، أو نقله من بلد إلى آخر داخل المملكة، أو نقله من داخل المملكة إلى خارجها أو العكس، أو نقله من جهة إلى أخرى خارج المملكة، أو عند ابتعاثه أو إلحاقه لمدة تزيد على ستة أشهر، أو عند انتدابه لمدة أو مدد متواصلة تزيد على ثلاثة أشهر".'),
('boe26-a70fac42cd62fc5967cd51ed','cmpz61z1i03dzcwg2t74l9bre','يصرف للفرد بدل ترحيل وفقاً للأحكام التي تحددها اللائحة التنفيذية، وذلك عند تعيينه لأول مرة في الخدمة، أو نقله من بلد إلى آخر داخل المملكة، أو نقله من داخل المملكة إلى خارجها أو العكس، أو نقله من جهة إلى جهة أخرى خارج المملكة، أو عند ابتعاثه، أو إلحاقه لمدة تزيد على ستة أشهر، أو عند انتدابه لمدة أو لمدد ثلاثة أشهر فأكثر','2023-08-27'::timestamptz,'مرسوم ملكي رقم م/28 وتاريخ 1445/2/11هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/9b461caf-dc11-46bd-a8fd-ac74009a8724/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/28) وتاريخ 1445/2/11هـ، لتكون بالنص الآتي: "يصرف للفرد بدل ترحيل وفقاً للأحكام التي تحددها اللائحة التنفيذية، وذلك عند تعيينه لأول مرة في الخدمة، أو نقله من بلد إلى آخر داخل المملكة، أو نقله من داخل المملكة إلى خارجها أو العكس، أو نقله من جهة إلى جهة أخرى خارج المملكة، أو عند ابتعاثه، أو إلحاقه لمدة تزيد على ستة أشهر، أو عند انتدابه لمدة أو لمدد ثلاثة أشهر فأكثر".'),
('boe26-e16c5fa9ff86812e02ceb06e','cmpzcvci50bvjvtrkif3yztuk','يكون للمحافظ نائبان متفرغان يعاونانه في أداء مهماته ومسؤولياته. ويحدد المجلس بقرار منه اختصاصات كل منهما وصلاحياته ومهماته بناء على توصية من المحافظ. ولا يشارك أي من النائبين في مداولات القرار ولا في التصويت عليه.

يعين نائبا المحافظ بالمرتبة الممتازة بناءً على اقتراح من المحافظ،وتحديد مزاياهما بأمر ملكي.

يكلف المحافظ أحد النائبين ليحل محله عند غيابه.','2022-03-01'::timestamptz,'قرار مجلس الوزراء رقم 412 وتاريخ 1443/7/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a292ec7e-85fb-4ceb-9ad0-ac9200ced829/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (412) وتاريخ 1443/7/28هـ، لتكون بالنص الآتي: 

يكون للمحافظ نائبان متفرغان يعاونانه في أداء مهماته ومسؤولياته. ويحدد المجلس بقرار منه اختصاصات كل منهما وصلاحياته ومهماته بناء على توصية من المحافظ. ولا يشارك أي من النائبين في مداولات القرار ولا في التصويت عليه.

يعين نائبا المحافظ بالمرتبة الممتازة بناءً على اقتراح من المحافظ،وتحديد مزاياهما بأمر ملكي.

يكلف المحافظ أحد النائبين ليحل محله عند غيابه.'),
('boe26-6019f0fe7c8e17bbc6eeaf7e','cmpzcv2ti095tvtrk4a3y1c7m','يعاقب بالسجن لمدة لا تقل عن (ستة) أشهر ولا تزيد على (سبع) سنوات، وبغرامة لا تقل عن (خمسين ألف) ريال ولا تزيد على (خمسمائة ألف)، أو بإحدى هاتين العقوبتين، كل من استولى بصورة غير مشروعة على أثر من ممتلكات الدولة','2021-03-25'::timestamptz,'مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بالسجن لمدة لا تقل عن (ستة) أشهر ولا تزيد على (سبع) سنوات، وبغرامة لا تقل عن (خمسين ألف) ريال ولا تزيد على (خمسمائة ألف)، أو بإحدى هاتين العقوبتين، كل من استولى بصورة غير مشروعة على أثر من ممتلكات الدولة".'),
('boe26-bf48e4ceaec6e5e214445b29','cmpzcv2ti095uvtrknk6fq07a','يعاقب بالسجن لمدة لا تقل عن (ثلاثة) أشهر ولا تزيد على (ثلاث) سنوات، وبغرامة لا تقل عن (عشرين ألف) ريال ولا تزيد على (ثلاثمائة ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- تعدى على أثر، أو موقع أثري، أو موقع تراث عمراني، بإتلافه، أو تحويره، أو إزالته، أو نبشه، أو إلحاق الضرر به، أو تغيير معالمه، أو طمسه.

2- مسح أو نقب عن الآثار دون ترخيص','2021-03-25'::timestamptz,'مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','/- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بالسجن لمدة لا تقل عن (ثلاثة) أشهر ولا تزيد على (ثلاث) سنوات، وبغرامة لا تقل عن (عشرين ألف) ريال ولا تزيد على (ثلاثمائة ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- تعدى على أثر، أو موقع أثري، أو موقع تراث عمراني، بإتلافه، أو تحويره، أو إزالته، أو نبشه، أو إلحاق الضرر به، أو تغيير معالمه، أو طمسه.

2- مسح أو نقب عن الآثار دون ترخيص".'),
('boe26-bbab002d7b5bc9a390af1073','cmpzcv2ti095vvtrkwbno8fkc','يعاقب بالسجن لمدة لا تزيد على (سنتين) وبغرامة لا تزيد على (مائتي ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- قلد أثراً أو زيفه مدعياً أثريته.

2- قام بأي من أعمال الهدم الكلي أو الجزئي داخل حدود مواقع الآثار والتراث العمراني، أو بنى عليها، دون الحصول على موافقة من الوزارة.

3- خالف شروط الارتفاق وحقوقه المفروضة على الأراضي المجاورة لموقع الآثار.

4- انتشل -عمداً- أثراً غارقاً، أو نقله عن مكانه','2021-03-25'::timestamptz,'مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بالسجن لمدة لا تزيد على (سنتين) وبغرامة لا تزيد على (مائتي ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- قلد أثراً أو زيفه مدعياً أثريته.

2- قام بأي من أعمال الهدم الكلي أو الجزئي داخل حدود مواقع الآثار والتراث العمراني، أو بنى عليها، دون الحصول على موافقة من الوزارة.

3- خالف شروط الارتفاق وحقوقه المفروضة على الأراضي المجاورة لموقع الآثار.

4- انتشل -عمداً- أثراً غارقاً، أو نقله عن مكانه".'),
('boe26-4fca03b01e3cadfed9e400bf','cmpzcv2ti095wvtrkq4zwampk','يعاقب بالسجن لمدة لا تزيد على (سنة) وبغرامة لا تزيد على (مائة ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- غيّر مبنى أو موقع تراث عمراني، أو أجرى في البيئة المحيطة به تعديلاً يؤدي إلى الإضرار به دون أخذ موافقة الوزارة.

2- نقل أنقاضاً أو أحجاراً أو أتربة من مواقع الآثار والتراث العمراني دون موافقة الوزارة.

3- رمى أنقاضاً أو مخلفات في مواقع الآثار والتراث العمراني.

4- شوّه أثراً أو تراثاً عمرانياً بالكتابة، أو الطلاء، أو النقش، أو إلصاق الإعلانات عليه، أو بافتعال الحريق','2021-03-25'::timestamptz,'مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بالسجن لمدة لا تزيد على (سنة) وبغرامة لا تزيد على (مائة ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- غيّر مبنى أو موقع تراث عمراني، أو أجرى في البيئة المحيطة به تعديلاً يؤدي إلى الإضرار به دون أخذ موافقة الوزارة.

2- نقل أنقاضاً أو أحجاراً أو أتربة من مواقع الآثار والتراث العمراني دون موافقة الوزارة.

3- رمى أنقاضاً أو مخلفات في مواقع الآثار والتراث العمراني.

4- شوّه أثراً أو تراثاً عمرانياً'),
('boe26-2299500c4d427808c542213e','cmpzcv2ti095xvtrkr96llu5f','يعاقب بغرامة لا تزيد على (سبعين ألف) ريال كل من خالف الشروط المتعلقة بالآثار والتراث العمراني في الرخصة الممنوحة له الخاصة بترميم المباني الأثرية والتراثية وأحكامها','2021-03-25'::timestamptz,'مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بغرامة لا تزيد على (سبعين ألف) ريال كل من خالف الشروط المتعلقة بالآثار والتراث العمراني في الرخصة الممنوحة له الخاصة بترميم المباني الأثرية والتراثية وأحكامها".'),
('boe26-5d429bb842c3695c4fedfb1e','cmpzcv2ti095yvtrkyshk48he','يعاقب بغرامة لا تزيد على (ستين ألف) ريال كل من:

1- حاز أو صنع نماذجاً أو نسخاً للآثار لأغراض تجارية دون ترخيص من الوزارة.

2- أخفى الآثار التي اكتشفها أو عثر عليها، أو امتنع عن تسليمها إلى الوزارة.

3- صدّر أثراً منقولاً أو باعه أو تصرف فيه، بالمخالفة لأحكام هذا النظام ولوائحه.

4- وضع لافتات أو لوحات أو غيرها من علامات الدعاية على مواقع الآثار والتراث العمراني دون موافقة الوزارة','2021-03-25'::timestamptz,'مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ ، لتصبح بالنص الآتي: "يعاقب بغرامة لا تزيد على (ستين ألف) ريال كل من:

1- حاز أو صنع نماذجاً أو نسخاً للآثار لأغراض تجارية دون ترخيص من الوزارة.

2- أخفى الآثار التي اكتشفها أو عثر عليها، أو امتنع عن تسليمها إلى الوزارة.

3- صدّر أثراً منقولاً أو باعه أو تصرف فيه، بالمخالفة لأحكام هذا النظام ولوائحه.

4- وضع لافتات أو لوحات أو غيرها من علامات الدعاية على مواقع الآثار والتراث العمراني دون موافقة الوزارة".'),
('boe26-e1e5e147be02acc80f4c2f17','cmpzcv2ti095zvtrkxi2ww4ui','يعاقب بغرامة لا تزيد على (خمسين ألف) ريال كل من:

1- لم يقدم للوزارة بياناً بالآثار التي يملكها.

2- حاز قطعة أثرية أصلية غير مسجلة.

3- حاز أثراً لا يحمل ما يثبت شرعية ملكيته.

4- باع أو أجّر أو نقل ملكية أثر ثابت، أو موقع تراث عمراني مصنف، دون أخذ موافقة الوزارة.

5- زاول نشاط ترميم الآثار المنقولة لأغراض تجارية دون الحصول على ترخيص من الوزارة، أو خالف شروط الترخيص الممنوح له.

6- قام بعمل من أعمال الصيانة أو التجزئة والتقسيم في مباني وأحياء وقرى التراث العمراني المصنفة، دون الحصول على موافقة الوزارة.

7- قام من المتاحف بترميم قطعة أثرية يملكها ومسجلة في سجل الآثار دون الحصول على موافقة الوزارة.

8- زاول نشاط تشغيل المتاحف دون الحصول على ترخيص من الوزارة، أو خالف شروط الترخيص الممنوح له.

9- عرقل عمل فرق الوزارة في مواقع الآثار والتراث العمراني','2021-03-25'::timestamptz,'مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بغرامة لا تزيد على (خمسين ألف) ريال كل من:

1- لم يقدم للوزارة بياناً بالآثار التي يملكها.

2- حاز قطعة أثرية أصلية غير مسجلة.

3- حاز أثراً لا يحمل ما يثبت شرعية ملكيته.

4- باع أو أجّر أو نقل ملكية أثر ثابت، أو موقع تراث عمراني مصنف، دون أخذ موافقة الوزارة.

5- زاول نشاط ترميم الآثار المنقولة لأغراض تجارية دون الحصول على ترخيص من الوزارة، أو خالف شروط الترخيص الممنوح له.

6- قام بعمل من أعمال '),
('boe26-bc85bf873c33d9e6b7b3d7c5','cmpz6ohut0b4pcwg2qc60qcjn','يكون للهيئة رئيس تنفيذي يعين ويعفى بقرار من المجلس بناء على ترشيح من الرئيس، ويحدد القرار أجره ومزاياه المالية الأخرى','2022-03-08'::timestamptz,'قرار مجلس الوزراء رقم 426 وتاريخ 1443/8/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a98158eb-927b-4f8c-a9ff-a9a700f21e78/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (426) وتاريخ 1443/8/5هـ، لتكون بالنص الآتي: "يكون للهيئة رئيس تنفيذي يعين ويعفى بقرار من المجلس بناء على ترشيح من الرئيس، ويحدد القرار أجره ومزاياه المالية الأخرى".'),
('boe26-08d207234272f2e4c30dd8c8','cmpzcuwl007d7vtrk8ju2wtv9','يكون تأديب أعضاء الهيئة من اختصاص دائرة (مجلس التأديب) تشكل في مجلس الهيئة من ثلاثة أعضاء يصدر بتسميتهم قرار من رئيس الهيئة، وتصدر قراراتها بالأغلبية، ولا تكون نهائية إلا بعد موافقة مجلس الهيئة عليها','2015-02-02'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة الخامسة عشرة :

يكون تأديب أعضاء الهيئة من اختصاص دائرة (مجلس التأديب) تشكل في مجلس الهيئة من ثلاثة أعضاء يصدر بتسميتهم قرار من رئيس الهيئة، وتصدر قراراتها بالأغلبية، ولا تكون نهائية إلا بعد موافقة مجلس الهيئة عليها".'),
('boe26-013c722d880072dda3933b60','cmpzcuwl007cuvtrk3vd942nz','تشكل الهيئة من رئيس، ونائب رئيس – أو أكثر – ومن عدد كافٍ من الأعضاء','2015-02-02'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) بتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

" المادة الثانية:
تشكل الهيئة من رئيس، ونائب رئيس – أو أكثر – ومن عدد كافٍ من الأعضاء".'),
('boe26-53dce022a2d7c36a677b7f77','cmpzcuwl007cuvtrk3vd942nz','تشكل النيابة العامة من: النائب العام، ووكيل النيابة العامة، وعدد كافٍ من الأعضاء','2020-05-07'::timestamptz,'مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','-عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "تشكل النيابة العامة من: النائب العام، ووكيل النيابة العامة، وعدد كافٍ من الأعضاء".'),
('boe26-df5c6383dd2ce2abfe7c0670','cmpzcuwl007cxvtrka4e959kv','يكون لعمل أعضاء الهيئة الصفة القضائية، ويتمتعون بالاستقلال التام، ولا يخضعون في عملهم إلا لأحكام الشريعة الإسلامية، والأنظمة المرعية، وليس لأحد التدخل في مجال عملهم.','2015-02-02'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة الخامسة:

يكون لعمل أعضاء الهيئة الصفة القضائية، ويتمتعون بالاستقلال التام، ولا يخضعون في عملهم إلا لأحكام الشريعة الإسلامية، والأنظمة المرعية، وليس لأحد التدخل في مجال عملهم."'),
('boe26-fe54aea3559910ec362f9e26','cmpzcuwl007d1vtrkub0hs4fy','1 - تكون أسماء وظائف أعضاء الهيئة كما يأتي :

- ملازم تحقيق.

- محقق (ج).

- محقق (ب).

- محقق (أ).

- وكيل رئيس دائرة تحقيق وادعاء (ب).

- وكيل رئيس دائرة تحقيق وادعاء (أ).

- رئيس دائرة تحقيق وادعاء (ب).

- رئيس دائرة تحقيق وادعاء (أ).

- مدعي استئناف.

- رئيس دوائر تحقيق وادعاء.

2 - يعامل أعضاء الهيئة من حيث الرواتب والبدلات والمكافآت والمزايا معاملة نظرائهم في نظام القضاء، وذلك وفق جدول معادلة وظائف الهيئة بوظائف القضاة المعتمد نظاماً."

ثانيًا: يكون جدول معادلة وظائف الهيئة بوظائف القضاة – المشار إليه في المادة (التاسعة) من النظام – على النحو الآتي:

وظائف القضاء               وظائف أعضاء الهيئة

ملازم قضائي             ملازم تحقيق

قاضي ج                 محقق ج

قاضي ب                       محقق ب

قاضي أ                          محقق أ

وكيل محكمة ب      وكيل رئيس دائرة تحقيق وادعاء ب

وكيل محكمة أ     وكيل رئيس دائرة تحقيق وادعاء أ

رئيس محكمة ب    رئيس تحقيق وادعاء ب

رئيس محكمة أ    رئيس تحقيق وادعاء أ

قاضي استئناف    مدعي استئناف

رئيس محكمة استئناف  رئيس دوائر تحقيق وادعاء

رئيس المحكمة العليا      ـــــــــــــــــــــــــــــــــــــــــــــــــــــ','2015-02-02'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة التاسعة:

1 - تكون أسماء وظائف أعضاء الهيئة كما يأتي :

- ملازم تحقيق.

- محقق (ج).

- محقق (ب).

- محقق (أ).

- وكيل رئيس دائرة تحقيق وادعاء (ب).

- وكيل رئيس دائرة تحقيق وادعاء (أ).

- رئيس دائرة تحقيق وادعاء (ب).

- رئيس دائرة تحقيق وادعاء (أ).

- مدعي استئناف.

- رئيس دوائر تحقيق وادعاء.

2 - يعامل أعضاء الهيئة من حيث الرواتب والبدلات والمكافآت والمزايا معاملة نظرائهم في نظام القضاء'),
('boe26-579c83d90fb955705b881367','cmpzcuwl007d2vtrk2xkfj540','يعين رئيس الهيئة بمرتبة وزير بأمر ملكي بناءً على ترشيح المشرف من تتوافر فيه الشروط المطلوبة لشغل وظيفة رئيس دوائر تحقيق وادعاء على الأقل.

ويكون شغل وظائف أعضاء الهيئة الأخرى ونقلهم إلى جهات أخرى بأمر ملكي، بناءً على قرار من مجلس الهيئة، وتوصية المشرف.','2015-02-02'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة العاشرة:

يعين رئيس الهيئة بمرتبة وزير بأمر ملكي بناءً على ترشيح المشرف من تتوافر فيه الشروط المطلوبة لشغل وظيفة رئيس دوائر تحقيق وادعاء على الأقل.

ويكون شغل وظائف أعضاء الهيئة الأخرى ونقلهم إلى جهات أخرى بأمر ملكي، بناءً على قرار من مجلس الهيئة، وتوصية المشرف."'),
('boe26-7af50aec8de53d16a52a9de4','cmpzcuwl007d2vtrk2xkfj540','يعين النائب العام بمرتبة وزير بأمر ملكي، ممن تتوافر فيه الشروط المطلوبة لشغل وظيفة رئيس دوائر تحقيق وادعاء على الأقل.

وكون شغل وظائف أعضاء النيابة الأخرى ونقلهم إلى جهات أخرى بأمر ملكي، بناءً على قرار من مجلس النيابة العامة','2020-05-07'::timestamptz,'مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "يعين النائب العام بمرتبة وزير بأمر ملكي، ممن تتوافر فيه الشروط المطلوبة لشغل وظيفة رئيس دوائر تحقيق وادعاء على الأقل.

وكون شغل وظائف أعضاء النيابة الأخرى ونقلهم إلى جهات أخرى بأمر ملكي، بناءً على قرار من مجلس النيابة العامة".'),
('boe26-e989eeceb2ee6817d0aa778c','cmpzcuwl007d5vtrk7whhruwy','في غير حالات الوفاة، وبلوغ السن النظامية، وعدم ثبوت صلاحية العضو خلال فترة التجربة؛ تنتهي خدمة عضو النيابة بأمر ملكي بناء على قرار من مجلس النيابة','2020-05-07'::timestamptz,'مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','-عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "في غير حالات الوفاة، وبلوغ السن النظامية، وعدم ثبوت صلاحية العضو خلال فترة التجربة؛ تنتهي خدمة عضو النيابة بأمر ملكي بناء على قرار من مجلس النيابة".'),
('boe26-a48673973cb04ab43856857a','cmpzcuwl007d9vtrk22o34lqv','يرفع رئيس دائرة التفتيش – أو من ينبيه – الدعوى التأديبية بناء على طلب من النائب العام، ولا تقام هذه الدعوى إلا بناء على تحقيق يتولاه أحد أعضاء النيابة العامة الذي يندبه مجلس النيابة العامة. ويشترط في عضو النيابة العامة الذي يندب للتحقيق أن يكون في مرتبة أعلى من مرتبة العضو المحقق معه أو سابقاً له في الأقدمية إن كانا في مرتبة واحدة','2020-05-07'::timestamptz,'مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "يرفع رئيس دائرة التفتيش – أو من ينبيه – الدعوى التأديبية بناء على طلب من النائب العام، ولا تقام هذه الدعوى إلا بناء على تحقيق يتولاه أحد أعضاء النيابة العامة الذي يندبه مجلس النيابة العامة. ويشترط في عضو النيابة العامة الذي يندب للتحقيق أن يكون في مرتبة أعلى من مرتبة العضو المحقق معه أو سابقاً له في الأقدمية إن كانا في مرتبة واحدة".'),
('boe26-909f40d3bcb8b015d5d5778f','cmpzcuwl007dgvtrkm1ljj6i7','يجب أن يشتمل الحكم في الدعوى التأديبية على الأسباب التي بُني عليها، وأن تتلى أسبابه عند النطق به في جلسة سرية.','2015-02-02'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة الرابعة والعشرون:

يجب أن يشتمل الحكم في الدعوى التأديبية على الأسباب التي بُني عليها، وأن تتلى أسبابه عند النطق به في جلسة سرية."'),
('boe26-54067824466ead1a13135bb1','cmpzcuwl007dhvtrk1hmczbpp','العقوبات التأديبية التي يجوز توقيعها على عضو الهيئة هي :  اللوم، وإنهاء الخدمة.','2015-02-02'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة الخامسة والعشرون:

العقوبات التأديبية التي يجوز توقيعها على عضو الهيئة هي :  اللوم، وإنهاء الخدمة."'),
('boe26-bf5a1806e61bc8730efa749b','cmpzcuwl007divtrk7c0ughkx','تبلغ قرارات مجلس التأديب إلى المشرف، ويصدر أمر ملكي بتنفيذ عقوبة إنهاء الخدمة، وقرار من المشرف بتنفيذ عقوبة اللوم بناءً على توصية رئيس الهيئة.','2015-02-02'::timestamptz,'مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة السادسة والعشرون:

تبلغ قرارات مجلس التأديب إلى المشرف، ويصدر أمر ملكي بتنفيذ عقوبة إنهاء الخدمة، وقرار من المشرف بتنفيذ عقوبة اللوم بناءً على توصية رئيس الهيئة."'),
('boe26-88a9f0ce29a844ac498f5610','cmpzcuwl007divtrk7c0ughkx','ترفع قرارات مجلس التأديب إلى مجلس النيابة العامة؛ للنظر فيها ، ويصدر أمر ملكي بتنفيذ عقوبة إنهاء الخدمة، وقرار من النائب العام بتنفيذ عقوبة اللوم','2020-05-07'::timestamptz,'مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "ترفع قرارات مجلس التأديب إلى مجلس النيابة العامة؛ للنظر فيها ، ويصدر أمر ملكي بتنفيذ عقوبة إنهاء الخدمة، وقرار من النائب العام بتنفيذ عقوبة اللوم".'),
('boe26-7761a9205594f8896913e9ad','cmpzcuwl007djvtrks8y57v6e','دون إخلال بالأحكام المنصوص عليها في هذا النظام، يتولى النائب العام الإشراف الإداري والمالي على النيابة العامة، وله صلاحيات الوزير بالنسبة إلى موظفي النيابة ومستخدميها، وهو المرجع فيما يصدر من النيابة في هذا الشأن إلى جميع الوزارات والجهات الأخرى','2020-05-07'::timestamptz,'مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "دون إخلال بالأحكام المنصوص عليها في هذا النظام، يتولى النائب العام الإشراف الإداري والمالي على النيابة العامة، وله صلاحيات الوزير بالنسبة إلى موظفي النيابة ومستخدميها، وهو المرجع فيما يصدر من النيابة في هذا الشأن إلى جميع الوزارات والجهات الأخرى".'),
('boe26-f03c00bc71b1503009f69ebf','cmpz63ftc03vhcwg2sek4u5mt','تحدد رسوم القيد في  سجل الوكالات    كالآتي:

خمسمائة ريال للتاجر الفرد والشركة.
وتدفع الرسوم لمرة واحدة.','1973-04-23'::timestamptz,'مرسوم ملكي رقم م/8 وتاريخ 20/3/1393هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b19a8aa6-7b50-43f0-ab8c-a9a700f1a446/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/8) وتاريخ 20 / 3 / 1393 هـ ، لتصبح بالنص الآتي:

" تحدد رسوم القيد في  سجل الوكالات    كالآتي:

خمسمائة ريال للتاجر الفرد والشركة.
وتدفع الرسوم لمرة واحدة."'),
('boe26-33c8b318ee2697e4b1576c4d','cmpz63fne03vfcwg2g2y4r4h4','كل من يخالف أحكام هذا النظام ولائحته التنفيذية يعاقب بغرامة لا تقل عن خمسة آلاف ريال ولا تتجاوز خمسين ألف ريال مع نشر العقوبة على نفقة المخالف وذلك دون إخلال بحق من لحقه ضرر من المخالفة في المطالبة بالتعويض.
فإن كانت المخالفة منسوبة لأجنبي أو لشركة سعودية فيها شريك أو أكثر غير سعودي أصبحت العقوبة بالإضافة إلى الغرامة تصفية الأعمال إداريا مع جواز الحرمان من ممارسة التجارة دائما أو لمدة معنية، ويجوز   لوزير الداخلية    الأمر   بترحيل الأجنبي    من البلاد في ضوء العقوبة المحكوم بها، وعلى   وزارة التجارة    إبلاغه عن الأجنبي أو الشريك الغير سعودي.','1980-06-23'::timestamptz,'مرسوم ملكي رقم م/32 وتاريخ 10/8/1400هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b19a8aa6-7b50-43f0-ab8c-a9a700f1a446/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/32) بتاريخ 10 / 8 / 1400 هـ ، لتكون كما يلى :

كل من يخالف أحكام هذا النظام ولائحته التنفيذية يعاقب بغرامة لا تقل عن خمسة آلاف ريال ولا تتجاوز خمسين ألف ريال مع نشر العقوبة على نفقة المخالف وذلك دون إخلال بحق من لحقه ضرر من المخالفة في المطالبة بالتعويض.
فإن كانت المخالفة منسوبة لأجنبي أو لشركة سعودية فيها شريك أو أكثر غير سعودي أصبحت العقوبة بالإضافة إلى الغرامة تصفية الأعمال إداريا مع جواز الحرمان من ممارسة التجارة دائما أو لمدة معنية، ويجوز   لوزير '),
('boe26-13366ef05b3fa51a606328f8','cmpz801va0cad7b6w4zoex1at','( تحديد الراتب الشهري للوزراء ومن في مرتبتهم بخمسة وأربعين ألف ريال ).','1981-07-29'::timestamptz,'مرسوم ملكي رقم م/40 وتاريخ 28/9/1401هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b2a002e4-a3da-474b-9735-a9a700f2386c/1','عدلت هذه المادة عدة تعديلات كان آخرها بالمرسوم الملكي رقم (م/40) وتاريخ 28 / 9 / 1401 هـ ، لتصبح بالنص التالى :

( تحديد الراتب الشهري للوزراء ومن في مرتبتهم بخمسة وأربعين ألف ريال ).'),
('boe26-f1c0bf3288752002b2d5cf65','cmpz8020j0caf7b6wz94tzk99','( يُحدَّد الراتب الشهري لنواب الوزراء وموظفي المرتبة المُمتازة بثلاثين ألف ريال) .','1981-07-29'::timestamptz,'مرسوم ملكي رقم م/40 وتاريخ 28/9/1401هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b2a002e4-a3da-474b-9735-a9a700f2386c/1','عدلت هذه المادة عدة تعديلات كان آخرها بالمرسوم الملكي رقم (م/40) وتاريخ 28 / 9 / 1401 هـ ، لتصبح بالنص التالى :

( يُحدَّد الراتب الشهري لنواب الوزراء وموظفي المرتبة المُمتازة بثلاثين ألف ريال) .'),
('boe26-b0c111ee8ea8bf0d48cc73eb','cmpz8025t0cah7b6wxkrc7fol','4-

أ- تُمنح إجازة سنوية للوزراء ومن هم في مرتبة وزير والمرتبة الممتازة، وتُحدد مدتها لكل فئة بأمر من رئيس مجلس الوزراء.

ب- يوافق رئيس مجلس الوزراء على طلب التمتع بالإجازة للوزراء، ولمن هم في مرتبة وزير أو المرتبة الممتازة، ويستثنى من ذلك ما يأتي:

ما يتصل بلطب التمتع بالإجازة لمن هم في مرتبة وزير أو المرتبة الممتازة من منسوبي أي وزارة والأجهزة المرتبطة بتلك الوزارة أو وزيرها، فيوافق الوزير عليه.

ما يتصل بطلب التمتع بالإجازة لمن هم في مرتبة وزير أو المرتبة الممتازة من منسوبي أي جهاز مستقل يرتبط مباشرة بالملك أو برئيس مجلس الوزراء والأجهزة المرتبطة بذلك الجهاز أو رئيسه، فيوافق رئيس الجهاز المستقل عليه','2021-02-25'::timestamptz,'مرسوم ملكي رقم م/56 وتاريخ 1442/7/13هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b2a002e4-a3da-474b-9735-a9a700f2386c/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/56) وتاريخ 1442/7/13هـ. لتصبح بالنص الآتي:

"4-

أ- تُمنح إجازة سنوية للوزراء ومن هم في مرتبة وزير والمرتبة الممتازة، وتُحدد مدتها لكل فئة بأمر من رئيس مجلس الوزراء.

ب- يوافق رئيس مجلس الوزراء على طلب التمتع بالإجازة للوزراء، ولمن هم في مرتبة وزير أو المرتبة الممتازة، ويستثنى من ذلك ما يأتي:

ما يتصل بلطب التمتع بالإجازة لمن هم في مرتبة وزير أو المرتبة الممتازة من منسوبي أي وزارة والأجهزة المرتبطة بتلك الوزارة أو وزيرها، فيوافق الوزير عليه.

م'),
('boe26-b5741813c5cae93a67930bec','cmpz5yvtz02dzcwg2kamjt5yn','تعقد اللجنة اجتماعين عاديين كل عام، ويحق لرئيس اللجنة أو لنصف الأعضاء دعوة اللجنة إلى عقد اجتماعات غير عادية','2021-11-16'::timestamptz,'قرار مجلس الوزراء رقم 211 وتاريخ 1443/4/11هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b2c545f0-d65f-4c13-b712-a9a700f193b6/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (211) وتاريخ 1443/4/11هـ، لتكون بالنص الآتي:

"تعقد اللجنة اجتماعين عاديين كل عام، ويحق لرئيس اللجنة أو لنصف الأعضاء دعوة اللجنة إلى عقد اجتماعات غير عادية".'),
('boe26-c933e3afb248030e0c969535','cmpz62drh03ivcwg224kqp4i1','يكون لصاحب البيانات الشخصية -وفقاً للأحكام الواردة في النظام وما تحدده اللوائح- الحقوق الآتية:

1- الحق في العلم، ويشمل ذلك إحاطته علماً بالمسوغ النظامي لجمع بياناته الشخصية والغرض من جمعها.

2- الحق في وصوله إلى بياناته الشخصية المتوافرة لدى جهة التحكم، وفق الضوابط والإجراءات التي تحددها اللوائح، ودون إخلال بما ورد في المادة (التاسعة) من النظام.

3- الحق في طلب الحصول على بياناته الشخصية المتوافرة لدى جهة التحكم بصيغة مقروءة وواضحة، وفق الضوابط والإجراءات التي تحددها اللوائح.

4- الحق في طلب تصحيح بياناته الشخصية المتوافرة لدى جهة التحكم، أو إتمامها، أو تحديثها.

5- الحق في طلب إتلاف بياناته الشخصية المتوافرة لدى جهة التحكم مما انتهت الحاجة إليه منها، وذلك دون إخلال بما تقضي به المادة (الثامنة عشرة) من النظام.','2023-03-27'::timestamptz,'مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي: "يكون لصاحب البيانات الشخصية -وفقاً للأحكام الواردة في النظام وما تحدده اللوائح- الحقوق الآتية:

1- الحق في العلم، ويشمل ذلك إحاطته علماً بالمسوغ النظامي لجمع بياناته الشخصية والغرض من جمعها.

2- الحق في وصوله إلى بياناته الشخصية المتوافرة لدى جهة التحكم، وفق الضوابط والإجراءات التي تحددها اللوائح، ودون إخلال بما ورد في المادة (التاسعة) من النظام.

3- الحق في طلب الحصول على بياناته الشخصية المتوافرة لد'),
('boe26-2aa960d142d623d1900b340d','cmpz62efa03j3cwg2n7g4zaf7','مع مراعاة ما ينص عليه النظام واللوائح في شأن الإفصاح عن البيانات الشخصية، على جهة التحكم عند اختيارها جهة المعالجة أن تلتزم باختيار الجهة التي توفر الضمانات اللازمة لتنفيذ أحكام النظام واللوائح، وعليها التحقق من التزام تلك الجهة بأحكام النظام واللوائح، ولا يخل ذلك بمسؤولياتها تجاه صاحب البيانات الشخصية أو الجهة المختصة بحسب الأحوال. وتحدد اللوائح الأحكام اللازمة لذلك، على أن تشتمل على الأحكام المتعلقة بأي تعاقدات لاحقة تقوم بها جهة المعالجة','2023-03-27'::timestamptz,'مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي: "مع مراعاة ما ينص عليه النظام واللوائح في شأن الإفصاح عن البيانات الشخصية، على جهة التحكم عند اختيارها جهة المعالجة أن تلتزم باختيار الجهة التي توفر الضمانات اللازمة لتنفيذ أحكام النظام واللوائح، وعليها التحقق من التزام تلك الجهة بأحكام النظام واللوائح، ولا يخل ذلك بمسؤولياتها تجاه صاحب البيانات الشخصية أو الجهة المختصة بحسب الأحوال. وتحدد اللوائح الأحكام اللازمة لذلك، على أن تشتمل على الأحكام المتعلقة'),
('boe26-0993af39b55ea67cdf7593d0','cmpz62er703j7cwg2lkj4svm6','لا يجوز لجهة التحكم جمع البيانات الشخصية إلا من صاحبها مباشرةً، ولا تجوز مُعالجة تلك البيانات إلا لتحقيق الغرض الذي جُمعت من أجله. ومع ذلك، يجوز لجهة التحكم جمع البيانات الشخصية من غير صاحبها مباشرةً، أو مُعالجتها لغرض آخر غير الذي جمعت من أجله، وذلك في الأحوال الآتية:

1- إذا وافق صاحب البيانات الشخصية على ذلك، وفقاً لأحكام النظام.

2- إذا كانت البيانات الشخصية متاحة للعموم، أو جرى جمعها من مصدر متاح للعموم.

3- إذا كانت جهة التحكم جهة عامة، وكان جمع البيانات الشخصية أومعالجتها؛ مطلوباً لأغراض المصلحة العامة أو لأغراض أمنية أو لتنفيذ نظام آخر أو لاستيفاء مُتطلبات قضائية.

4- إذا كان التقيد بهذا الحظر قد يُلحق ضرراً بصاحب البيانات الشخصية أو يؤثر على مصالحه الحيوية.

5- إذا كان جمع البيانات الشخصية أو معالجتها ضروريا ً لحماية الصحة العامة أو السلامة العامة أو حماية حياة فرد أو أفراد معينين أو حماية صحتهم.

6- إذا كانت البيانات الشخصية لن تُسجل أو تُحفظ في صيغة تجعل من الممكن تحديد هوية صاحبها ومعرفته بصورة مباشرة أو غير مباشرة.

7- إذا كان جمع البيانات الشخصية أو معالجتها ضرورياً لتحقيق مصالح مشروعة لجهة التحكم، ما لم يخل ذلك بحقوق صاحب البيانات الشخصية أو يتعارض مع مصالحه ولم تكن تلك البيانات بيانات حساسة.','2023-03-27'::timestamptz,'مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي: "لا يجوز لجهة التحكم جمع البيانات الشخصية إلا من صاحبها مباشرةً، ولا تجوز مُعالجة تلك البيانات إلا لتحقيق الغرض الذي جُمعت من أجله. ومع ذلك، يجوز لجهة التحكم جمع البيانات الشخصية من غير صاحبها مباشرةً، أو مُعالجتها لغرض آخر غير الذي جمعت من أجله، وذلك في الأحوال الآتية:

1- إذا وافق صاحب البيانات الشخصية على ذلك، وفقاً لأحكام النظام.

2- إذا كانت البيانات الشخصية متاحة للعموم، أو جرى جمعها من مصدر متاح'),
('boe26-b36d1cf664abfa4d91b165c2','cmpz62f3303jbcwg2gta5w5rk','على جهة التحكم أن تعتمد سياسة للخصوصية، وأن تجعلها متاحة لأصحاب البيانات الشخصية ليطلعوا عليها عند جمع بياناتهم. على أن تشتمل تلك السياسة على تحديد الغرض من جمعها، ومُحتوى البيانات الشخصية المطلوب جمعها، وطريقة جمعها، ووسيلة حفظها، وكيفية معالجتها، وكيفية إتلافها، وحقوق صاحبها فيما يتعلق بها، وكيفية ممارسة هذه الحقوق','2023-03-27'::timestamptz,'مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي:

" على جهة التحكم أن تعتمد سياسة للخصوصية، وأن تجعلها متاحة لأصحاب البيانات الشخصية ليطلعوا عليها عند جمع بياناتهم. على أن تشتمل تلك السياسة على تحديد الغرض من جمعها، ومُحتوى البيانات الشخصية المطلوب جمعها، وطريقة جمعها، ووسيلة حفظها، وكيفية معالجتها، وكيفية إتلافها، وحقوق صاحبها فيما يتعلق بها، وكيفية ممارسة هذه الحقوق".'),
('boe26-676811d7bcbf90e47adcbe33','cmpz62geo03jrcwg2srv8er1t','1- تشعر جهة التحكم الجهة المختصة عند علمها بحدوث تسرب لبيانات شخصية أو تلفها أو وصول غير مشروع إليها؛ وفقاً لما تحدده اللوائح.

2- تشعر جهة التحكم صاحب البيانات الشخصية إذا كان من شأن حدوث تسرب لبيانات شخصية أو تلفها أو وصول غير مشروع إليها أن يرتب ضرراً على بياناته أو يتعارض مع حقوقه أو مصالحه؛ وفقاً لما تحدده اللوائح','2023-03-27'::timestamptz,'مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي:

"1- تشعر جهة التحكم الجهة المختصة عند علمها بحدوث تسرب لبيانات شخصية أو تلفها أو وصول غير مشروع إليها؛ وفقاً لما تحدده اللوائح.

2- تشعر جهة التحكم صاحب البيانات الشخصية إذا كان من شأن حدوث تسرب لبيانات شخصية أو تلفها أو وصول غير مشروع إليها أن يرتب ضرراً على بياناته أو يتعارض مع حقوقه أو مصالحه؛ وفقاً لما تحدده اللوائح".'),
('boe26-3e9c17a42e65e821400bfccf','cmpz62k1v03kzcwg27wvvzuk7','يصدر رئيس الجهة المختصة اللوائح، وذلك في مدة لا تتجاوز (سبعمائة وعشرين) يوماً من تاريخ صدور النظام، على أن يُنسِّق -قبل إصدارها- مع: (وزارة الاتصالات وتقنية المعلومات، ووزارة الخارجية، وهيئة الاتصالات والفضاء والتقنية، وهيئة الحكومة الرقمية، والهيئة الوطنية للأمن السيبراني، والمجلس الصحي السعودي، والبنك المركزي السعودي)، كلٌّ فيما يخصه.','2023-03-27'::timestamptz,'مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي: 

"يصدر رئيس الجهة المختصة اللوائح، وذلك في مدة لا تتجاوز (سبعمائة وعشرين) يوماً من تاريخ صدور النظام، على أن يُنسِّق -قبل إصدارها- مع: (وزارة الاتصالات وتقنية المعلومات، ووزارة الخارجية، وهيئة الاتصالات والفضاء والتقنية، وهيئة الحكومة الرقمية، والهيئة الوطنية للأمن السيبراني، والمجلس الصحي السعودي، والبنك المركزي السعودي)، كلٌّ فيما يخصه."'),
('boe26-0f0fdba803b9d6f9d64aee80','cmpzcvb5i0be5vtrkanic9kv4','يجوز في حالة النقل من دائرة جمركية إلى أخرى إعفاء أصحاب العلاقة من تقديم بيان جمركي تفصيلي في مركز الدخول، وتتم الإحالة وفق المستندات والشروط التي يحددها المدير العام".','2024-01-21'::timestamptz,'مرسوم ملكي رقم م/124 وتاريخ 1445/7/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b93d0275-775f-482a-9d52-a9a700f2ca15/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/124) وتاريخ 1445/7/9هـ، لتصبح على النحو الآتي:

المادة (72): "يجوز في حالة النقل من دائرة جمركية إلى أخرى إعفاء أصحاب العلاقة من تقديم بيان جمركي تفصيلي في مركز الدخول، وتتم الإحالة وفق المستندات والشروط التي يحددها المدير العام".'),
('boe26-03f9fddbf578db44bb84e4f9','cmpzcvb5i0bezvtrknf2899kk','يعفى من الضرائب (الرسوم) الجمركية ما يلي:

أ- مستوردات القوات المسلحة وقوى الأمن الداخلي بجميع قطاعاتها من ذخائر وأسلحة وتجهيزات ووسائط نقل عسكرية وقطعها وأي مادة أخرى بقرار من مجلس الوزراء أو من الجهة المخولة بذلك في كل دولة.

ب- مستوردات الجمارك ذات الطابع الأمني بقرار من مجلس الوزراء أو من الجهة المخولة بذلك في كل دولة".','2024-01-21'::timestamptz,'مرسوم ملكي رقم م/124 وتاريخ 1445/7/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b93d0275-775f-482a-9d52-a9a700f2ca15/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/124) وتاريخ 1445/7/9هـ، لتصبح بالنص الآتي:

المادة (102): "يعفى من الضرائب (الرسوم) الجمركية ما يلي:

أ- مستوردات القوات المسلحة وقوى الأمن الداخلي بجميع قطاعاتها من ذخائر وأسلحة وتجهيزات ووسائط نقل عسكرية وقطعها وأي مادة أخرى بقرار من مجلس الوزراء أو من الجهة المخولة بذلك في كل دولة.

ب- مستوردات الجمارك ذات الطابع الأمني بقرار من مجلس الوزراء أو من الجهة المخولة بذلك في كل دولة".'),
